// Assemble the app-facing schema; English ingredient lines stay parser-ready.
function mk(s) {
  const ingredients = {};
  LANGS.forEach(l => {
    ingredients[l] = s.ing.map(it => {
      const qty = it.q != null ? String(it.q) : '';
      const unit = it.u ? unitStr(it.u, it.q, l) : '';
      // Piece-counted nouns (a count with no mass/volume unit) take the plural
      // when qty>1: "2 Ceapă" → "2 Cepe". Only locales with a plural override
      // switch; every other locale — and English, whose text drives the
      // shopping-list parser — keeps the singular base.
      const plural = it.q > 1 && !it.u && it.n.plural && it.n.plural[l];
      const name = plural || it.n[l] || it.n.en;
      return [qty, unit, name].filter(Boolean).join(' ');
    });
  });
  return {
    id: s.id, name: s.name, origin: RO_ORIGIN, category: CAT,
    servings: s.servings, time: s.prep + s.cook,
    costRon: s.costRon, nutrition: s.nut, tags: s.tags,
    ingredients, howIsMade: s.steps,
  };
}

const SPECS = [
  { id:'budget_001', name:NAMES.ciorba, servings:2, prep:15, cook:70, costRon:5, nut:{cal:320,prot:16,carb:50,fat:6,fib:14}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.whiteBeans}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:100,u:'g',n:I.celery}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'tbsp',n:I.passata}, {q:1,n:I.bayLeaf}, {q:1.5,u:'l',n:I.water}, {q:1,n:I.lemon}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești fasole uscată, las-o peste noapte în apă rece, apoi scurge-o. Pune fasolea într-o oală mare cu apă proaspătă, dă în clocot, ia spuma cu o lingură și fierbe circa 45 de minute, până e aproape moale. Între timp, toacă mărunt ceapa, morcovul și țelina și călește-le în ulei 5 minute, apoi adaugă boiaua și roșiile pasate și mai gătește 2 minute. Pune această bază peste fasole împreună cu foaia de dafin și un praf bun de sare și fierbe încă 20 de minute, până fasolea e moale, iar ciorba prinde corp. Acrește după gust cu zeamă de lămâie — asta o face „ciorbă" — și potrivește sarea. Presară pătrunjel tocat și servește fierbinte, cu pâine.',
      en:'If using dried beans, soak them overnight in cold water, then drain. Put the beans in a large pot with fresh water, bring to a boil, skim off the foam, and simmer for about 45 minutes until nearly tender. Meanwhile, finely chop the onion, carrot and celery and soften them in the oil for 5 minutes, then stir in the paprika and tomato passata and cook for 2 more minutes. Add this base to the beans with the bay leaf and a good pinch of salt, and simmer for another 20 minutes, until the beans are soft and the soup has body. Sour it to taste with a squeeze of lemon — this is what makes it a ciorbă — and adjust the salt. Scatter over the chopped parsley and serve hot with bread.',
      es:'Si usas alubias secas, remójalas toda la noche en agua fría y escúrrelas. Ponlas en una olla grande con agua limpia, lleva a ebullición, retira la espuma y cuece unos 45 minutos hasta que estén casi tiernas. Mientras, pica fino la cebolla, la zanahoria y el apio y sofríelos en el aceite 5 minutos, luego añade el pimentón y el tomate y cocina 2 minutos más. Agrega esta base a las alubias con la hoja de laurel y una buena pizca de sal, y cuece otros 20 minutos, hasta que estén blandas y la sopa tenga cuerpo. Acidúlala al gusto con un chorro de limón —eso la convierte en ciorbă— y ajusta la sal. Espolvorea el perejil picado y sirve caliente con pan.',
      fr:'Si vous utilisez des haricots secs, faites-les tremper une nuit à l’eau froide, puis égouttez. Mettez-les dans une grande casserole d’eau fraîche, portez à ébullition, écumez et laissez mijoter environ 45 minutes jusqu’à ce qu’ils soient presque tendres. Pendant ce temps, hachez finement l’oignon, la carotte et le céleri et faites-les revenir dans l’huile 5 minutes, puis ajoutez le paprika et les tomates passées et poursuivez 2 minutes. Ajoutez cette base aux haricots avec la feuille de laurier et une bonne pincée de sel, et laissez mijoter encore 20 minutes, jusqu’à ce que les haricots soient tendres et la soupe ait du corps. Acidulez au goût d’un filet de citron — c’est ce qui en fait une ciorbă — et rectifiez le sel. Parsemez de persil haché et servez chaud avec du pain.',
      de:'Bei getrockneten Bohnen diese über Nacht in kaltem Wasser einweichen und abgießen. Die Bohnen mit frischem Wasser in einen großen Topf geben, aufkochen, den Schaum abschöpfen und etwa 45 Minuten köcheln, bis sie fast weich sind. Währenddessen Zwiebel, Karotte und Sellerie fein hacken und im Öl 5 Minuten anschwitzen, dann Paprikapulver und passierte Tomaten einrühren und 2 Minuten weiterkochen. Diese Basis mit dem Lorbeerblatt und einer guten Prise Salz zu den Bohnen geben und weitere 20 Minuten köcheln, bis die Bohnen weich sind und die Suppe Körper hat. Nach Geschmack mit einem Spritzer Zitrone säuern — das macht sie zur Ciorbă — und salzen. Mit gehackter Petersilie bestreuen und heiß mit Brot servieren.',
      pt:'Se usar feijão seco, demolhe-o de um dia para o outro em água fria e escorra. Coloque o feijão numa panela grande com água fresca, deixe ferver, retire a espuma e cozinhe cerca de 45 minutos até ficar quase macio. Entretanto, pique fino a cebola, a cenoura e o aipo e refogue no óleo 5 minutos, depois junte o colorau e o tomate passata e cozinhe mais 2 minutos. Junte esta base ao feijão com a folha de louro e uma boa pitada de sal, e cozinhe mais 20 minutos, até o feijão ficar macio e a sopa ganhar corpo. Acidule a gosto com sumo de limão — é o que a torna uma ciorbă — e acerte o sal. Polvilhe com salsa picada e sirva quente com pão.',
      ru:'Если используете сухую фасоль, замочите её на ночь в холодной воде и слейте. Положите фасоль в большую кастрюлю со свежей водой, доведите до кипения, снимите пену и варите около 45 минут почти до мягкости. Тем временем мелко нарежьте лук, морковь и сельдерей и обжарьте в масле 5 минут, затем вмешайте паприку и протёртые томаты и готовьте ещё 2 минуты. Добавьте эту основу к фасоли с лавровым листом и хорошей щепоткой соли и варите ещё 20 минут, пока фасоль не станет мягкой, а суп — насыщенным. Подкислите по вкусу соком лимона — именно это делает его чорбой — и посолите. Посыпьте рубленой петрушкой и подавайте горячим с хлебом.',
      ar:'إن استخدمت الفاصوليا الجافة، انقعها ليلة كاملة في ماء بارد ثم صفّها. ضع الفاصوليا في قدر كبير مع ماء جديد، اغلها وأزل الرغوة، واطهها نحو 45 دقيقة حتى تقترب من النضج. في هذه الأثناء افرم البصل والجزر والكرفس ناعماً وشوّحها في الزيت 5 دقائق، ثم أضف البابريكا والطماطم المهروسة واطهها دقيقتين إضافيتين. أضف هذا الأساس إلى الفاصوليا مع ورقة الغار ورشة ملح جيدة، واطهها 20 دقيقة أخرى حتى تلين الفاصوليا وتكتسب الشوربة قواماً. حمّضها حسب الذوق بعصير الليمون — وهذا ما يجعلها «تشوربا» — واضبط الملح. انثر البقدونس المفروم وقدّمها ساخنة مع الخبز.',
      zh:'若用干豆，先用冷水浸泡一夜后沥干。把豆子放入大锅加清水煮开，撇去浮沫，小火煮约45分钟至将熟。同时把洋葱、胡萝卜和芹菜切碎，用油炒5分钟，加入红椒粉和番茄泥再炒2分钟。将这个底料连同香叶和一大撮盐一起倒入豆子中，再煮20分钟，至豆软、汤浓。按口味挤入柠檬汁增酸——这正是它成为“酸汤（ciorbă）”的关键——再调盐。撒上切碎的欧芹，趁热配面包食用。',
      ja:'乾燥豆を使う場合は一晩冷水に浸してから水を切る。豆を大きめの鍋に入れて新しい水を注ぎ、沸騰させてアクを取り、約45分ほぼ柔らかくなるまで煮る。その間に玉ねぎ、にんじん、セロリをみじん切りにして油で5分炒め、パプリカとトマトピューレを加えてさらに2分炒める。このベースを豆にローリエと塩ひとつまみとともに加え、さらに20分、豆が柔らかくスープにコクが出るまで煮る。好みでレモンを搾って酸味をつける——これが「チョルバ」たるゆえん——塩で調える。刻んだパセリを散らし、パンを添えて熱いうちに供する。',
      hi:'सूखी बीन्स इस्तेमाल कर रहे हों तो रातभर ठंडे पानी में भिगोकर छान लें। बीन्स को बड़े बर्तन में ताज़े पानी के साथ डालकर उबालें, झाग हटाएँ और लगभग 45 मिनट लगभग नरम होने तक पकाएँ। इस बीच प्याज़, गाजर और सेलेरी बारीक काटकर तेल में 5 मिनट भूनें, फिर पेपरिका और टमाटर प्यूरी डालकर 2 मिनट और पकाएँ। यह बेस बीन्स में तेज पत्ता और अच्छी चुटकी नमक के साथ डालें और 20 मिनट और पकाएँ, जब तक बीन्स नरम और सूप गाढ़ा हो। स्वादानुसार नींबू निचोड़कर खट्टा करें — यही इसे „चोरबा" बनाता है — और नमक ठीक करें। कटा हरा धनिया छिड़कें और ब्रेड के साथ गरम परोसें।',
      tr:'Kuru fasulye kullanıyorsanız gece boyu soğuk suda ıslatıp süzün. Fasulyeyi büyük bir tencerede taze suyla kaynatın, köpüğünü alın ve neredeyse yumuşayana dek yaklaşık 45 dakika pişirin. Bu sırada soğan, havuç ve kerevizi ince doğrayıp yağda 5 dakika kavurun, sonra toz biberi ve domates püresini ekleyip 2 dakika daha pişirin. Bu harcı defne yaprağı ve iyi bir tutam tuzla fasulyeye ekleyin ve fasulye yumuşayıp çorba kıvam alana dek 20 dakika daha pişirin. Damak tadınıza göre limon sıkarak ekşitin — onu „çorba" yapan budur — ve tuzu ayarlayın. Kıyılmış maydanoz serpip ekmekle sıcak servis edin.',
      it:'Se usi fagioli secchi, mettili in ammollo una notte in acqua fredda, poi scola. Metti i fagioli in una pentola capiente con acqua fresca, porta a bollore, schiuma e fai sobbollire circa 45 minuti finché sono quasi teneri. Intanto trita fine cipolla, carota e sedano e falli appassire nell’olio 5 minuti, poi unisci la paprica e la passata e cuoci altri 2 minuti. Aggiungi questa base ai fagioli con l’alloro e una buona presa di sale, e fai sobbollire altri 20 minuti, finché i fagioli sono morbidi e la zuppa ha corpo. Acidula a piacere con una spremuta di limone — è ciò che la rende una ciorbă — e regola il sale. Cospargi di prezzemolo tritato e servi calda con pane.',
      ko:'말린 콩을 쓰면 찬물에 하룻밤 불린 뒤 물을 뺀다. 콩을 큰 냄비에 새 물과 함께 넣고 끓여 거품을 걷어내고 약 45분간 거의 익을 때까지 끓인다. 그동안 양파, 당근, 셀러리를 곱게 다져 기름에 5분 볶고 파프리카 가루와 토마토 퓌레를 넣어 2분 더 볶는다. 이 베이스를 월계수 잎, 소금 넉넉히 한 꼬집과 함께 콩에 넣고 콩이 부드러워지고 국물에 깊이가 생길 때까지 20분 더 끓인다. 기호대로 레몬을 짜 신맛을 낸다 — 이것이 „초르버"를 만드는 핵심이다 — 소금으로 간한다. 다진 파슬리를 뿌려 빵과 함께 뜨겁게 낸다.' } },

  { id:'budget_002', name:NAMES.tocanita, servings:2, prep:10, cook:30, costRon:3, nut:{cal:350,prot:7,carb:60,fat:10,fib:6}, tags:['budget','vegan','one-pot'],
    ing:[ {q:600,u:'g',n:I.potatoes}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'clove',n:I.garlic}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {q:300,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Curăță cartofii și taie-i cuburi de o îmbucătură. Încălzește uleiul într-o oală și călește ceapa tocată la foc mediu 5 minute, până se înmoaie și se rumenește. Adaugă boiaua și usturoiul și amestecă 30 de secunde — nu lăsa boiaua să ardă, că amărăște — apoi pune roșiile pasate și foaia de dafin. Adaugă cartofii, apa și un praf bun de sare, amestecă să se acopere, apoi fierbe acoperit, la foc mic, circa 25 de minute, până cartofii sunt fragezi și sosul s-a legat. Scutură oala din când în când în loc să amesteci tare, ca să rămână cartofii întregi. Servește fierbinte, simplu sau cu o lingură de smântână, dacă ai.',
      en:'Peel the potatoes and cut them into bite-sized chunks. Warm the oil in a pot and cook the chopped onion over medium heat for 5 minutes, until soft and golden. Stir in the paprika and garlic and cook for 30 seconds — don’t let the paprika burn or it turns bitter — then add the tomato passata and bay leaf. Add the potatoes, water and a good pinch of salt, stir to coat, then simmer covered over low heat for about 25 minutes, until the potatoes are tender and the sauce has thickened. Shake the pot now and then rather than stirring hard, so the potatoes stay whole. Serve hot, on its own or with a spoon of soured cream if you have it.',
      es:'Pela las patatas y córtalas en trozos de un bocado. Calienta el aceite en una olla y sofríe la cebolla picada a fuego medio 5 minutos, hasta que esté blanda y dorada. Añade el pimentón y el ajo y remueve 30 segundos —no dejes que el pimentón se queme o amarga— luego incorpora el tomate y la hoja de laurel. Añade las patatas, el agua y una buena pizca de sal, remueve para cubrir y cuece tapado a fuego bajo unos 25 minutos, hasta que las patatas estén tiernas y la salsa haya espesado. Agita la olla de vez en cuando en lugar de remover fuerte, para que las patatas queden enteras. Sirve caliente, solo o con una cucharada de nata agria si tienes.',
      fr:'Épluchez les pommes de terre et coupez-les en morceaux d’une bouchée. Chauffez l’huile dans une casserole et faites revenir l’oignon haché à feu moyen 5 minutes, jusqu’à ce qu’il soit tendre et doré. Ajoutez le paprika et l’ail et remuez 30 secondes — sans laisser brûler le paprika, sinon il devient amer — puis ajoutez les tomates passées et la feuille de laurier. Ajoutez les pommes de terre, l’eau et une bonne pincée de sel, mélangez pour enrober, puis laissez mijoter à couvert à feu doux environ 25 minutes, jusqu’à ce que les pommes de terre soient tendres et la sauce épaissie. Secouez la casserole de temps en temps plutôt que de remuer fort, pour garder les pommes de terre entières. Servez chaud, seul ou avec une cuillerée de crème aigre si vous en avez.',
      de:'Die Kartoffeln schälen und in mundgerechte Stücke schneiden. Das Öl in einem Topf erwärmen und die gehackte Zwiebel bei mittlerer Hitze 5 Minuten anschwitzen, bis sie weich und goldbraun ist. Paprikapulver und Knoblauch einrühren und 30 Sekunden anrösten — das Paprikapulver nicht verbrennen lassen, sonst wird es bitter — dann passierte Tomaten und Lorbeerblatt zugeben. Kartoffeln, Wasser und eine gute Prise Salz zugeben, umrühren, dann zugedeckt bei niedriger Hitze etwa 25 Minuten köcheln, bis die Kartoffeln weich sind und die Soße gebunden ist. Den Topf ab und zu schwenken statt kräftig zu rühren, damit die Kartoffeln ganz bleiben. Heiß servieren, pur oder mit einem Löffel Schmand, falls vorhanden.',
      pt:'Descasque as batatas e corte-as em pedaços de uma dentada. Aqueça o óleo numa panela e refogue a cebola picada em lume médio 5 minutos, até ficar macia e dourada. Junte o colorau e o alho e mexa 30 segundos — não deixe o colorau queimar, senão amarga — depois adicione o tomate passata e a folha de louro. Junte as batatas, a água e uma boa pitada de sal, mexa para envolver e cozinhe tapado em lume brando cerca de 25 minutos, até as batatas ficarem macias e o molho engrossar. Abane a panela de vez em quando em vez de mexer com força, para as batatas ficarem inteiras. Sirva quente, simples ou com uma colher de natas azedas se tiver.',
      ru:'Очистите картофель и нарежьте кусочками на один укус. Разогрейте масло в кастрюле и обжарьте нарезанный лук на среднем огне 5 минут, до мягкости и золотистости. Вмешайте паприку и чеснок и готовьте 30 секунд — не дайте паприке подгореть, иначе будет горчить — затем добавьте протёртые томаты и лавровый лист. Добавьте картофель, воду и хорошую щепотку соли, перемешайте, затем тушите под крышкой на слабом огне около 25 минут, пока картофель не станет мягким, а соус не загустеет. Время от времени встряхивайте кастрюлю вместо энергичного помешивания, чтобы картофель остался целым. Подавайте горячим, сам по себе или с ложкой сметаны, если есть.',
      ar:'قشّر البطاطس وقطّعها مكعبات بحجم اللقمة. سخّن الزيت في قدر وشوّح البصل المفروم على نار متوسطة 5 دقائق حتى يلين ويكتسب لوناً ذهبياً. أضف البابريكا والثوم وقلّب 30 ثانية — دون أن تحترق البابريكا وإلا صارت مرّة — ثم أضف الطماطم المهروسة وورقة الغار. أضف البطاطس والماء ورشة ملح جيدة، قلّب حتى تتغلّف، ثم اطهها مغطاة على نار هادئة نحو 25 دقيقة حتى تنضج البطاطس وتتماسك الصلصة. هزّ القدر بين الحين والآخر بدل التقليب القوي كي تبقى البطاطس كاملة. قدّمها ساخنة، وحدها أو مع ملعقة قشدة حامضة إن توفّرت.',
      zh:'土豆去皮，切成一口大小的块。锅中热油，中火炒切碎的洋葱5分钟，至变软金黄。加入红椒粉和蒜炒30秒——别让红椒粉烧焦，否则发苦——再加入番茄泥和香叶。放入土豆、水和一大撮盐，翻拌均匀，然后加盖小火煮约25分钟，至土豆软、汤汁收浓。中途晃动锅子而不要用力翻搅，让土豆保持完整。趁热食用，可单吃或加一勺酸奶油。',
      ja:'じゃがいもの皮をむき、一口大に切る。鍋に油を温め、みじん切りの玉ねぎを中火で5分、柔らかく色づくまで炒める。パプリカとにんにくを加えて30秒炒め——パプリカは焦がすと苦くなるので注意——トマトピューレとローリエを加える。じゃがいも、水、塩ひとつまみを入れて全体を混ぜ、ふたをして弱火で約25分、じゃがいもが柔らかくソースがまとまるまで煮る。強くかき混ぜず時々鍋をゆすって、じゃがいもを崩さないようにする。そのまま、あるいはあればサワークリームを添えて熱いうちに供する。',
      hi:'आलू छीलकर एक-निवाले के टुकड़ों में काटें। बर्तन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 5 मिनट नरम-सुनहरा होने तक भूनें। पेपरिका और लहसुन डालकर 30 सेकंड चलाएँ — पेपरिका जलने न दें वरना कड़वी हो जाती है — फिर टमाटर प्यूरी और तेज पत्ता डालें। आलू, पानी और अच्छी चुटकी नमक डालें, लपेटने के लिए मिलाएँ, फिर ढककर धीमी आँच पर लगभग 25 मिनट पकाएँ जब तक आलू नरम और सॉस गाढ़ी हो। तेज़ चलाने के बजाय बीच-बीच में बर्तन हिलाएँ ताकि आलू साबुत रहें। गरम, अकेले या एक चम्मच खट्टी क्रीम के साथ परोसें।',
      tr:'Patatesleri soyup lokma büyüklüğünde doğrayın. Tencerede yağı ısıtın ve doğranmış soğanı orta ateşte 5 dakika, yumuşayıp kızarana dek kavurun. Toz biber ve sarımsağı ekleyip 30 saniye karıştırın — toz biberi yakmayın, yoksa acılaşır — sonra domates püresi ve defne yaprağını ekleyin. Patatesleri, suyu ve iyi bir tutam tuzu ekleyip harmanlayın, ardından kapağını kapatıp kısık ateşte yaklaşık 25 dakika, patatesler yumuşayıp sos koyulaşana dek pişirin. Sert karıştırmak yerine ara sıra tencereyi sallayın ki patatesler bütün kalsın. Sıcak, tek başına ya da varsa bir kaşık ekşi krema ile servis edin.',
      it:'Sbuccia le patate e tagliale a pezzi di un boccone. Scalda l’olio in una pentola e rosola la cipolla tritata a fuoco medio per 5 minuti, finché è morbida e dorata. Unisci la paprica e l’aglio e mescola 30 secondi — non far bruciare la paprica, o diventa amara — poi aggiungi la passata e l’alloro. Aggiungi le patate, l’acqua e una buona presa di sale, mescola per insaporire, poi cuoci coperto a fuoco basso circa 25 minuti, finché le patate sono tenere e il sugo si è addensato. Scuoti la pentola ogni tanto invece di mescolare con forza, così le patate restano intere. Servi caldo, da solo o con un cucchiaio di panna acida se ce l’hai.',
      ko:'감자는 껍질을 벗겨 한입 크기로 썬다. 냄비에 기름을 데우고 다진 양파를 중불에서 5분간 부드럽고 노릇해질 때까지 볶는다. 파프리카 가루와 마늘을 넣고 30초 볶는다 — 파프리카는 태우면 쓴맛이 나니 주의 — 토마토 퓌레와 월계수 잎을 넣는다. 감자, 물, 소금 넉넉히 한 꼬집을 넣어 고루 섞은 뒤 뚜껑을 덮어 약불에서 약 25분간 감자가 부드럽고 소스가 걸쭉해질 때까지 끓인다. 세게 젓지 말고 가끔 냄비를 흔들어 감자가 부서지지 않게 한다. 그대로 또는 있으면 사워크림 한 숟갈과 함께 뜨겁게 낸다.' } },

  { id:'budget_003', name:NAMES.iahnie, servings:2, prep:10, cook:25, costRon:4, nut:{cal:340,prot:16,carb:48,fat:9,fib:13}, tags:['budget','vegan','high-protein'],
    ing:[ {q:400,u:'g',n:I.beans}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:2,u:'clove',n:I.garlic}, {q:1,u:'tsp',n:I.paprika}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Încălzește uleiul într-o oală și călește ceapa tocată mărunt la foc mediu circa 6 minute, până se înmoaie și se rumenește frumos — o ceapă bine gătită e sufletul acestui fel. Adaugă usturoiul și boiaua și amestecă 30 de secunde, apoi pune roșiile pasate și foaia de dafin și lasă să dea în clocot 3 minute. Scurge și clătește fasolea, adaug-o în oală cu un strop de apă și fierbe blând 15 minute, ca să se pătrundă de arome. Zdrobește câteva boabe de peretele oalei ca să îngroși sosul într-o tocană cremoasă. Potrivește de sare și mai adaugă puțină apă dacă se leagă prea tare. Servește caldă, tradițional cu murături sau pâine.',
      en:'Warm the oil in a pot and cook the finely chopped onion over medium heat for about 6 minutes, until soft and nicely golden — a well-cooked onion is the backbone of this dish. Add the garlic and paprika and stir for 30 seconds, then add the tomato passata and bay leaf and let it bubble for 3 minutes. Drain and rinse the beans, add them to the pot with a splash of water, and simmer gently for 15 minutes so they take on the flavour. Mash a few beans against the side of the pot to thicken the sauce into a creamy stew. Season with salt to taste, and add a little water if it gets too thick. Serve warm, traditionally with pickles or bread.',
      es:'Calienta el aceite en una olla y sofríe la cebolla picada fina a fuego medio unos 6 minutos, hasta que esté blanda y bien dorada —una cebolla bien hecha es el alma de este plato—. Añade el ajo y el pimentón y remueve 30 segundos, luego incorpora el tomate y la hoja de laurel y deja borbotear 3 minutos. Escurre y enjuaga las alubias, añádelas con un chorrito de agua y cuece suave 15 minutos para que tomen sabor. Aplasta unas alubias contra la olla para espesar la salsa en un guiso cremoso. Sazona con sal y añade un poco de agua si queda muy espeso. Sirve caliente, tradicionalmente con encurtidos o pan.',
      fr:'Chauffez l’huile dans une casserole et faites revenir l’oignon finement haché à feu moyen environ 6 minutes, jusqu’à ce qu’il soit tendre et bien doré — un oignon bien cuit est l’âme de ce plat. Ajoutez l’ail et le paprika et remuez 30 secondes, puis ajoutez les tomates passées et la feuille de laurier et laissez bouillonner 3 minutes. Égouttez et rincez les haricots, ajoutez-les avec un peu d’eau et laissez mijoter doucement 15 minutes pour qu’ils s’imprègnent. Écrasez quelques haricots contre la casserole pour épaissir la sauce en un ragoût crémeux. Salez et ajoutez un peu d’eau si c’est trop épais. Servez chaud, traditionnellement avec des pickles ou du pain.',
      de:'Das Öl in einem Topf erwärmen und die fein gehackte Zwiebel bei mittlerer Hitze etwa 6 Minuten anschwitzen, bis sie weich und schön goldbraun ist — eine gut gegarte Zwiebel ist das Rückgrat dieses Gerichts. Knoblauch und Paprikapulver zugeben und 30 Sekunden rühren, dann passierte Tomaten und Lorbeerblatt zugeben und 3 Minuten blubbern lassen. Die Bohnen abtropfen und abspülen, mit einem Schuss Wasser in den Topf geben und 15 Minuten sanft köcheln, damit sie Geschmack aufnehmen. Ein paar Bohnen am Topfrand zerdrücken, um die Soße zu einem cremigen Eintopf zu binden. Mit Salz abschmecken und bei Bedarf etwas Wasser zugeben. Warm servieren, traditionell mit Eingelegtem oder Brot.',
      pt:'Aqueça o óleo numa panela e refogue a cebola bem picada em lume médio cerca de 6 minutos, até ficar macia e bem dourada — uma cebola bem feita é a alma deste prato. Junte o alho e o colorau e mexa 30 segundos, depois adicione o tomate passata e a folha de louro e deixe borbulhar 3 minutos. Escorra e lave o feijão, junte-o com um pouco de água e cozinhe brandamente 15 minutos para absorver o sabor. Esmague alguns grãos contra a panela para engrossar o molho num guisado cremoso. Tempere com sal e junte um pouco de água se ficar muito espesso. Sirva quente, tradicionalmente com picles ou pão.',
      ru:'Разогрейте масло в кастрюле и обжарьте мелко нарезанный лук на среднем огне около 6 минут, до мягкости и красивой золотистости — хорошо приготовленный лук основа этого блюда. Добавьте чеснок и паприку, помешивайте 30 секунд, затем добавьте протёртые томаты и лавровый лист и дайте побулькать 3 минуты. Слейте и промойте фасоль, добавьте её с небольшим количеством воды и тушите на слабом огне 15 минут, чтобы она пропиталась вкусом. Разомните несколько фасолин о стенку кастрюли, чтобы соус загустел в кремовое рагу. Посолите по вкусу и добавьте немного воды, если станет слишком густо. Подавайте тёплым, традиционно с соленьями или хлебом.',
      ar:'سخّن الزيت في قدر وشوّح البصل المفروم ناعماً على نار متوسطة نحو 6 دقائق حتى يلين ويكتسب لوناً ذهبياً جميلاً — البصل المطهو جيداً هو روح هذا الطبق. أضف الثوم والبابريكا وقلّب 30 ثانية، ثم أضف الطماطم المهروسة وورقة الغار واتركها تغلي 3 دقائق. صفّ الفاصوليا واغسلها، أضفها مع رشة ماء واطهها بهدوء 15 دقيقة لتتشرّب النكهة. اهرس بعض الحبات على جدار القدر لتكثيف الصلصة إلى يخنة كريمية. تبّل بالملح وأضف قليلاً من الماء إن ثخنت كثيراً. قدّمها دافئة، وتقليدياً مع المخللات أو الخبز.',
      zh:'锅中热油，中火炒切碎的洋葱约6分钟，至变软、金黄漂亮——炒透的洋葱是这道菜的灵魂。加入蒜和红椒粉炒30秒，再加番茄泥和香叶，煮沸3分钟。豆子沥干冲洗后连同少许水下锅，小火煮15分钟入味。用勺把几颗豆子压在锅壁上，使汤汁浓稠、口感绵密。加盐调味，太稠就加一点水。趁热食用，传统上配腌菜或面包。',
      ja:'鍋に油を温め、みじん切りの玉ねぎを中火で約6分、柔らかくきれいな飴色になるまで炒める——よく炒めた玉ねぎがこの料理の要。にんにくとパプリカを加えて30秒炒め、トマトピューレとローリエを加えて3分ふつふつ煮る。豆を水切りして洗い、水少々とともに鍋に加えて15分ほど静かに煮て味を含ませる。豆を数粒だけ鍋肌でつぶし、ソースにとろみをつけてクリーミーな煮込みにする。塩で味を調え、固くなりすぎたら水を少し足す。温かいうちに、伝統的にはピクルスやパンを添えて供する。',
      hi:'बर्तन में तेल गरम करें और बारीक कटा प्याज़ मध्यम आँच पर लगभग 6 मिनट नरम और अच्छा सुनहरा होने तक भूनें — अच्छी भुनी प्याज़ इस व्यंजन की जान है। लहसुन और पेपरिका डालकर 30 सेकंड चलाएँ, फिर टमाटर प्यूरी और तेज पत्ता डालकर 3 मिनट उबलने दें। बीन्स को छानकर धोएँ, थोड़े पानी के साथ बर्तन में डालें और 15 मिनट धीमी आँच पर पकाएँ ताकि स्वाद सोख लें। कुछ बीन्स को बर्तन की दीवार पर दबाकर मसलें ताकि सॉस गाढ़ी-मलाईदार सालन बने। नमक डालें और ज़्यादा गाढ़ा होने पर थोड़ा पानी मिलाएँ। गरम, परंपरागत रूप से अचार या ब्रेड के साथ परोसें।',
      tr:'Tencerede yağı ısıtın ve ince doğranmış soğanı orta ateşte yaklaşık 6 dakika, yumuşayıp güzelce kızarana dek kavurun — iyi kavrulmuş soğan bu yemeğin ruhudur. Sarımsak ve toz biberi ekleyip 30 saniye karıştırın, sonra domates püresi ve defne yaprağını ekleyip 3 dakika fıkırdatın. Fasulyeyi süzüp durulayın, biraz suyla tencereye ekleyin ve tadı çekmesi için 15 dakika hafifçe pişirin. Birkaç taneyi tava kenarında ezip sosu kremamsı bir yahniye dönüştürün. Tuzla tatlandırın, fazla koyulaşırsa biraz su ekleyin. Sıcak, geleneksel olarak turşu ya da ekmekle servis edin.',
      it:'Scalda l’olio in una pentola e rosola la cipolla tritata fine a fuoco medio per circa 6 minuti, finché è morbida e ben dorata — una cipolla ben cotta è l’anima di questo piatto. Unisci l’aglio e la paprica e mescola 30 secondi, poi aggiungi la passata e l’alloro e lascia sobbollire 3 minuti. Scola e sciacqua i fagioli, aggiungili con un goccio d’acqua e fai sobbollire dolcemente 15 minuti perché prendano sapore. Schiaccia qualche fagiolo contro la pentola per addensare il sugo in uno stufato cremoso. Regola di sale e aggiungi un po’ d’acqua se diventa troppo denso. Servi caldo, tradizionalmente con sottaceti o pane.',
      ko:'냄비에 기름을 데우고 곱게 다진 양파를 중불에서 약 6분간 부드럽고 먹음직스러운 갈색이 될 때까지 볶는다 — 잘 볶은 양파가 이 요리의 핵심이다. 마늘과 파프리카 가루를 넣고 30초 볶은 뒤 토마토 퓌레와 월계수 잎을 넣어 3분간 보글보글 끓인다. 콩을 헹궈 물기를 빼고 물을 조금 넣어 15분간 은근히 끓여 맛이 배게 한다. 콩 몇 알을 냄비 벽에 눌러 으깨 소스를 걸쭉하고 크리미한 스튜로 만든다. 소금으로 간하고 너무 되직하면 물을 조금 넣는다. 따뜻하게, 전통적으로 피클이나 빵과 함께 낸다.' } },

  { id:'budget_004', name:NAMES.vinete, servings:2, prep:15, cook:30, costRon:4, nut:{cal:180,prot:3,carb:12,fat:14,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.eggplant}, {q:1,n:I.onion}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.lemon}, {n:I.salt} ],
    steps:{
      ro:'Înțeapă vinetele de câteva ori cu furculița și coace-le întregi — pe flacără, la grătar sau în cuptor încins — întorcându-le până coaja e arsă, iar miezul complet moale, circa 25-30 de minute. Lasă-le să se răcorească puțin, apoi curăță coaja arsă și scurge miezul într-o strecurătoare câteva minute, ca să piardă zeama amară. Toacă miezul fin cu un cuțit sau o lingură de lemn (evită vasele de metal, care îl înnegresc) până devine aproape pastă. Încorporează uleiul câte puțin, ca la maioneză, până se albește și devine cremos. Adaugă ceapa tăiată foarte mărunt, sărează și dă gust cu zeamă de lămâie. Servește rece, întinsă pe pâine.',
      en:'Prick the eggplants a few times with a fork and roast them whole — over an open flame, under the grill, or in a hot oven — turning until the skin is charred and the flesh is completely soft, about 25-30 minutes. Let them cool a little, then peel off the blackened skin and drain the flesh in a sieve for a few minutes to lose its bitter juices. Chop the flesh finely with a knife or wooden spoon (avoid metal bowls, which darken it) until it is almost a paste. Beat in the oil a little at a time, as if making mayonnaise, until it turns pale and creamy. Fold in the very finely chopped onion, season with salt, and sharpen with a squeeze of lemon. Serve cool, spread on bread.',
      es:'Pincha las berenjenas varias veces con un tenedor y ásalas enteras —sobre la llama, al grill o en el horno caliente— girándolas hasta que la piel esté quemada y la pulpa completamente blanda, unos 25-30 minutos. Deja que se templen, pela la piel ennegrecida y escurre la pulpa en un colador unos minutos para que pierda los jugos amargos. Pica la pulpa fina con cuchillo o cuchara de madera (evita recipientes de metal, que la oscurecen) hasta casi hacer una pasta. Incorpora el aceite poco a poco, como una mayonesa, hasta que aclare y quede cremosa. Añade la cebolla muy picada, sazona con sal y realza con un chorro de limón. Sirve fría, untada en pan.',
      fr:'Piquez les aubergines plusieurs fois à la fourchette et faites-les rôtir entières — sur une flamme, sous le gril ou au four chaud — en les retournant jusqu’à ce que la peau soit carbonisée et la chair complètement molle, environ 25-30 minutes. Laissez tiédir, retirez la peau noircie et laissez égoutter la chair dans une passoire quelques minutes pour perdre ses sucs amers. Hachez la chair finement au couteau ou à la cuillère en bois (évitez les récipients en métal, qui la noircissent) jusqu’à obtenir presque une pâte. Incorporez l’huile petit à petit, comme une mayonnaise, jusqu’à ce que ce soit pâle et crémeux. Ajoutez l’oignon très finement haché, salez et relevez d’un filet de citron. Servez frais, tartiné sur du pain.',
      de:'Die Auberginen mehrmals mit einer Gabel einstechen und im Ganzen rösten — über offener Flamme, unter dem Grill oder im heißen Ofen — dabei wenden, bis die Haut verkohlt und das Fruchtfleisch ganz weich ist, etwa 25-30 Minuten. Etwas abkühlen lassen, dann die verkohlte Haut abziehen und das Fruchtfleisch in einem Sieb einige Minuten abtropfen lassen, damit es die bitteren Säfte verliert. Das Fruchtfleisch mit Messer oder Holzlöffel fein hacken (Metallschüsseln vermeiden, sie verfärben es) bis fast eine Paste entsteht. Das Öl nach und nach einarbeiten, wie bei Mayonnaise, bis es hell und cremig wird. Die sehr fein gehackte Zwiebel unterheben, salzen und mit einem Spritzer Zitrone abrunden. Kühl servieren, auf Brot gestrichen.',
      pt:'Pique as beringelas várias vezes com um garfo e asse-as inteiras — sobre a chama, no grelhador ou no forno quente — virando até a pele ficar queimada e a polpa completamente mole, cerca de 25-30 minutos. Deixe amornar, retire a pele queimada e escorra a polpa num coador alguns minutos para perder os sucos amargos. Pique a polpa fina com faca ou colher de pau (evite recipientes de metal, que a escurecem) até quase virar pasta. Incorpore o óleo aos poucos, como numa maionese, até clarear e ficar cremosa. Envolva a cebola bem picada, tempere com sal e avive com um pouco de sumo de limão. Sirva fria, barrada em pão.',
      ru:'Наколите баклажаны вилкой в нескольких местах и запеките целиком — на открытом огне, под грилем или в горячей духовке — переворачивая, пока кожица не обуглится, а мякоть не станет совсем мягкой, около 25-30 минут. Дайте немного остыть, снимите обугленную кожицу и дайте мякоти стечь в сите несколько минут, чтобы ушёл горький сок. Мелко порубите мякоть ножом или деревянной ложкой (избегайте металлической посуды, она её темнит) почти до пасты. Вбивайте масло понемногу, как при приготовлении майонеза, пока масса не побледнеет и не станет кремовой. Вмешайте очень мелко нарезанный лук, посолите и оживите соком лимона. Подавайте охлаждённой, намазав на хлеб.',
      ar:'اثقب الباذنجان عدة مرات بالشوكة واشوِه كاملاً — على لهب مباشر أو تحت الشواية أو في فرن ساخن — مع تقليبه حتى تتفحّم القشرة ويصبح اللبّ طرياً تماماً، نحو 25-30 دقيقة. اتركه يبرد قليلاً، ثم قشّر القشرة المحروقة وصفّ اللبّ في مصفاة دقائق ليفقد عصارته المُرّة. افرم اللبّ ناعماً بسكين أو ملعقة خشب (تجنّب أوعية المعدن التي تسوّده) حتى يقارب العجينة. أضف الزيت تدريجياً كأنك تعدّ المايونيز حتى يشحب لونه ويصبح كريمياً. أضف البصل المفروم ناعماً جداً، ملّحه وأنعشه بعصير الليمون. قدّمه بارداً مدهوناً على الخبز.',
      zh:'用叉子在茄子上戳几下，整只烤制——明火、烤架或热烤箱皆可——不时翻面，直到表皮焦黑、内里完全软烂，约25-30分钟。稍微放凉，剥去焦皮，把茄肉放漏网里沥几分钟，去掉苦水。用刀或木勺把茄肉剁细（别用金属容器，会使其发黑），几乎成泥。像做蛋黄酱一样一点点加入油，搅打至发白绵滑。拌入切得极细的洋葱，加盐调味，挤入柠檬汁提味。冷食，抹在面包上。',
      ja:'なすをフォークで数か所刺し、丸ごと焼く——直火、グリル、または高温のオーブンで——皮が真っ黒に焦げて中が完全に柔らかくなるまで、約25〜30分返しながら焼く。少し冷ましてから焦げた皮をむき、ざるで数分水切りして苦い汁を落とす。金属のボウルは色が黒くなるので避け、包丁か木べらで果肉をほぼペースト状に細かく刻む。マヨネーズを作る要領で油を少しずつ加え、白っぽくクリーミーになるまで混ぜる。ごく細かく刻んだ玉ねぎを混ぜ込み、塩で味を調え、レモンを搾って引き締める。冷やして、パンに塗って供する。',
      hi:'बैंगन में काँटे से कुछ जगह छेद करें और साबुत भूनें — खुली आँच पर, ग्रिल में या गरम ओवन में — पलटते हुए जब तक छिलका जल जाए और गूदा पूरी तरह नरम हो, लगभग 25-30 मिनट। थोड़ा ठंडा होने दें, जला छिलका उतारें और गूदे को छलनी में कुछ मिनट रखकर उसका कड़वा रस निकलने दें। गूदे को चाकू या लकड़ी के चम्मच से बारीक काटें (धातु के बर्तन से बचें, वे इसे काला कर देते हैं) जब तक लगभग पेस्ट न बने। मेयोनेज़ की तरह थोड़ा-थोड़ा तेल फेंटते हुए मिलाएँ जब तक यह हल्का और मलाईदार हो जाए। बहुत बारीक कटा प्याज़ मिलाएँ, नमक डालें और नींबू निचोड़कर स्वाद बढ़ाएँ। ठंडा, ब्रेड पर लगाकर परोसें।',
      tr:'Patlıcanları çatalla birkaç yerinden delin ve bütün halde közleyin — açık ateşte, ızgarada ya da kızgın fırında — kabuğu kömürleşip içi tamamen yumuşayana dek çevirerek, yaklaşık 25-30 dakika. Biraz soğutun, yanmış kabuğu soyun ve eti bir süzgeçte birkaç dakika süzerek acı suyunu bırakmasını sağlayın. Eti bıçak ya da tahta kaşıkla (kararttığı için metal kaplardan kaçının) neredeyse macun olana dek ince ince doğrayın. Mayonez yapar gibi yağı azar azar ekleyip çırpın; rengi açılıp kremamsı olsun. Çok ince doğranmış soğanı katın, tuzla tatlandırın ve limon sıkarak canlandırın. Soğuk, ekmeğe sürerek servis edin.',
      it:'Bucherella le melanzane con una forchetta e arrostiscile intere — su fiamma viva, sotto il grill o in forno caldo — girandole finché la buccia è bruciacchiata e la polpa del tutto morbida, circa 25-30 minuti. Falle intiepidire, togli la buccia annerita e scola la polpa in un colino qualche minuto per perdere i succhi amari. Trita la polpa fine con coltello o cucchiaio di legno (evita recipienti di metallo, che la scuriscono) fin quasi a crema. Incorpora l’olio poco alla volta, come per una maionese, finché diventa pallida e cremosa. Unisci la cipolla tritata finissima, sala e ravviva con una spremuta di limone. Servi fresca, spalmata sul pane.',
      ko:'가지를 포크로 몇 군데 찌른 뒤 통째로 굽는다 — 직화, 그릴, 또는 뜨거운 오븐에서 — 껍질이 새까맣게 타고 속이 완전히 물러질 때까지 약 25~30분 뒤집어가며 굽는다. 살짝 식힌 뒤 탄 껍질을 벗기고 과육을 체에 몇 분간 밭쳐 쓴 즙을 뺀다. 금속 그릇은 색을 검게 하니 피하고, 칼이나 나무 주걱으로 과육을 거의 페이스트가 될 때까지 곱게 다진다. 마요네즈를 만들듯 기름을 조금씩 넣어 색이 연해지고 크리미해질 때까지 젓는다. 아주 곱게 다진 양파를 섞고 소금으로 간한 뒤 레몬을 짜 맛을 살린다. 차갑게, 빵에 발라 낸다.' } },

  { id:'budget_005', name:NAMES.ghiveci, servings:2, prep:20, cook:35, costRon:5, nut:{cal:260,prot:6,carb:38,fat:10,fib:9}, tags:['budget','vegan','healthy'],
    ing:[ {q:200,u:'g',n:I.potatoes}, {q:1,n:I.carrot}, {q:1,n:I.onion}, {q:1,n:I.bellPepper}, {q:200,u:'g',n:I.zucchini}, {q:200,u:'g',n:I.passata}, {q:2,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Taie toate legumele — cartof, morcov, ceapă, ardei gras și dovlecel — în bucăți de mărime asemănătoare, ca să se gătească uniform. Încălzește uleiul într-o oală largă și călește ceapa și usturoiul 4 minute, apoi adaugă legumele mai tari (cartof și morcov) și mai gătește 5 minute, amestecând. Adaugă ardeiul și dovlecelul, roșiile pasate, foaia de dafin și un praf bun de sare, împreună cu un strop de apă. Acoperă și fierbe blând circa 30 de minute, amestecând din când în când, până fiecare legumă e fragedă, iar sosul e bogat. Trebuie să iasă o tocană moale, nu o supă — dacă e nevoie, mai fierbe câteva minute descoperit. Potrivește de gust și servește cald, simplu sau ca garnitură.',
      en:'Cut all the vegetables — potato, carrot, onion, bell pepper and zucchini — into similar bite-sized pieces so they cook evenly. Warm the oil in a wide pot and soften the onion and garlic for 4 minutes, then add the harder vegetables (potato and carrot) and cook for 5 minutes, stirring. Add the pepper and zucchini, the tomato passata, bay leaf and a good pinch of salt, along with a splash of water. Cover and simmer gently for about 30 minutes, stirring occasionally, until every vegetable is tender and the sauce is rich. It should end up soft and stewy, not soupy — cook uncovered for the last few minutes if needed. Season to taste and serve warm, on its own or as a side.',
      es:'Corta todas las verduras —patata, zanahoria, cebolla, pimiento y calabacín— en trozos de tamaño similar para que cuezan por igual. Calienta el aceite en una olla amplia y sofríe la cebolla y el ajo 4 minutos, luego añade las verduras más duras (patata y zanahoria) y cocina 5 minutos, removiendo. Añade el pimiento y el calabacín, el tomate, la hoja de laurel y una buena pizca de sal, junto con un chorrito de agua. Tapa y cuece suave unos 30 minutos, removiendo de vez en cuando, hasta que todas las verduras estén tiernas y la salsa sea densa. Debe quedar como un guiso blando, no una sopa —cuece destapado los últimos minutos si hace falta—. Ajusta de sal y sirve caliente, solo o como guarnición.',
      fr:'Coupez tous les légumes — pomme de terre, carotte, oignon, poivron et courgette — en morceaux de taille similaire pour une cuisson homogène. Chauffez l’huile dans une grande casserole et faites revenir l’oignon et l’ail 4 minutes, puis ajoutez les légumes les plus fermes (pomme de terre et carotte) et faites cuire 5 minutes en remuant. Ajoutez le poivron et la courgette, les tomates passées, la feuille de laurier et une bonne pincée de sel, avec un peu d’eau. Couvrez et laissez mijoter doucement environ 30 minutes, en remuant de temps en temps, jusqu’à ce que chaque légume soit tendre et la sauce riche. Cela doit rester un ragoût moelleux, pas une soupe — cuisez à découvert les dernières minutes si besoin. Rectifiez l’assaisonnement et servez chaud, seul ou en accompagnement.',
      de:'Alle Gemüse — Kartoffel, Karotte, Zwiebel, Paprika und Zucchini — in ähnlich große Stücke schneiden, damit sie gleichmäßig garen. Das Öl in einem weiten Topf erwärmen und Zwiebel und Knoblauch 4 Minuten anschwitzen, dann das festere Gemüse (Kartoffel und Karotte) zugeben und unter Rühren 5 Minuten braten. Paprika und Zucchini, passierte Tomaten, Lorbeerblatt und eine gute Prise Salz zugeben, dazu einen Schuss Wasser. Zudecken und etwa 30 Minuten sanft köcheln, gelegentlich rühren, bis jedes Gemüse weich und die Soße reichhaltig ist. Es soll ein weicher Eintopf werden, keine Suppe — die letzten Minuten bei Bedarf offen kochen. Abschmecken und warm servieren, pur oder als Beilage.',
      pt:'Corte todos os legumes — batata, cenoura, cebola, pimentão e courgette — em pedaços de tamanho semelhante para cozerem por igual. Aqueça o óleo numa panela larga e refogue a cebola e o alho 4 minutos, depois junte os legumes mais duros (batata e cenoura) e cozinhe 5 minutos, mexendo. Junte o pimentão e a courgette, o tomate passata, a folha de louro e uma boa pitada de sal, com um pouco de água. Tape e cozinhe brandamente cerca de 30 minutos, mexendo de vez em quando, até todos os legumes ficarem macios e o molho encorpado. Deve ficar um guisado macio, não uma sopa — coza destapado nos últimos minutos se precisar. Acerte o sal e sirva quente, simples ou como acompanhamento.',
      ru:'Нарежьте все овощи — картофель, морковь, лук, болгарский перец и кабачок — кусочками схожего размера, чтобы они готовились равномерно. Разогрейте масло в широкой кастрюле и обжарьте лук и чеснок 4 минуты, затем добавьте более твёрдые овощи (картофель и морковь) и готовьте 5 минут, помешивая. Добавьте перец и кабачок, протёртые томаты, лавровый лист и хорошую щепотку соли, а также немного воды. Накройте и тушите на слабом огне около 30 минут, изредка помешивая, пока все овощи не станут мягкими, а соус — насыщенным. Должно получиться мягкое рагу, а не суп — при необходимости последние минуты готовьте без крышки. Посолите по вкусу и подавайте тёплым, само по себе или как гарнир.',
      ar:'قطّع كل الخضار — البطاطس والجزر والبصل والفلفل الحلو والكوسة — إلى قطع متقاربة الحجم لتنضج بالتساوي. سخّن الزيت في قدر واسع وشوّح البصل والثوم 4 دقائق، ثم أضف الخضار الأقسى (البطاطس والجزر) واطهها 5 دقائق مع التقليب. أضف الفلفل والكوسة والطماطم المهروسة وورقة الغار ورشة ملح جيدة مع رشة ماء. غطِّ القدر واطهه بهدوء نحو 30 دقيقة مع التقليب أحياناً حتى تنضج كل الخضار وتصبح الصلصة غنية. يجب أن يكون يخنة طرية لا شوربة — اطهه مكشوفاً في الدقائق الأخيرة إن لزم. اضبط التتبيل وقدّمه دافئاً، وحده أو كطبق جانبي.',
      zh:'把所有蔬菜——土豆、胡萝卜、洋葱、甜椒和西葫芦——切成大小相近的块，方便均匀成熟。宽口锅热油，炒洋葱和蒜4分钟，再加较硬的蔬菜（土豆和胡萝卜）翻炒5分钟。加入甜椒、西葫芦、番茄泥、香叶和一大撮盐，再加少许水。加盖小火煮约30分钟，其间不时搅动，至所有蔬菜软烂、汤汁浓郁。成品应是软糯的炖菜而非汤——需要的话最后几分钟开盖收汁。按口味调味，趁热单吃或作配菜。',
      ja:'すべての野菜——じゃがいも、にんじん、玉ねぎ、パプリカ、ズッキーニ——を火通りがそろうよう同じくらいの一口大に切る。広めの鍋に油を温め、玉ねぎとにんにくを4分炒め、火の通りにくい野菜（じゃがいもとにんじん）を加えて混ぜながら5分炒める。パプリカとズッキーニ、トマトピューレ、ローリエ、塩ひとつまみを水少々とともに加える。ふたをして約30分、時々混ぜながら、すべての野菜が柔らかくソースが濃厚になるまで静かに煮る。スープではなく、柔らかい煮込みに仕上げる——必要なら最後の数分はふたを取って煮詰める。味を調え、そのまま、または付け合わせとして温かいうちに供する。',
      hi:'सभी सब्ज़ियाँ — आलू, गाजर, प्याज़, शिमला मिर्च और तोरी — एक जैसे टुकड़ों में काटें ताकि समान रूप से पकें। चौड़े बर्तन में तेल गरम करें और प्याज़ व लहसुन 4 मिनट भूनें, फिर सख्त सब्ज़ियाँ (आलू और गाजर) डालकर 5 मिनट चलाते हुए पकाएँ। शिमला मिर्च और तोरी, टमाटर प्यूरी, तेज पत्ता और अच्छी चुटकी नमक थोड़े पानी के साथ डालें। ढककर लगभग 30 मिनट धीमी आँच पर बीच-बीच में चलाते हुए पकाएँ जब तक हर सब्ज़ी नरम और सॉस गाढ़ी हो। यह नरम सालन जैसा बने, सूप नहीं — ज़रूरत हो तो आख़िरी कुछ मिनट खुला पकाएँ। स्वादानुसार नमक ठीक करें और गरम, अकेले या साइड के रूप में परोसें।',
      tr:'Bütün sebzeleri — patates, havuç, soğan, dolmalık biber ve kabak — eşit pişsin diye benzer büyüklükte lokmalara doğrayın. Geniş bir tencerede yağı ısıtın, soğan ve sarımsağı 4 dakika kavurun, sonra sert sebzeleri (patates ve havuç) ekleyip karıştırarak 5 dakika pişirin. Biber ve kabağı, domates püresini, defne yaprağını ve iyi bir tutam tuzu biraz suyla ekleyin. Kapağını kapatıp yaklaşık 30 dakika, ara sıra karıştırarak, tüm sebzeler yumuşayıp sos koyulaşana dek hafifçe pişirin. Çorba değil, yumuşak bir güveç olmalı — gerekirse son birkaç dakika kapaksız pişirin. Tuzunu ayarlayıp sıcak, tek başına ya da garnitür olarak servis edin.',
      it:'Taglia tutte le verdure — patata, carota, cipolla, peperone e zucchina — a pezzi di dimensioni simili così cuociono in modo uniforme. Scalda l’olio in una pentola ampia e fai appassire cipolla e aglio per 4 minuti, poi aggiungi le verdure più dure (patata e carota) e cuoci 5 minuti, mescolando. Aggiungi peperone e zucchina, la passata, l’alloro e una buona presa di sale, con un goccio d’acqua. Copri e fai sobbollire dolcemente circa 30 minuti, mescolando ogni tanto, finché ogni verdura è tenera e il sugo è ricco. Deve venire uno stufato morbido, non una minestra — cuoci scoperto gli ultimi minuti se serve. Regola di sale e servi caldo, da solo o come contorno.',
      ko:'모든 채소 — 감자, 당근, 양파, 파프리카, 애호박 — 를 고르게 익도록 비슷한 한입 크기로 썬다. 넓은 냄비에 기름을 데우고 양파와 마늘을 4분 볶은 뒤 단단한 채소(감자와 당근)를 넣어 저으며 5분 볶는다. 파프리카와 애호박, 토마토 퓌레, 월계수 잎, 소금 넉넉히 한 꼬집을 물 조금과 함께 넣는다. 뚜껑을 덮고 약 30분간 가끔 저으며 모든 채소가 부드럽고 소스가 진해질 때까지 은근히 끓인다. 수프가 아니라 부드러운 스튜가 되어야 한다 — 필요하면 마지막 몇 분은 뚜껑을 열고 졸인다. 간을 맞춰 그대로 또는 곁들임으로 따뜻하게 낸다.' } },
  { id:'budget_006', name:NAMES.fasoleBatuta, servings:2, prep:10, cook:60, costRon:4, nut:{cal:380,prot:18,carb:45,fat:14,fib:15}, tags:['budget','vegan','high-protein'],
    ing:[ {q:250,u:'g',n:I.whiteBeans}, {q:2,n:I.onion}, {q:4,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești fasole uscată, las-o peste noapte în apă rece, apoi fierbe-o în apă proaspătă circa o oră, până e foarte moale; scurge-o, păstrând puțin din zeamă. Pasează fasolea caldă cu 2 linguri de ulei (un blender o face mai fină) până devine cremoasă, subțiind cu un strop de zeamă, și potrivește bine de sare. Taie ceapa solzișori și călește-o încet în restul de ulei până se rumenește frumos și se îndulcește, circa 10 minute, apoi ia de pe foc și amestecă boiaua. Întinde pasta de fasole pe o farfurie și pune deasupra ceapa caldă cu boia. Servește la temperatura camerei, cu pâine și murături.',
      en:'If using dried beans, soak them overnight in cold water, then boil in fresh water for about an hour until very soft; drain, keeping a little of the liquid. Mash the warm beans with 2 tablespoons of the oil (a blender makes it smoother) until creamy, loosening with a splash of the liquid, and season well with salt. Slice the onions thinly and fry them slowly in the remaining oil until deep golden and sweet, about 10 minutes, then take off the heat and stir in the paprika. Spread the bean paste on a plate and top with the warm paprika onions. Serve at room temperature with bread and pickles.',
      es:'Si usas alubias secas, remójalas toda la noche y cuécelas en agua limpia una hora hasta que estén muy blandas; escurre reservando un poco del líquido. Tritura las alubias calientes con 2 cucharadas de aceite (la batidora las deja más finas) hasta que estén cremosas, aflojando con un poco del líquido, y sazona bien con sal. Corta las cebollas en juliana fina y fríelas despacio en el aceite restante hasta que estén doradas y dulces, unos 10 minutos, retira del fuego y añade el pimentón. Extiende el puré en un plato y cúbrelo con la cebolla caliente al pimentón. Sirve a temperatura ambiente con pan y encurtidos.',
      fr:'Si vous utilisez des haricots secs, faites-les tremper une nuit, puis cuire à l’eau fraîche environ une heure jusqu’à ce qu’ils soient très tendres ; égouttez en gardant un peu d’eau. Écrasez les haricots chauds avec 2 c. à s. d’huile (un mixeur les rend plus lisses) jusqu’à consistance crémeuse, en détendant avec un peu d’eau, et salez bien. Émincez finement les oignons et faites-les revenir lentement dans le reste d’huile jusqu’à ce qu’ils soient bien dorés et doux, environ 10 minutes, retirez du feu et ajoutez le paprika. Étalez la purée dans une assiette et couvrez des oignons chauds au paprika. Servez à température ambiante avec du pain et des pickles.',
      de:'Bei getrockneten Bohnen diese über Nacht einweichen und in frischem Wasser etwa eine Stunde weich kochen; abgießen, etwas Kochwasser aufbewahren. Die warmen Bohnen mit 2 EL Öl (ein Mixer macht es feiner) cremig pürieren, mit etwas Wasser lockern und kräftig salzen. Die Zwiebeln fein schneiden und im restlichen Öl langsam goldbraun und süßlich braten, etwa 10 Minuten, vom Herd nehmen und das Paprikapulver einrühren. Die Bohnenpaste auf einen Teller streichen und mit den warmen Paprika-Zwiebeln belegen. Bei Zimmertemperatur mit Brot und Eingelegtem servieren.',
      pt:'Se usar feijão seco, demolhe-o de um dia para o outro e coza em água fresca cerca de uma hora até ficar muito macio; escorra, guardando um pouco da água. Esmague o feijão quente com 2 colheres de sopa de óleo (a varinha deixa-o mais fino) até ficar cremoso, soltando com um pouco da água, e tempere bem com sal. Corte as cebolas fininhas e frite-as devagar no restante óleo até ficarem bem douradas e doces, cerca de 10 minutos, retire do lume e junte o colorau. Espalhe o puré num prato e cubra com as cebolas quentes ao colorau. Sirva à temperatura ambiente com pão e picles.',
      ru:'Если используете сухую фасоль, замочите её на ночь и отварите в свежей воде около часа до мягкости; слейте, сохранив немного отвара. Разомните тёплую фасоль с 2 столовыми ложками масла (блендер сделает нежнее) до кремовой массы, разбавьте отваром и хорошо посолите. Нарежьте лук тонко и медленно обжарьте в оставшемся масле до золотистости и сладости, около 10 минут, снимите с огня и вмешайте паприку. Намажьте фасолевую пасту на тарелку и выложите сверху тёплый лук с паприкой. Подавайте комнатной температуры с хлебом и соленьями.',
      ar:'إن استخدمت فاصوليا جافة، انقعها ليلة كاملة ثم اسلقها في ماء جديد نحو ساعة حتى تلين تماماً؛ صفّها واحتفظ بقليل من الماء. اهرس الفاصوليا الدافئة مع ملعقتين كبيرتين من الزيت (الخلاط يجعلها أنعم) حتى تصبح كريمية، وخفّفها برشة ماء وملّحها جيداً. قطّع البصل شرائح رفيعة وشوّحه ببطء في باقي الزيت حتى يذهبّ ويحلو، نحو 10 دقائق، ارفعه عن النار وأضف البابريكا. افرد معجون الفاصوليا في طبق وغطّه بالبصل الدافئ بالبابريكا. قدّمه بحرارة الغرفة مع الخبز والمخللات.',
      zh:'若用干豆，提前一夜泡软，再用清水煮约1小时至非常软烂；沥干，留少许煮豆水。趁热用2大勺油把豆子压成泥（用搅拌机更细腻），加少许煮豆水调稀，加盐充分调味。洋葱切细丝，用余下的油小火慢炒至金黄回甜，约10分钟，离火拌入红椒粉。把豆泥抹在盘中，铺上温热的红椒洋葱。常温食用，配面包和腌菜。',
      ja:'乾燥豆を使う場合は一晩浸し、新しい水で約1時間、とても柔らかくなるまで茹でる；ゆで汁を少し取り分けて水を切る。温かい豆を油大さじ2とともにクリーミーになるまでつぶし（ブレンダーだと滑らか）、ゆで汁でゆるめて塩でしっかり味付けする。玉ねぎを薄切りにし、残りの油でしっかり色づいて甘くなるまで約10分弱火で炒め、火を止めてパプリカを混ぜる。豆のペーストを皿に広げ、温かいパプリカ玉ねぎをのせる。常温で、パンやピクルスを添えて供する。',
      hi:'सूखी बीन्स इस्तेमाल करें तो रातभर भिगोकर ताज़े पानी में लगभग एक घंटा बहुत नरम होने तक उबालें; छानकर थोड़ा पानी बचा लें। गरम बीन्स को 2 बड़े चम्मच तेल के साथ मलाईदार होने तक मैश करें (ब्लेंडर से महीन बनती है), थोड़े पानी से पतला करें और नमक अच्छे से डालें। प्याज़ को पतला काटें और बचे तेल में धीमी आँच पर सुनहरा-मीठा होने तक लगभग 10 मिनट भूनें, आँच से उतारकर पेपरिका मिलाएँ। बीन स्प्रेड को प्लेट पर फैलाएँ और ऊपर गरम पेपरिका-प्याज़ डालें। कमरे के तापमान पर ब्रेड और अचार के साथ परोसें।',
      tr:'Kuru fasulye kullanıyorsanız gece boyu ıslatıp taze suda yaklaşık bir saat, iyice yumuşayana dek haşlayın; suyundan biraz ayırıp süzün. Sıcak fasulyeyi 2 yemek kaşığı yağla (blender daha pürüzsüz yapar) kremamsı olana dek ezin, biraz suyla açın ve iyice tuzlayın. Soğanları ince doğrayıp kalan yağda ağır ağır iyice kızarıp tatlanana dek yaklaşık 10 dakika kavurun, ateşten alıp toz biberi karıştırın. Fasulye ezmesini tabağa yayıp üzerine sıcak biberli soğanı koyun. Oda sıcaklığında ekmek ve turşuyla servis edin.',
      it:'Se usi fagioli secchi, mettili in ammollo una notte e lessali in acqua fresca circa un’ora finché sono morbidissimi; scola tenendo un po’ di liquido. Schiaccia i fagioli caldi con 2 cucchiai d’olio (il frullatore li rende più lisci) fino a crema, allunga con un po’ di liquido e sala bene. Affetta le cipolle sottili e falle rosolare piano nell’olio rimasto finché sono ben dorate e dolci, circa 10 minuti, togli dal fuoco e unisci la paprica. Spalma il purè su un piatto e completa con le cipolle calde alla paprica. Servi a temperatura ambiente con pane e sottaceti.',
      ko:'말린 콩을 쓰면 하룻밤 불려 새 물에 약 1시간, 아주 부드러워질 때까지 삶고 삶은 물을 조금 남겨 물기를 뺀다. 따뜻한 콩을 기름 2큰술과 함께 크리미해질 때까지 으깨고(블렌더를 쓰면 더 곱다) 삶은 물로 농도를 맞춘 뒤 소금으로 충분히 간한다. 양파를 얇게 썰어 남은 기름에 약불로 진한 갈색이 나고 단맛이 날 때까지 약 10분 볶고, 불을 끈 뒤 파프리카 가루를 섞는다. 콩 스프레드를 접시에 펴고 따뜻한 파프리카 양파를 올린다. 실온으로, 빵과 피클을 곁들여 낸다.' } },

  { id:'budget_007', name:NAMES.mamaliga, servings:2, prep:5, cook:25, costRon:5, nut:{cal:420,prot:14,carb:60,fat:15,fib:5}, tags:['budget','vegetarian','family'],
    ing:[ {q:150,u:'g',n:I.cornmeal}, {q:750,u:'ml',n:I.water}, {q:100,u:'g',n:I.cheese}, {q:100,u:'g',n:I.sourCream}, {n:I.salt} ],
    steps:{
      ro:'Adu apa cu sare la fiert și toarnă mălaiul în ploaie, amestecând viguros ca să nu se formeze cocoloașe. Fierbe la foc mic, amestecând des cu o lingură de lemn, circa 20 de minute, până se îngroașă și devine netedă. Pune jumătate în boluri, sfărâmă deasupra jumătate din brânză, apoi adaugă restul de mămăligă și brânza rămasă, ca să se topească între straturile calde. Pune peste fiecare bol o lingură generoasă de smântână. Servește fierbinte, cât brânza e încă moale.',
      en:'Bring the salted water to a boil and rain in the cornmeal, whisking hard to keep it lump-free. Cook on low, stirring often with a wooden spoon, for about 20 minutes until thick and smooth. Spoon half into bowls, crumble over half the cheese, then add the rest of the polenta and the remaining cheese so it melts between the warm layers. Top each bowl with a generous spoon of sour cream. Serve hot, while the cheese is still soft.',
      es:'Lleva el agua con sal a ebullición y vierte la harina de maíz en un hilo, batiendo fuerte para evitar grumos. Cocina a fuego bajo, removiendo a menudo con cuchara de madera, unos 20 minutos hasta que espese y quede suave. Pon la mitad en boles, desmenuza encima la mitad del queso, luego añade el resto de la polenta y el queso restante para que se funda entre las capas calientes. Corona cada bol con una buena cucharada de crema agria. Sirve caliente, mientras el queso siga blando.',
      fr:'Portez l’eau salée à ébullition et versez la semoule de maïs en pluie, en fouettant fort pour éviter les grumeaux. Faites cuire à feu doux, en remuant souvent à la cuillère en bois, environ 20 minutes jusqu’à ce que ce soit épais et lisse. Répartissez la moitié dans des bols, émiettez dessus la moitié du fromage, puis ajoutez le reste de polenta et le reste de fromage pour qu’il fonde entre les couches chaudes. Couronnez chaque bol d’une belle cuillerée de crème aigre. Servez chaud, tant que le fromage est encore moelleux.',
      de:'Das Salzwasser zum Kochen bringen und den Maisgrieß einrieseln lassen, dabei kräftig rühren, damit keine Klümpchen entstehen. Bei niedriger Hitze unter häufigem Rühren mit einem Holzlöffel etwa 20 Minuten dick und glatt kochen. Die Hälfte in Schalen geben, die Hälfte des Käses darüberbröseln, dann die restliche Polenta und den restlichen Käse zugeben, damit er zwischen den warmen Schichten schmilzt. Jede Schale mit einem großzügigen Löffel Schmand krönen. Heiß servieren, solange der Käse noch weich ist.',
      pt:'Leve a água com sal a ferver e deite o fubá em fio, batendo com força para evitar grumos. Cozinhe em lume baixo, mexendo com frequência com colher de pau, cerca de 20 minutos até engrossar e ficar liso. Coloque metade em taças, esfarele por cima metade do queijo, depois junte o resto da polenta e o queijo restante para derreter entre as camadas quentes. Cubra cada taça com uma boa colher de natas azedas. Sirva quente, enquanto o queijo ainda está mole.',
      ru:'Доведите подсолённую воду до кипения и всыпьте кукурузную крупу тонкой струйкой, энергично взбивая, чтобы не было комков. Варите на слабом огне, часто помешивая деревянной ложкой, около 20 минут до густоты и гладкости. Выложите половину в миски, раскрошите сверху половину брынзы, затем добавьте остальную поленту и оставшуюся брынзу, чтобы она расплавилась между тёплыми слоями. Увенчайте каждую миску щедрой ложкой сметаны. Подавайте горячим, пока брынза ещё мягкая.',
      ar:'اغلِ الماء المملّح وأضف دقيق الذرة تدريجياً مع الخفق القوي لتجنّب التكتل. اطهه على نار هادئة مع التحريك المتكرر بملعقة خشب نحو 20 دقيقة حتى يثخن ويصبح ناعماً. ضع النصف في أوعية، فتّت فوقه نصف الجبن، ثم أضف باقي البولنتا والجبن المتبقي ليذوب بين الطبقات الدافئة. توّج كل وعاء بملعقة سخية من القشدة الحامضة. قدّمه ساخناً والجبن ما زال طرياً.',
      zh:'把盐水烧开，玉米粉呈细流状缓缓倒入，用力搅打以免结块。小火边煮边用木勺常搅约20分钟，至浓稠顺滑。先盛一半到碗里，撒上一半奶酪碎，再加入剩下的玉米粥和剩余奶酪，让奶酪在温热的两层间融化。每碗顶上放一大勺酸奶油。趁热、奶酪还软时食用。',
      ja:'塩水を沸かし、コーンミールを細く流し入れながら、だまにならないよう力強く混ぜる。弱火で木べらでよく混ぜながら約20分、とろりと滑らかになるまで煮る。半量を器に盛り、チーズの半量を崩してのせ、残りのポレンタと残りのチーズを重ねて温かい層の間で溶かす。各器にサワークリームをたっぷり一さじのせる。チーズが柔らかいうちに熱々で供する。',
      hi:'नमकीन पानी उबालें और मक्के का आटा धार बनाकर डालते हुए ज़ोर से फेंटें ताकि गुठलियाँ न बनें। धीमी आँच पर लकड़ी के चम्मच से बार-बार चलाते हुए लगभग 20 मिनट गाढ़ा और चिकना होने तक पकाएँ। आधा हिस्सा कटोरों में डालें, ऊपर आधी चीज़ चूरा करें, फिर बची पोलेंटा और बची चीज़ डालें ताकि गरम परतों के बीच पिघल जाए। हर कटोरे पर एक भरपूर चम्मच खट्टी क्रीम डालें। गरमागरम, चीज़ के नरम रहते ही परोसें।',
      tr:'Tuzlu suyu kaynatın ve mısır ununu ince ince dökerek topaklanmasın diye kuvvetlice çırpın. Kısık ateşte tahta kaşıkla sık karıştırarak yaklaşık 20 dakika koyulaşıp pürüzsüz olana dek pişirin. Yarısını kâselere alın, üzerine peynirin yarısını ufalayın, sonra kalan lapayı ve kalan peyniri ekleyin ki sıcak katlar arasında erisin. Her kâseyi bol bir kaşık ekşi krema ile taçlandırın. Peynir hâlâ yumuşakken sıcak servis edin.',
      it:'Porta a bollore l’acqua salata e versa la farina di mais a pioggia, frustando con forza per evitare grumi. Cuoci a fuoco basso, mescolando spesso con un cucchiaio di legno, per circa 20 minuti finché è densa e liscia. Metti metà nelle ciotole, sbriciola sopra metà del formaggio, poi aggiungi il resto della polenta e il formaggio rimasto perché fonda tra gli strati caldi. Corona ogni ciotola con una generosa cucchiaiata di panna acida. Servi calda, finché il formaggio è ancora morbido.',
      ko:'소금물을 끓이고 옥수수가루를 가늘게 흘려 넣으며 덩어리지지 않게 세게 저어준다. 약불에서 나무 주걱으로 자주 저으며 약 20분간 되직하고 매끈해질 때까지 끓인다. 절반을 그릇에 담고 치즈 절반을 부숴 올린 뒤, 남은 폴렌타와 남은 치즈를 더해 따뜻한 층 사이에서 녹게 한다. 각 그릇에 사워크림을 넉넉히 한 숟갈 올린다. 치즈가 부드러울 때 뜨겁게 낸다.' } },

  { id:'budget_008', name:NAMES.ardei, servings:2, prep:20, cook:45, costRon:5, nut:{cal:340,prot:7,carb:55,fat:11,fib:7}, tags:['budget','vegan','family'],
    ing:[ {q:4,n:I.bellPepper}, {q:120,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:200,u:'g',n:I.passata}, {q:3,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Taie capacele ardeilor și scoate semințele. Călește ceapa tocată și morcovul ras în ulei 5 minute, apoi adaugă orezul clătit și mai gătește 2 minute; potrivește de sare. Umple ardeii lejer cu compoziția de orez, fiindcă se umflă la fiert, și așază-i în picioare într-o oală. Toarnă roșiile pasate în jurul lor cu apă cât să-i acopere aproape complet și fierbe blând, acoperit, circa 40 de minute, până ardeii sunt fragezi și orezul e fiert. Stropește-i o dată-de două ori cu sos și servește cald, cu sosul turnat deasupra.',
      en:'Cut the tops off the peppers and scoop out the seeds. Soften the chopped onion and grated carrot in the oil for 5 minutes, then stir in the rinsed rice and cook for 2 minutes; season with salt. Fill the peppers loosely with the rice mixture, since it swells as it cooks, and stand them upright in a pot. Pour the tomato passata around them with enough water to nearly cover, and simmer gently, covered, for about 40 minutes until the peppers are tender and the rice is done. Baste once or twice, and serve warm with the sauce spooned over.',
      es:'Corta la parte superior de los pimientos y retira las semillas. Sofríe la cebolla picada y la zanahoria rallada en el aceite 5 minutos, añade el arroz enjuagado y cocina 2 minutos; sazona con sal. Rellena los pimientos sin apretar, porque el arroz crece al cocer, y colócalos de pie en una olla. Vierte el tomate alrededor con agua hasta casi cubrirlos y cuece tapado a fuego suave unos 40 minutos, hasta que estén tiernos y el arroz cocido. Riega una o dos veces con la salsa y sirve caliente con la salsa por encima.',
      fr:'Coupez le chapeau des poivrons et retirez les graines. Faites revenir l’oignon haché et la carotte râpée dans l’huile 5 minutes, ajoutez le riz rincé et faites cuire 2 minutes ; salez. Remplissez les poivrons sans tasser, car le riz gonfle à la cuisson, et posez-les debout dans une casserole. Versez les tomates passées autour avec de l’eau pour les couvrir presque, et laissez mijoter à couvert à feu doux environ 40 minutes jusqu’à ce que les poivrons soient tendres et le riz cuit. Arrosez une ou deux fois de sauce et servez chaud, nappé de sauce.',
      de:'Von den Paprika die Deckel abschneiden und die Kerne entfernen. Zwiebel gehackt und Karotte gerieben im Öl 5 Minuten anschwitzen, den abgespülten Reis zugeben und 2 Minuten mitkochen; salzen. Die Paprika locker mit der Reismischung füllen, da der Reis beim Garen aufquillt, und aufrecht in einen Topf stellen. Die passierten Tomaten mit so viel Wasser darum gießen, dass sie fast bedeckt sind, und zugedeckt bei niedriger Hitze etwa 40 Minuten köcheln, bis die Paprika weich und der Reis gar ist. Ein- bis zweimal mit Soße übergießen und warm servieren, mit Soße darüber.',
      pt:'Corte a tampa dos pimentos e retire as sementes. Refogue a cebola picada e a cenoura ralada no óleo 5 minutos, junte o arroz lavado e cozinhe 2 minutos; tempere com sal. Recheie os pimentos sem apertar, pois o arroz incha ao cozer, e ponha-os em pé numa panela. Deite o tomate passata à volta com água quase a cobrir e cozinhe tapado em lume brando cerca de 40 minutos, até os pimentos ficarem macios e o arroz cozido. Regue uma ou duas vezes com o molho e sirva quente, com o molho por cima.',
      ru:'Срежьте у перцев верхушки и удалите семена. Обжарьте нарезанный лук и тёртую морковь в масле 5 минут, добавьте промытый рис и готовьте 2 минуты; посолите. Наполните перцы неплотно, так как рис разбухает, и поставьте их вертикально в кастрюлю. Влейте вокруг протёртые томаты с водой почти до покрытия и тушите под крышкой на слабом огне около 40 минут, пока перцы не станут мягкими, а рис готовым. Полейте раз-другой соусом и подавайте тёплыми, полив соусом.',
      ar:'اقطع رؤوس الفلفل وأخرج البذور. شوّح البصل المفروم والجزر المبشور في الزيت 5 دقائق، أضف الأرز المغسول واطهه دقيقتين؛ ملّح. احشُ الفلفل بارتخاء لأن الأرز ينتفخ عند الطهي، وارصّه واقفاً في قدر. اسكب الطماطم المهروسة حوله مع ماء يكاد يغمره واطهه مغطى على نار هادئة نحو 40 دقيقة حتى يلين الفلفل وينضج الأرز. اسقِه بالصلصة مرة أو مرتين وقدّمه دافئاً مع الصلصة فوقه.',
      zh:'切下甜椒顶盖，去籽。用油炒切碎的洋葱和擦丝的胡萝卜5分钟，加入洗好的米再炒2分钟，加盐调味。把米馅松松地填入甜椒（米受热会膨胀），竖着码进锅中。四周倒入番茄泥并加水至几乎没过，加盖小火炖约40分钟，至甜椒软、米熟。中途浇一两次汤汁，趁热连汤汁一起上桌。',
      ja:'ピーマンの上部を切り取り、種を除く。みじん切りの玉ねぎとすりおろしたにんじんを油で5分炒め、洗った米を加えて2分炒める；塩で味付けする。米は煮ると膨らむのでゆるめに詰め、鍋に立てて並べる。周りにトマトピューレを注ぎ、ほぼかぶるまで水を足し、ふたをして弱火で約40分、ピーマンが柔らかく米が炊けるまで煮る。途中で1〜2回ソースをかけ、ソースをかけて温かいうちに供する。',
      hi:'शिमला मिर्च के ऊपरी हिस्से काटकर बीज निकालें। कटा प्याज़ और कद्दूकस गाजर तेल में 5 मिनट भूनें, धुला चावल डालकर 2 मिनट पकाएँ; नमक डालें। मिर्च को ढीला भरें क्योंकि चावल पकते समय फूलता है, और बर्तन में खड़ा रखें। चारों ओर टमाटर प्यूरी डालें और लगभग ढकने तक पानी डालें, ढककर धीमी आँच पर लगभग 40 मिनट पकाएँ जब तक मिर्च नरम और चावल पक जाए। एक-दो बार सॉस से सींचें और ऊपर सॉस डालकर गरम परोसें।',
      tr:'Biberlerin kapaklarını kesip çekirdeklerini çıkarın. Doğranmış soğan ve rendelenmiş havucu yağda 5 dakika kavurun, yıkanmış pirinci ekleyip 2 dakika pişirin; tuzlayın. Pirinç pişerken şişeceği için biberleri gevşek doldurun ve tencerede dik dizin. Etraflarına domates püresini dökün, neredeyse örtene kadar su ekleyin ve kapağı kapalı kısık ateşte yaklaşık 40 dakika, biberler yumuşayıp pirinç pişene dek pişirin. Bir iki kez sosla gezdirin ve üzerine sos dökerek sıcak servis edin.',
      it:'Taglia la calotta ai peperoni e togli i semi. Fai appassire cipolla tritata e carota grattugiata nell’olio per 5 minuti, unisci il riso sciacquato e cuoci 2 minuti; sala. Riempi i peperoni senza pressare, perché il riso gonfia in cottura, e mettili in piedi in una pentola. Versa intorno la passata con acqua quasi a coprirli e fai sobbollire coperto a fuoco basso circa 40 minuti, finché i peperoni sono teneri e il riso cotto. Bagnali una o due volte col sugo e servi caldi, col sugo sopra.',
      ko:'파프리카 윗부분을 잘라내고 씨를 제거한다. 다진 양파와 채 썬 당근을 기름에 5분 볶고 헹군 쌀을 넣어 2분 볶은 뒤 소금으로 간한다. 쌀은 익으며 부푸니 느슨하게 채우고 냄비에 세워 담는다. 주위에 토마토 퓌레를 붓고 거의 잠길 만큼 물을 더해 뚜껑을 덮고 약불에서 약 40분, 파프리카가 부드럽고 쌀이 익을 때까지 끓인다. 한두 번 소스를 끼얹고 소스를 위에 부어 따뜻하게 낸다.' } },

  { id:'budget_009', name:NAMES.zacusca, servings:2, prep:25, cook:60, costRon:4, nut:{cal:220,prot:3,carb:16,fat:16,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:400,u:'g',n:I.eggplant}, {q:3,n:I.bellPepper}, {q:2,n:I.onion}, {q:150,u:'g',n:I.passata}, {q:5,u:'tbsp',n:I.oil}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Coace vinetele și ardeii întregi până coaja se arde și miezul se înmoaie, circa 30 de minute, apoi curăță-i și toacă-i mărunt. Călește ceapa tocată în ulei la foc mic până se înmoaie și se rumenește, circa 10 minute. Adaugă legumele coapte, roșiile pasate și foaia de dafin și gătește blând, amestecând des ca să nu se prindă, circa 40 de minute, până se închide la culoare, se îngroașă și uleiul iese deasupra. Potrivește de sare și scoate foaia de dafin. Servește rece, întinsă gros pe pâine — se ține câteva zile la frigider.',
      en:'Roast the eggplants and peppers whole until their skins char and the flesh softens, about 30 minutes, then peel and chop them finely. Fry the chopped onion in the oil over low heat until soft and golden, about 10 minutes. Add the roasted vegetables, the tomato passata and the bay leaf, and cook gently, stirring often so it doesn’t catch, for about 40 minutes until it darkens, thickens, and the oil rises to the top. Season with salt to taste and discard the bay leaf. Serve cool, spread thickly on bread — it keeps for days in the fridge.',
      es:'Asa las berenjenas y los pimientos enteros hasta que la piel se queme y la pulpa se ablande, unos 30 minutos, pélalos y pícalos fino. Sofríe la cebolla picada en el aceite a fuego bajo hasta que esté blanda y dorada, unos 10 minutos. Añade las verduras asadas, el tomate y la hoja de laurel y cocina suave, removiendo a menudo para que no se pegue, unos 40 minutos hasta que oscurezca, espese y el aceite suba a la superficie. Sazona con sal y retira el laurel. Sirve fría, untada gruesa en pan — se conserva días en la nevera.',
      fr:'Faites rôtir les aubergines et poivrons entiers jusqu’à ce que la peau soit carbonisée et la chair molle, environ 30 minutes, puis pelez-les et hachez-les finement. Faites revenir l’oignon haché dans l’huile à feu doux jusqu’à ce qu’il soit tendre et doré, environ 10 minutes. Ajoutez les légumes rôtis, les tomates passées et la feuille de laurier et faites cuire doucement, en remuant souvent pour que ça n’attache pas, environ 40 minutes jusqu’à ce que ça fonce, épaississe et que l’huile remonte. Salez et retirez le laurier. Servez froid, tartiné épais sur du pain — se garde plusieurs jours au frais.',
      de:'Auberginen und Paprika im Ganzen rösten, bis die Haut verkohlt und das Fruchtfleisch weich ist, etwa 30 Minuten, dann schälen und fein hacken. Die gehackte Zwiebel im Öl bei niedriger Hitze weich und goldbraun braten, etwa 10 Minuten. Das geröstete Gemüse, die passierten Tomaten und das Lorbeerblatt zugeben und sanft köcheln, oft rühren, damit nichts ansetzt, etwa 40 Minuten, bis es dunkler und dicker wird und das Öl obenauf steigt. Mit Salz abschmecken und das Lorbeerblatt entfernen. Kühl servieren, dick aufs Brot gestrichen — hält sich tagelang im Kühlschrank.',
      pt:'Asse as beringelas e os pimentos inteiros até a pele queimar e a polpa amolecer, cerca de 30 minutos, depois descasque e pique fino. Refogue a cebola picada no óleo em lume baixo até ficar macia e dourada, cerca de 10 minutos. Junte os legumes assados, o tomate passata e a folha de louro e cozinhe devagar, mexendo com frequência para não pegar, cerca de 40 minutos até escurecer, engrossar e o óleo subir. Tempere com sal e retire o louro. Sirva fria, barrada grossa no pão — dura dias no frigorífico.',
      ru:'Запеките баклажаны и перцы целиком, пока кожица не обуглится, а мякоть не станет мягкой, около 30 минут, затем очистите и мелко нарежьте. Обжарьте нарезанный лук в масле на слабом огне до мягкости и золотистости, около 10 минут. Добавьте запечённые овощи, протёртые томаты и лавровый лист и готовьте на слабом огне, часто помешивая, чтобы не пригорело, около 40 минут, пока масса не потемнеет, не загустеет и масло не выступит сверху. Посолите по вкусу и удалите лавровый лист. Подавайте холодной, намазав толстым слоем на хлеб — хранится несколько дней в холодильнике.',
      ar:'اشوِ الباذنجان والفلفل كاملاً حتى تتفحّم القشرة ويلين اللبّ، نحو 30 دقيقة، ثم قشّرهما وافرمهما ناعماً. شوّح البصل المفروم في الزيت على نار هادئة حتى يلين ويذهبّ، نحو 10 دقائق. أضف الخضار المشوية والطماطم المهروسة وورقة الغار واطهها بهدوء مع التحريك المتكرر كي لا تلتصق، نحو 40 دقيقة حتى تغمق وتثخن ويطفو الزيت. تبّل بالملح وأخرج ورقة الغار. قدّمها باردة مدهونة بسمك على الخبز — تبقى أياماً في الثلاجة.',
      zh:'把茄子和甜椒整只烤到表皮焦黑、内里软烂，约30分钟，去皮切碎。洋葱末用油小火炒至变软金黄，约10分钟。加入烤好的蔬菜、番茄泥和香叶，小火慢煮并常搅动以免粘底，约40分钟，至颜色变深、变稠、油浮到表面。加盐调味，取出香叶。冷食，厚厚地抹在面包上——冷藏可放数日。',
      ja:'なすとパプリカを丸ごと、皮が真っ黒に焦げて中が柔らかくなるまで約30分焼き、皮をむいて細かく刻む。みじん切りの玉ねぎを油で弱火で柔らかく色づくまで約10分炒める。焼いた野菜、トマトピューレ、ローリエを加え、焦げ付かないようによく混ぜながら約40分、色が濃くなり、とろみがつき、油が上に浮くまで静かに煮る。塩で味を調え、ローリエを取り除く。冷やして、パンに厚く塗って供する——冷蔵庫で数日もつ。',
      hi:'बैंगन और शिमला मिर्च को साबुत तब तक भूनें जब तक छिलका जल जाए और गूदा नरम हो, लगभग 30 मिनट, फिर छीलकर बारीक काटें। कटा प्याज़ तेल में धीमी आँच पर नरम-सुनहरा होने तक लगभग 10 मिनट भूनें। भुनी सब्ज़ियाँ, टमाटर प्यूरी और तेज पत्ता डालें और बार-बार चलाते हुए लगभग 40 मिनट धीमी आँच पर पकाएँ जब तक रंग गहरा हो, गाढ़ा हो और तेल ऊपर आ जाए। नमक डालें और तेज पत्ता निकाल दें। ठंडा, ब्रेड पर मोटा लगाकर परोसें — फ्रिज में कई दिन चलता है।',
      tr:'Patlıcan ve biberleri bütün halde kabuğu kömürleşip içi yumuşayana dek yaklaşık 30 dakika közleyin, sonra soyup ince doğrayın. Doğranmış soğanı yağda kısık ateşte yumuşayıp kızarana dek yaklaşık 10 dakika kavurun. Közlenmiş sebzeleri, domates püresini ve defne yaprağını ekleyip dibe tutmasın diye sık karıştırarak yaklaşık 40 dakika, koyulaşıp rengi kararana ve yağ üste çıkana dek pişirin. Tuzla tatlandırın ve defne yaprağını çıkarın. Soğuk, ekmeğe kalınca sürerek servis edin — buzdolabında günlerce durur.',
      it:'Arrostisci melanzane e peperoni interi finché la buccia si brucia e la polpa si ammorbidisce, circa 30 minuti, poi sbuccia e trita fine. Rosola la cipolla tritata nell’olio a fuoco basso finché è morbida e dorata, circa 10 minuti. Unisci le verdure arrostite, la passata e l’alloro e cuoci piano, mescolando spesso perché non attacchi, circa 40 minuti finché scurisce, si addensa e l’olio affiora. Regola di sale e togli l’alloro. Servi fredda, spalmata spessa sul pane — si conserva giorni in frigo.',
      ko:'가지와 파프리카를 통째로 껍질이 새까맣게 타고 속이 물러질 때까지 약 30분 구운 뒤 껍질을 벗겨 곱게 다진다. 다진 양파를 기름에 약불로 부드럽고 노릇해질 때까지 약 10분 볶는다. 구운 채소, 토마토 퓌레, 월계수 잎을 넣고 눌어붙지 않게 자주 저으며 약 40분, 색이 진해지고 걸쭉해지며 기름이 위로 뜰 때까지 은근히 끓인다. 소금으로 간하고 월계수 잎을 건진다. 차갑게, 빵에 두껍게 발라 낸다 — 냉장고에서 며칠 간다.' } },

  { id:'budget_010', name:NAMES.sarmale, servings:2, prep:25, cook:60, costRon:4, nut:{cal:320,prot:7,carb:52,fat:9,fib:8}, tags:['budget','vegan','family'],
    ing:[ {q:500,u:'g',n:I.cabbage}, {q:120,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:150,u:'g',n:I.passata}, {q:3,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Desprinde foile de varză și opărește-le scurt, ca să se înmoaie și să se ruleze fără să crape. Călește ceapa tocată și morcovul ras în ulei 5 minute, adaugă orezul clătit și jumătate din roșiile pasate și mai gătește 2 minute; potrivește de sare. Pune câte o lingură de umplutură pe fiecare foaie și rulează strâns, îndoind marginile. Așază sarmalele lipite într-o oală, toarnă peste ele restul de roșii pasate și apă cât să le acopere și fierbe blând, acoperit, circa o oră, până varza e fragedă și orezul fiert. Servește cald, tradițional cu mămăligă.',
      en:'Separate the cabbage leaves and blanch them briefly so they soften and roll without cracking. Soften the chopped onion and grated carrot in the oil for 5 minutes, stir in the rinsed rice and half the tomato passata, and cook 2 minutes; season with salt. Put a spoonful of filling on each leaf and roll into a snug parcel, tucking in the sides. Pack the rolls tightly in a pot, pour over the rest of the passata and enough water to cover, and simmer gently, covered, for about an hour until the cabbage is tender and the rice is cooked. Serve warm, traditionally with polenta.',
      es:'Separa las hojas de repollo y escáldalas brevemente para que se ablanden y se enrollen sin romperse. Sofríe la cebolla picada y la zanahoria rallada en el aceite 5 minutos, añade el arroz enjuagado y la mitad del tomate y cocina 2 minutos; sazona con sal. Pon una cucharada de relleno en cada hoja y enrolla apretado, metiendo los lados. Coloca los rollos bien juntos en una olla, cúbrelos con el resto del tomate y agua y cuece tapado a fuego suave una hora, hasta que el repollo esté tierno y el arroz cocido. Sirve caliente, tradicionalmente con polenta.',
      fr:'Détachez les feuilles de chou et blanchissez-les brièvement pour qu’elles s’assouplissent et s’enroulent sans se déchirer. Faites revenir l’oignon haché et la carotte râpée dans l’huile 5 minutes, ajoutez le riz rincé et la moitié des tomates passées et faites cuire 2 minutes ; salez. Déposez une cuillerée de farce sur chaque feuille et roulez serré en rentrant les côtés. Rangez les rouleaux bien serrés dans une casserole, couvrez du reste de tomates et d’eau, et laissez mijoter à couvert environ une heure jusqu’à ce que le chou soit tendre et le riz cuit. Servez chaud, traditionnellement avec de la polenta.',
      de:'Die Kohlblätter ablösen und kurz blanchieren, damit sie weich werden und sich ohne Reißen rollen lassen. Zwiebel gehackt und Karotte gerieben im Öl 5 Minuten anschwitzen, den abgespülten Reis und die Hälfte der passierten Tomaten zugeben und 2 Minuten mitkochen; salzen. Auf jedes Blatt einen Löffel Füllung geben und fest einrollen, die Seiten einschlagen. Die Rouladen dicht in einen Topf schichten, mit den restlichen Tomaten und Wasser bedecken und zugedeckt etwa eine Stunde sanft köcheln, bis der Kohl weich und der Reis gar ist. Warm servieren, traditionell mit Polenta.',
      pt:'Separe as folhas de couve e escalde-as rapidamente para amolecerem e enrolarem sem rachar. Refogue a cebola picada e a cenoura ralada no óleo 5 minutos, junte o arroz lavado e metade do tomate e cozinhe 2 minutos; tempere com sal. Ponha uma colher de recheio em cada folha e enrole bem apertado, dobrando os lados. Disponha os rolinhos bem juntos numa panela, cubra com o resto do tomate e água e cozinhe tapado em lume brando cerca de uma hora, até a couve ficar macia e o arroz cozido. Sirva quente, tradicionalmente com polenta.',
      ru:'Отделите капустные листья и бланшируйте их недолго, чтобы они размякли и сворачивались, не ломаясь. Обжарьте нарезанный лук и тёртую морковь в масле 5 минут, добавьте промытый рис и половину протёртых томатов и готовьте 2 минуты; посолите. На каждый лист положите ложку начинки и сверните плотно, подгибая края. Уложите голубцы плотно в кастрюлю, залейте оставшимися томатами и водой до покрытия и тушите под крышкой около часа, пока капуста не станет мягкой, а рис готовым. Подавайте тёплыми, традиционно с полентой.',
      ar:'افصل أوراق الملفوف واسلقها قليلاً كي تلين وتُلف دون أن تتشقق. شوّح البصل المفروم والجزر المبشور في الزيت 5 دقائق، أضف الأرز المغسول ونصف الطماطم المهروسة واطهه دقيقتين؛ ملّح. ضع ملعقة حشوة على كل ورقة ولفّها بإحكام مع طيّ الجوانب. ارصّ اللفائف متلاصقة في قدر، اسكب فوقها باقي الطماطم وماء يغمرها واطهها مغطاة على نار هادئة نحو ساعة حتى يلين الملفوف وينضج الأرز. قدّمها دافئة، وتقليدياً مع عصيدة الذرة.',
      zh:'把卷心菜叶剥下，稍微焯一下使其变软、卷时不裂。用油炒切碎的洋葱和擦丝的胡萝卜5分钟，加入洗好的米和一半番茄泥再炒2分钟，加盐调味。每片叶子上放一勺馅，收边卷紧。把菜卷紧密码进锅里，倒入剩余番茄泥并加水没过，加盖小火炖约一小时，至卷心菜软、米熟。趁热食用，传统上配玉米粥。',
      ja:'キャベツの葉をはがし、さっと湯通しして、割れずに巻けるよう柔らかくする。みじん切りの玉ねぎとすりおろしにんじんを油で5分炒め、洗った米とトマトピューレの半量を加えて2分炒める；塩で味付けする。各葉に大さじ1杯の詰め物をのせ、両端を折り込んできつく巻く。ロールを鍋に隙間なく詰め、残りのトマトピューレとかぶるくらいの水を注ぎ、ふたをして弱火で約1時間、キャベツが柔らかく米が炊けるまで煮る。温かいうちに、伝統的にはポレンタを添えて供する。',
      hi:'पत्ता गोभी की पत्तियाँ अलग करें और थोड़ा उबालें ताकि नरम हों और बिना फटे लिपट जाएँ। कटा प्याज़ और कद्दूकस गाजर तेल में 5 मिनट भूनें, धुला चावल और आधी टमाटर प्यूरी डालकर 2 मिनट पकाएँ; नमक डालें। हर पत्ती पर एक चम्मच भरावन रखें और किनारे मोड़ते हुए कसकर रोल करें। रोल को बर्तन में सटाकर रखें, ऊपर बची टमाटर प्यूरी और ढकने तक पानी डालें, ढककर धीमी आँच पर लगभग एक घंटा पकाएँ जब तक गोभी नरम और चावल पक जाए। गरम, परंपरागत रूप से पोलेंटा/मामालीगा के साथ परोसें।',
      tr:'Lahana yapraklarını ayırın ve kısa süre haşlayarak yumuşayıp çatlamadan sarılacak hale getirin. Doğranmış soğan ve rendelenmiş havucu yağda 5 dakika kavurun, yıkanmış pirinci ve domates püresinin yarısını ekleyip 2 dakika pişirin; tuzlayın. Her yaprağa bir kaşık iç koyup kenarları katlayarak sıkıca sarın. Sarmaları tencereye sıkışık dizin, üzerine kalan domatesi ve örtecek kadar su ekleyin ve kapağı kapalı kısık ateşte yaklaşık bir saat, lahana yumuşayıp pirinç pişene dek pişirin. Sıcak, geleneksel olarak mısır lapasıyla servis edin.',
      it:'Stacca le foglie di cavolo e sbollentale brevemente perché si ammorbidiscano e si arrotolino senza rompersi. Fai appassire cipolla tritata e carota grattugiata nell’olio per 5 minuti, unisci il riso sciacquato e metà della passata e cuoci 2 minuti; sala. Metti un cucchiaio di ripieno su ogni foglia e arrotola stretto, ripiegando i lati. Disponi gli involtini fitti in una pentola, coprili con il resto della passata e acqua e fai sobbollire coperto circa un’ora, finché il cavolo è tenero e il riso cotto. Servi caldo, tradizionalmente con la polenta.',
      ko:'양배추 잎을 떼어 살짝 데쳐 부드럽게 하여 찢어지지 않게 말 수 있도록 한다. 다진 양파와 채 썬 당근을 기름에 5분 볶고 헹군 쌀과 토마토 퓌레 절반을 넣어 2분 볶은 뒤 소금으로 간한다. 각 잎에 소를 한 숟갈 올리고 양옆을 접어 단단히 만다. 롤을 냄비에 촘촘히 담고 남은 토마토 퓌레와 잠길 만큼의 물을 부어 뚜껑을 덮고 약불에서 약 1시간, 양배추가 부드럽고 쌀이 익을 때까지 끓인다. 따뜻하게, 전통적으로 폴렌타와 함께 낸다.' } },
  { id:'budget_011', name:NAMES.linte, servings:2, prep:10, cook:35, costRon:4, nut:{cal:340,prot:18,carb:50,fat:8,fib:16}, tags:['budget','vegan','high-protein'],
    ing:[ {q:250,u:'g',n:I.lentils}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {q:1,n:I.carrot}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {n:I.salt} ],
    steps:{
      ro:'Clătește lintea și alege eventualele impurități. Călește ceapa tocată, usturoiul și morcovul ras în ulei la foc mediu 5 minute. Adaugă lintea, roșiile pasate și foaia de dafin, apoi toarnă apă cât să acopere cu două degete. Fierbe blând, parțial acoperit, circa 30 de minute, până lintea e moale și sosul s-a îngroșat, adăugând un strop de apă dacă scade prea mult. Scoate foaia de dafin, potrivește de sare și servește cald, cu pâine.',
      en:'Rinse the lentils and pick out any grit. Soften the chopped onion, garlic and grated carrot in the oil over medium heat for 5 minutes. Stir in the lentils, the tomato passata and the bay leaf, then pour in enough water to cover by two fingers. Simmer gently, partly covered, for about 30 minutes until the lentils are soft and the sauce has thickened, adding a splash of water if it dries out. Discard the bay leaf, season with salt, and serve warm with bread.',
      es:'Enjuaga las lentejas y retira cualquier impureza. Sofríe la cebolla picada, el ajo y la zanahoria rallada en el aceite a fuego medio 5 minutos. Añade las lentejas, el tomate triturado y la hoja de laurel, y cubre con agua dos dedos por encima. Cuece a fuego suave, parcialmente tapado, unos 30 minutos hasta que las lentejas estén blandas y la salsa espese, añadiendo un poco de agua si se seca. Retira el laurel, sala y sirve caliente con pan.',
      fr:'Rincez les lentilles et retirez les impuretés. Faites revenir l’oignon haché, l’ail et la carotte râpée dans l’huile à feu moyen 5 minutes. Ajoutez les lentilles, les tomates passées et la feuille de laurier, puis couvrez d’eau à deux doigts au-dessus. Laissez mijoter à couvert partiel environ 30 minutes jusqu’à ce que les lentilles soient tendres et la sauce épaisse, en ajoutant un peu d’eau si ça sèche. Retirez le laurier, salez et servez chaud avec du pain.',
      de:'Die Linsen abspülen und verlesen. Zwiebel gehackt, Knoblauch und geriebene Karotte im Öl bei mittlerer Hitze 5 Minuten anschwitzen. Die Linsen, die passierten Tomaten und das Lorbeerblatt zugeben, dann mit Wasser bedecken, zwei Finger breit darüber. Zugedeckt bei schwacher Hitze etwa 30 Minuten köcheln, bis die Linsen weich sind und die Soße eindickt; bei Bedarf etwas Wasser zugeben. Das Lorbeerblatt entfernen, salzen und warm mit Brot servieren.',
      pt:'Enxágue as lentilhas e retire eventuais impurezas. Refogue a cebola picada, o alho e a cenoura ralada no óleo em lume médio 5 minutos. Junte as lentilhas, o tomate passata e a folha de louro, e cubra com água dois dedos acima. Cozinhe em lume brando, parcialmente tapado, cerca de 30 minutos até as lentilhas ficarem macias e o molho engrossar, juntando um pouco de água se secar. Retire o louro, tempere com sal e sirva quente com pão.',
      ru:'Промойте чечевицу и переберите. Обжарьте нарезанный лук, чеснок и тёртую морковь в масле на среднем огне 5 минут. Добавьте чечевицу, протёртые томаты и лавровый лист, затем залейте водой на два пальца выше. Тушите под неполной крышкой около 30 минут, пока чечевица не станет мягкой, а соус не загустеет, подливая воду при необходимости. Удалите лавровый лист, посолите и подавайте тёплым с хлебом.',
      ar:'اغسل العدس وأزل الشوائب. شوّح البصل المفروم والثوم والجزر المبشور في الزيت على نار متوسطة 5 دقائق. أضف العدس والطماطم المهروسة وورقة الغار، ثم غطِّ بالماء بمقدار إصبعين فوقه. اطهه على نار هادئة مع تغطية جزئية نحو 30 دقيقة حتى يلين العدس وتثخن الصلصة، مع إضافة قليل من الماء إذا جفّ. أخرج ورقة الغار وملّح وقدّمه دافئاً مع الخبز.',
      zh:'把扁豆冲洗干净，挑去杂质。中火用油把切碎的洋葱、蒜和擦丝的胡萝卜炒5分钟。加入扁豆、番茄泥和香叶，再加水没过约两指高。半盖小火炖约30分钟，至扁豆软烂、汤汁变稠，太干就加点水。取出香叶，加盐调味，配面包趁热食用。',
      ja:'レンズ豆を洗い、混じり物を取り除く。みじん切りの玉ねぎ、にんにく、すりおろしにんじんを油で中火で5分炒める。レンズ豆、トマトピューレ、ローリエを加え、指二本分かぶるくらいの水を注ぐ。半分ふたをして弱火で約30分、レンズ豆が柔らかくソースがとろりとするまで煮る（乾いたら水を足す）。ローリエを取り除き、塩で味を調え、パンを添えて温かいうちに供する。',
      hi:'मसूर दाल धोकर कंकड़ निकाल लें। कटा प्याज़, लहसुन और कद्दूकस गाजर तेल में मध्यम आँच पर 5 मिनट भूनें। दाल, टमाटर प्यूरी और तेज पत्ता डालें, फिर दो उँगली ऊपर तक पानी डालें। आंशिक ढककर धीमी आँच पर लगभग 30 मिनट पकाएँ जब तक दाल नरम और ग्रेवी गाढ़ी हो जाए, सूखने पर थोड़ा पानी डालें। तेज पत्ता निकालें, नमक डालें और गरम, ब्रेड के साथ परोसें।',
      tr:'Mercimeği yıkayıp ayıklayın. Doğranmış soğan, sarımsak ve rendelenmiş havucu yağda orta ateşte 5 dakika kavurun. Mercimek, domates püresi ve defne yaprağını ekleyin, üzerini iki parmak geçecek kadar suyla örtün. Yarı kapalı, kısık ateşte yaklaşık 30 dakika, mercimek yumuşayıp sos koyulaşana dek pişirin; kuruyunca biraz su ekleyin. Defne yaprağını çıkarın, tuzlayın ve ekmekle sıcak servis edin.',
      it:'Sciacqua le lenticchie e togli eventuali impurità. Fai appassire la cipolla tritata, l’aglio e la carota grattugiata nell’olio a fuoco medio per 5 minuti. Unisci le lenticchie, la passata e l’alloro, poi copri con acqua due dita sopra. Cuoci a fuoco basso, semicoperto, circa 30 minuti finché le lenticchie sono morbide e il sugo si addensa, aggiungendo un po’ d’acqua se asciuga. Togli l’alloro, sala e servi caldo con il pane.',
      ko:'렌틸콩을 헹구고 이물질을 골라낸다. 다진 양파, 마늘, 채 썬 당근을 기름에 중불로 5분 볶는다. 렌틸콩, 토마토 퓌레, 월계수 잎을 넣고 두 손가락 높이만큼 물을 붓는다. 뚜껑을 반쯤 덮고 약불에서 약 30분, 렌틸콩이 부드러워지고 소스가 걸쭉해질 때까지 끓인다(마르면 물을 조금 추가). 월계수 잎을 건지고 소금으로 간해 빵과 함께 따뜻하게 낸다.' } },

  { id:'budget_012', name:NAMES.pilaf, servings:2, prep:10, cook:25, costRon:4, nut:{cal:380,prot:7,carb:68,fat:9,fib:4}, tags:['budget','vegan','family'],
    ing:[ {q:200,u:'g',n:I.rice}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:1,n:I.bellPepper}, {q:3,u:'tbsp',n:I.oil}, {q:400,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Clătește orezul până apa e limpede, apoi scurge-l. Călește ceapa tocată, morcovul ras și ardeiul tăiat cubulețe în ulei 5 minute, apoi adaugă orezul și prăjește-l 2 minute, cât să lucească boabele. Toarnă apa, pune un praf bun de sare și adu la fiert. Acoperă, dă focul la minim și fierbe neatins circa 18 minute, până apa e absorbită. Ia de pe foc și lasă acoperit 10 minute, apoi afânează cu furculița și servește.',
      en:'Rinse the rice until the water runs clear, then drain. Soften the chopped onion, grated carrot and diced pepper in the oil for 5 minutes, then stir in the rice and toast it for 2 minutes so the grains glisten. Pour in the water, add a good pinch of salt, and bring to a boil. Cover, turn the heat right down, and cook undisturbed for about 18 minutes until the water is absorbed. Take off the heat and let it stand, covered, for 10 minutes, then fluff with a fork and serve.',
      es:'Enjuaga el arroz hasta que el agua salga clara y escúrrelo. Sofríe la cebolla picada, la zanahoria rallada y el pimiento en dados en el aceite 5 minutos, añade el arroz y tuéstalo 2 minutos hasta que brille. Vierte el agua, añade una buena pizca de sal y lleva a ebullición. Tapa, baja el fuego al mínimo y cocina sin remover unos 18 minutos hasta que absorba el agua. Retira del fuego y deja reposar tapado 10 minutos, luego suelta con un tenedor y sirve.',
      fr:'Rincez le riz jusqu’à ce que l’eau soit claire, puis égouttez. Faites revenir l’oignon haché, la carotte râpée et le poivron en dés dans l’huile 5 minutes, ajoutez le riz et faites-le nacrer 2 minutes. Versez l’eau, ajoutez une bonne pincée de sel et portez à ébullition. Couvrez, baissez le feu au minimum et laissez cuire sans remuer environ 18 minutes jusqu’à absorption de l’eau. Retirez du feu, laissez reposer à couvert 10 minutes, puis égrenez à la fourchette et servez.',
      de:'Den Reis waschen, bis das Wasser klar ist, dann abtropfen lassen. Zwiebel gehackt, Karotte gerieben und Paprika gewürfelt im Öl 5 Minuten anschwitzen, den Reis zugeben und 2 Minuten glasig rösten. Das Wasser angießen, kräftig salzen und aufkochen. Zudecken, die Hitze ganz herunterdrehen und etwa 18 Minuten ohne Rühren garen, bis das Wasser aufgesogen ist. Vom Herd nehmen, zugedeckt 10 Minuten ruhen lassen, mit der Gabel auflockern und servieren.',
      pt:'Lave o arroz até a água sair limpa e escorra. Refogue a cebola picada, a cenoura ralada e o pimento aos cubos no óleo 5 minutos, junte o arroz e frite 2 minutos até brilhar. Deite a água, tempere com uma boa pitada de sal e leve a ferver. Tape, reduza o lume ao mínimo e cozinhe sem mexer cerca de 18 minutos até absorver a água. Retire do lume, deixe repousar tapado 10 minutos, solte com um garfo e sirva.',
      ru:'Промойте рис до прозрачной воды и откиньте. Обжарьте нарезанный лук, тёртую морковь и перец кубиками в масле 5 минут, добавьте рис и обжаривайте 2 минуты до блеска зёрен. Влейте воду, посолите щедрой щепоткой и доведите до кипения. Накройте, убавьте огонь до минимума и готовьте не перемешивая около 18 минут, пока вода не впитается. Снимите с огня, дайте постоять под крышкой 10 минут, взрыхлите вилкой и подавайте.',
      ar:'اغسل الأرز حتى يصفو الماء ثم صفّه. شوّح البصل المفروم والجزر المبشور والفلفل المكعّب في الزيت 5 دقائق، أضف الأرز وحمّصه دقيقتين حتى يلمع. اسكب الماء وأضف رشة ملح جيدة وارفعه للغليان. غطّه، اخفض النار لأدنى درجة واطهه دون تحريك نحو 18 دقيقة حتى يتشرّب الماء. ارفعه عن النار واتركه مغطى 10 دقائق، ثم فكّكه بالشوكة وقدّمه.',
      zh:'把米淘洗至水清，沥干。用油炒切碎的洋葱、擦丝的胡萝卜和切丁的甜椒5分钟，加入米再炒2分钟至米粒发亮。倒入水，加一大撮盐，煮开。加盖转最小火，不翻动焖约18分钟，至水分收干。离火加盖静置10分钟，用叉子拨松后上桌。',
      ja:'米を水が澄むまで洗い、水を切る。みじん切りの玉ねぎ、すりおろしにんじん、角切りのパプリカを油で5分炒め、米を加えて2分、粒が艶やかになるまで炒める。水を注ぎ、塩をしっかりひとつまみ加えて沸騰させる。ふたをして火を最弱にし、混ぜずに約18分、水分がなくなるまで炊く。火から下ろし、ふたをして10分蒸らし、フォークでほぐして供する。',
      hi:'चावल को पानी साफ आने तक धोकर छान लें। कटा प्याज़, कद्दूकस गाजर और कटी शिमला मिर्च तेल में 5 मिनट भूनें, चावल डालकर 2 मिनट भूनें जब तक दाने चमकने लगें। पानी डालें, एक अच्छी चुटकी नमक डालें और उबाल लाएँ। ढककर आँच बिलकुल धीमी करें और बिना हिलाए लगभग 18 मिनट पकाएँ जब तक पानी सूख जाए। आँच से उतारकर ढककर 10 मिनट रखें, फिर काँटे से खिलाकर परोसें।',
      tr:'Pirinci suyu berraklaşana dek yıkayıp süzün. Doğranmış soğan, rendelenmiş havuç ve küp biberi yağda 5 dakika kavurun, pirinci ekleyip taneler parlayana dek 2 dakika kavurun. Suyu ekleyin, iyi bir tutam tuz atın ve kaynatın. Kapağı kapatıp ateşi en kısığa alın ve karıştırmadan yaklaşık 18 dakika, su çekilene dek pişirin. Ateşten alıp kapalı 10 dakika dinlendirin, çatalla kabartıp servis edin.',
      it:'Sciacqua il riso finché l’acqua è limpida, poi scola. Fai appassire la cipolla tritata, la carota grattugiata e il peperone a dadini nell’olio per 5 minuti, unisci il riso e tostalo 2 minuti finché i chicchi luccicano. Versa l’acqua, aggiungi una bella presa di sale e porta a bollore. Copri, abbassa al minimo e cuoci senza mescolare circa 18 minuti finché l’acqua è assorbita. Togli dal fuoco, lascia riposare coperto 10 minuti, sgrana con la forchetta e servi.',
      ko:'쌀을 물이 맑아질 때까지 씻어 물기를 뺀다. 다진 양파, 채 썬 당근, 깍둑 썬 파프리카를 기름에 5분 볶고 쌀을 넣어 2분, 쌀알이 반질해질 때까지 볶는다. 물을 붓고 소금을 넉넉히 한 꼬집 넣어 끓인다. 뚜껑을 덮고 불을 최소로 줄여 젓지 않고 약 18분, 물이 흡수될 때까지 익힌다. 불에서 내려 뚜껑을 덮은 채 10분 뜸을 들이고 포크로 살살 풀어 낸다.' } },

  { id:'budget_013', name:NAMES.varza, servings:2, prep:15, cook:45, costRon:3, nut:{cal:160,prot:4,carb:18,fat:9,fib:6}, tags:['budget','vegan','healthy'],
    ing:[ {q:600,u:'g',n:I.cabbage}, {q:1,n:I.onion}, {q:4,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:1,n:I.bayLeaf}, {q:1,u:'tsp',n:I.paprika}, {n:I.salt} ],
    steps:{
      ro:'Taie varza fideluță și ceapa solzișori. Călește ceapa în ulei 5 minute, apoi adaugă varza și gătește, amestecând des, până se înmoaie și începe să se rumenească, circa 10 minute. Adaugă roșiile pasate, foaia de dafin, boiaua și un praf bun de sare, pune un strop de apă și acoperă. Înăbușă la foc mic circa 30 de minute, amestecând din când în când, până varza e foarte moale și ușor caramelizată. Descoperă în ultimele minute ca să scadă lichidul și servește cald.',
      en:'Shred the cabbage finely and slice the onion. Soften the onion in the oil for 5 minutes, then add the cabbage and cook, stirring often, until it wilts and begins to colour, about 10 minutes. Stir in the tomato passata, the bay leaf, the paprika and a good pinch of salt, add a splash of water, and cover. Braise gently for about 30 minutes, stirring now and then, until the cabbage is very soft and lightly caramelised. Uncover for the last few minutes to cook off the liquid, and serve warm.',
      es:'Corta el repollo en tiras finas y la cebolla en pluma. Sofríe la cebolla en el aceite 5 minutos, añade el repollo y cocina, removiendo a menudo, hasta que se ablande y empiece a dorarse, unos 10 minutos. Incorpora el tomate triturado, la hoja de laurel, el pimentón y una buena pizca de sal, añade un poco de agua y tapa. Guisa a fuego suave unos 30 minutos, removiendo de vez en cuando, hasta que el repollo esté muy tierno y ligeramente caramelizado. Destapa los últimos minutos para reducir el líquido y sirve caliente.',
      fr:'Émincez finement le chou et l’oignon. Faites revenir l’oignon dans l’huile 5 minutes, ajoutez le chou et faites cuire en remuant souvent jusqu’à ce qu’il tombe et commence à dorer, environ 10 minutes. Incorporez les tomates passées, le laurier, le paprika et une bonne pincée de sel, ajoutez un peu d’eau et couvrez. Laissez braiser à feu doux environ 30 minutes, en remuant de temps en temps, jusqu’à ce que le chou soit très tendre et légèrement caramélisé. Découvrez les dernières minutes pour réduire le liquide et servez chaud.',
      de:'Den Kohl fein hobeln und die Zwiebel in Streifen schneiden. Die Zwiebel im Öl 5 Minuten anschwitzen, den Kohl zugeben und unter häufigem Rühren etwa 10 Minuten garen, bis er zusammenfällt und Farbe annimmt. Passierte Tomaten, Lorbeerblatt, Paprikapulver und eine kräftige Prise Salz einrühren, einen Schuss Wasser zugeben und zudecken. Bei schwacher Hitze etwa 30 Minuten schmoren, gelegentlich umrühren, bis der Kohl sehr weich und leicht karamellisiert ist. Zum Schluss den Deckel abnehmen, damit die Flüssigkeit einkocht, und warm servieren.',
      pt:'Corte a couve em tiras finas e a cebola às meias-luas. Refogue a cebola no óleo 5 minutos, junte a couve e cozinhe, mexendo com frequência, até murchar e começar a dourar, cerca de 10 minutos. Junte o tomate passata, a folha de louro, o colorau e uma boa pitada de sal, adicione um pouco de água e tape. Estufe em lume brando cerca de 30 minutos, mexendo de vez em quando, até a couve ficar muito macia e ligeiramente caramelizada. Destape nos últimos minutos para reduzir o líquido e sirva quente.',
      ru:'Нашинкуйте капусту тонко и нарежьте лук полукольцами. Обжарьте лук в масле 5 минут, добавьте капусту и готовьте, часто помешивая, пока не осядет и не начнёт румяниться, около 10 минут. Вмешайте протёртые томаты, лавровый лист, паприку и щедрую щепотку соли, влейте немного воды и накройте. Тушите на слабом огне около 30 минут, изредка помешивая, пока капуста не станет очень мягкой и слегка карамелизуется. В последние минуты снимите крышку, чтобы выпарить жидкость, и подавайте тёплой.',
      ar:'قطّع الملفوف شرائح رفيعة والبصل شرائح. شوّح البصل في الزيت 5 دقائق، أضف الملفوف واطهه مع التحريك المتكرر حتى يذبل ويبدأ بالتحمّر، نحو 10 دقائق. أضف الطماطم المهروسة وورقة الغار والبابريكا ورشة ملح جيدة، أضف قليلاً من الماء وغطِّ. اطهه على نار هادئة نحو 30 دقيقة مع التحريك أحياناً حتى يلين الملفوف جداً ويتكرمل قليلاً. اكشف الغطاء في الدقائق الأخيرة لتبخير السائل وقدّمه دافئاً.',
      zh:'把卷心菜切细丝，洋葱切丝。用油炒洋葱5分钟，加入卷心菜，常翻炒约10分钟，至变软并开始上色。拌入番茄泥、香叶、红椒粉和一大撮盐，加一点水后加盖。小火焖约30分钟，偶尔翻动，至卷心菜非常软烂、微微焦糖化。最后几分钟开盖收汁，趁热食用。',
      ja:'キャベツを細切りにし、玉ねぎを薄切りにする。玉ねぎを油で5分炒め、キャベツを加えてよく混ぜながら約10分、しんなりして色づき始めるまで炒める。トマトピューレ、ローリエ、パプリカ、塩ひとつまみをしっかり混ぜ、水を少し加えてふたをする。弱火で約30分、時々混ぜながら、キャベツがとても柔らかく軽く色づくまで蒸し煮にする。最後の数分はふたを取って水分を飛ばし、温かいうちに供する。',
      hi:'पत्तागोभी को बारीक काटें और प्याज़ को पतला काटें। प्याज़ को तेल में 5 मिनट भूनें, पत्तागोभी डालें और बार-बार चलाते हुए लगभग 10 मिनट भूनें जब तक नरम होकर हल्की सुनहरी होने लगे। टमाटर प्यूरी, तेज पत्ता, पेपरिका और एक अच्छी चुटकी नमक मिलाएँ, थोड़ा पानी डालकर ढक दें। धीमी आँच पर लगभग 30 मिनट पकाएँ, बीच-बीच में चलाते हुए, जब तक पत्तागोभी बहुत नरम और हल्की कैरामेलाइज़ हो जाए। आखिरी कुछ मिनट ढक्कन हटाकर तरल सुखाएँ और गरम परोसें।',
      tr:'Lahanayı ince kıyın, soğanı dilimleyin. Soğanı yağda 5 dakika kavurun, lahanayı ekleyip sık karıştırarak yaklaşık 10 dakika, suyunu salıp renk almaya başlayana dek pişirin. Domates püresi, defne yaprağı, toz biber ve iyi bir tutam tuz ekleyin, biraz su katıp kapağını kapatın. Kısık ateşte yaklaşık 30 dakika, arada karıştırarak, lahana iyice yumuşayıp hafif karamelize olana dek pişirin. Son dakikalarda kapağı açıp suyunu çekin ve sıcak servis edin.',
      it:'Taglia il cavolo a striscioline sottili e la cipolla a fette. Fai appassire la cipolla nell’olio 5 minuti, unisci il cavolo e cuoci, mescolando spesso, finché appassisce e inizia a colorire, circa 10 minuti. Unisci la passata, l’alloro, la paprica e una bella presa di sale, aggiungi un po’ d’acqua e copri. Brasa a fuoco basso circa 30 minuti, mescolando ogni tanto, finché il cavolo è molto morbido e leggermente caramellato. Scopri negli ultimi minuti per far ritirare il liquido e servi caldo.',
      ko:'양배추를 곱게 채 썰고 양파를 얇게 썬다. 양파를 기름에 5분 볶고 양배추를 넣어 자주 저으며 약 10분, 숨이 죽고 색이 나기 시작할 때까지 볶는다. 토마토 퓌레, 월계수 잎, 파프리카 가루, 소금 넉넉히 한 꼬집을 섞고 물을 조금 넣어 뚜껑을 덮는다. 약불에서 약 30분, 가끔 저으며 양배추가 아주 부드럽고 살짝 캐러멜화될 때까지 조린다. 마지막 몇 분은 뚜껑을 열어 수분을 날리고 따뜻하게 낸다.' } },

  { id:'budget_014', name:NAMES.oua, servings:2, prep:5, cook:15, costRon:4, nut:{cal:250,prot:14,carb:11,fat:16,fib:3}, tags:['budget','vegetarian','quick'],
    ing:[ {q:4,n:I.eggs}, {q:400,u:'g',n:I.tomatoes}, {q:1,n:I.bellPepper}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Toacă ceapa, taie ardeiul cubulețe și roșiile bucățele. Călește ceapa și ardeiul în ulei la foc mediu 5 minute, apoi adaugă roșiile și un praf de sare și gătește până se transformă într-un sos gros, circa 8 minute. Bate ușor ouăle, toarnă-le peste legume și amestecă blând cu o lingură de lemn până se leagă, dar rămân cremoase, circa 2 minute. Ia de pe foc cât încă sunt moi — se gătesc mai departe în tigaia fierbinte. Servește imediat, cu pâine.',
      en:'Chop the onion, dice the pepper and cut the tomatoes into small pieces. Soften the onion and pepper in the oil over medium heat for 5 minutes, then add the tomatoes and a pinch of salt and cook until they collapse into a thick sauce, about 8 minutes. Beat the eggs lightly, pour them over the vegetables, and stir gently with a wooden spoon until just set but still creamy, about 2 minutes. Take off the heat while soft — they keep cooking in the hot pan. Serve straight away with bread.',
      es:'Pica la cebolla, corta el pimiento en dados y los tomates en trozos pequeños. Sofríe la cebolla y el pimiento en el aceite a fuego medio 5 minutos, añade los tomates y una pizca de sal y cocina hasta que se deshagan en una salsa espesa, unos 8 minutos. Bate ligeramente los huevos, viértelos sobre las verduras y remueve con suavidad con una cuchara de madera hasta que cuajen pero sigan cremosos, unos 2 minutos. Retira del fuego cuando aún estén jugosos — siguen cocinándose en la sartén caliente. Sirve enseguida con pan.',
      fr:'Hachez l’oignon, coupez le poivron en dés et les tomates en petits morceaux. Faites revenir l’oignon et le poivron dans l’huile à feu moyen 5 minutes, ajoutez les tomates et une pincée de sel et faites cuire jusqu’à obtenir une sauce épaisse, environ 8 minutes. Battez légèrement les œufs, versez-les sur les légumes et remuez doucement à la cuillère en bois jusqu’à ce qu’ils prennent tout en restant crémeux, environ 2 minutes. Retirez du feu tant qu’ils sont moelleux — ils continuent de cuire dans la poêle chaude. Servez aussitôt avec du pain.',
      de:'Die Zwiebel hacken, die Paprika würfeln und die Tomaten klein schneiden. Zwiebel und Paprika im Öl bei mittlerer Hitze 5 Minuten anschwitzen, die Tomaten und eine Prise Salz zugeben und kochen, bis sie zu einer dicken Soße zerfallen, etwa 8 Minuten. Die Eier leicht verquirlen, über das Gemüse gießen und mit einem Holzlöffel sanft rühren, bis sie gerade stocken, aber cremig bleiben, etwa 2 Minuten. Vom Herd nehmen, solange sie weich sind — sie garen in der heißen Pfanne nach. Sofort mit Brot servieren.',
      pt:'Pique a cebola, corte o pimento aos cubos e os tomates em pedaços pequenos. Refogue a cebola e o pimento no óleo em lume médio 5 minutos, junte os tomates e uma pitada de sal e cozinhe até desfazerem num molho espesso, cerca de 8 minutos. Bata ligeiramente os ovos, deite-os sobre os legumes e mexa com suavidade com uma colher de pau até ganharem consistência mas ficarem cremosos, cerca de 2 minutos. Retire do lume enquanto ainda macios — continuam a cozer na frigideira quente. Sirva de imediato com pão.',
      ru:'Нарежьте лук, нарежьте перец кубиками и порежьте помидоры небольшими кусочками. Обжарьте лук и перец в масле на среднем огне 5 минут, добавьте помидоры и щепотку соли и готовьте, пока они не разварятся в густой соус, около 8 минут. Слегка взбейте яйца, вылейте их на овощи и осторожно помешивайте деревянной ложкой, пока не схватятся, но останутся нежными, около 2 минут. Снимите с огня, пока мягкие — они дойдут на горячей сковороде. Подавайте сразу с хлебом.',
      ar:'افرم البصل، وقطّع الفلفل مكعّبات والطماطم قطعاً صغيرة. شوّح البصل والفلفل في الزيت على نار متوسطة 5 دقائق، أضف الطماطم ورشة ملح واطهها حتى تتحوّل إلى صلصة كثيفة، نحو 8 دقائق. اخفق البيض قليلاً، اسكبه فوق الخضار وحرّكه برفق بملعقة خشب حتى يتماسك مع بقائه طرياً، نحو دقيقتين. ارفعه عن النار وهو طري — يستمر في النضج في المقلاة الساخنة. قدّمه فوراً مع الخبز.',
      zh:'洋葱切碎，甜椒切丁，番茄切小块。中火用油炒洋葱和甜椒5分钟，加入番茄和一撮盐，煮约8分钟至化成浓稠的酱。把鸡蛋略微打散，倒在蔬菜上，用木勺轻轻搅动约2分钟，至刚凝固但仍嫩滑。趁蛋还软时离火——在热锅里会继续熟。配面包立即上桌。',
      ja:'玉ねぎをみじん切りにし、パプリカを角切り、トマトを小さく切る。玉ねぎとパプリカを油で中火で5分炒め、トマトと塩ひとつまみを加えて約8分、とろりとしたソースになるまで煮る。卵を軽く溶き、野菜に流し入れ、木べらでやさしく混ぜて、固まりつつもとろりとするまで約2分火を通す。柔らかいうちに火から下ろす——熱いフライパンで火が入り続ける。すぐにパンを添えて供する。',
      hi:'प्याज़ काटें, शिमला मिर्च को क्यूब में और टमाटर छोटे टुकड़ों में काटें। प्याज़ और शिमला मिर्च को तेल में मध्यम आँच पर 5 मिनट भूनें, टमाटर और एक चुटकी नमक डालें और लगभग 8 मिनट पकाएँ जब तक गाढ़ी चटनी बन जाए। अंडों को हल्का फेंटें, सब्ज़ियों के ऊपर डालें और लकड़ी के चम्मच से हल्के हाथ से लगभग 2 मिनट चलाएँ जब तक जम जाएँ पर मलाईदार रहें। नरम रहते ही आँच से उतारें — गरम पैन में पकते रहते हैं। तुरंत ब्रेड के साथ परोसें।',
      tr:'Soğanı doğrayın, biberi küp doğrayın ve domatesleri küçük parçalara kesin. Soğan ve biberi yağda orta ateşte 5 dakika kavurun, domatesleri ve bir tutam tuzu ekleyip koyu bir sos olana dek yaklaşık 8 dakika pişirin. Yumurtaları hafifçe çırpın, sebzelerin üzerine dökün ve tahta kaşıkla nazikçe, tutana ama kremamsı kalana dek yaklaşık 2 dakika karıştırın. Yumuşakken ateşten alın — sıcak tavada pişmeye devam eder. Hemen ekmekle servis edin.',
      it:'Trita la cipolla, taglia il peperone a dadini e i pomodori a pezzetti. Fai appassire la cipolla e il peperone nell’olio a fuoco medio 5 minuti, unisci i pomodori e un pizzico di sale e cuoci finché si disfano in un sugo denso, circa 8 minuti. Sbatti leggermente le uova, versale sulle verdure e mescola delicatamente con un cucchiaio di legno finché rapprendono ma restano cremose, circa 2 minuti. Togli dal fuoco quando sono ancora morbide — continuano a cuocere nella padella calda. Servi subito con il pane.',
      ko:'양파를 다지고 파프리카를 깍둑 썰고 토마토를 작게 썬다. 양파와 파프리카를 기름에 중불로 5분 볶고 토마토와 소금 한 꼬집을 넣어 약 8분, 걸쭉한 소스가 될 때까지 익힌다. 달걀을 가볍게 풀어 채소 위에 붓고 나무 주걱으로 부드럽게 약 2분, 막 엉기되 크리미함이 남을 때까지 저어준다. 부드러울 때 불에서 내린다 — 뜨거운 팬에서 계속 익는다. 빵을 곁들여 바로 낸다.' } },

  { id:'budget_015', name:NAMES.macaroane, servings:2, prep:5, cook:15, costRon:5, nut:{cal:460,prot:16,carb:60,fat:16,fib:3}, tags:['budget','vegetarian','quick'],
    ing:[ {q:250,u:'g',n:I.pasta}, {q:150,u:'g',n:I.cheese}, {q:100,u:'g',n:I.sourCream}, {q:30,u:'g',n:I.butter}, {n:I.salt} ],
    steps:{
      ro:'Fierbe macaroanele în apă cu sare până sunt moi, apoi scurge-le. Cât sunt fierbinți, amestecă-le cu untul până se topește și le acoperă. Sfărâmă cea mai mare parte din brânză peste paste și amestecă, ca să se înmoaie de la căldură. Servește în boluri, cu restul de brânză sfărâmată deasupra și o lingură generoasă de smântână. Mănâncă imediat, cât sunt calde.',
      en:'Boil the macaroni in salted water until tender, then drain. While still hot, toss the pasta with the butter until it melts and coats it. Crumble most of the cheese over the pasta and fold it through so it softens in the heat. Serve in bowls, topped with the rest of the crumbled cheese and a generous spoon of sour cream. Eat straight away, while hot.',
      es:'Cuece los macarrones en agua con sal hasta que estén tiernos, luego escúrrelos. Aún calientes, mézclalos con la mantequilla hasta que se derrita y los cubra. Desmenuza la mayor parte del queso sobre la pasta y remueve para que se ablande con el calor. Sirve en boles, con el resto del queso desmenuzado por encima y una buena cucharada de crema agria. Come enseguida, mientras esté caliente.',
      fr:'Faites cuire les macaronis dans l’eau salée jusqu’à ce qu’ils soient tendres, puis égouttez. Encore chauds, mélangez-les avec le beurre jusqu’à ce qu’il fonde et les enrobe. Émiettez la majeure partie du fromage sur les pâtes et mélangez pour qu’il ramollisse à la chaleur. Servez dans des bols, parsemés du reste de fromage émietté et d’une belle cuillerée de crème aigre. Mangez aussitôt, bien chaud.',
      de:'Die Makkaroni in Salzwasser weich kochen, dann abgießen. Noch heiß mit der Butter mischen, bis sie schmilzt und alles überzieht. Den größten Teil des Käses über die Nudeln bröseln und unterheben, damit er in der Wärme weich wird. In Schalen anrichten, mit dem restlichen zerbröckelten Käse und einem großzügigen Löffel Schmand bestreuen. Sofort heiß essen.',
      pt:'Coza o macarrão em água com sal até ficar macio, depois escorra. Ainda quente, envolva-o na manteiga até derreter e cobrir tudo. Esfarele a maior parte do queijo sobre a massa e misture para amolecer com o calor. Sirva em taças, com o resto do queijo esfarelado por cima e uma boa colher de natas azedas. Coma de imediato, bem quente.',
      ru:'Отварите макароны в подсолённой воде до мягкости, затем откиньте. Пока горячие, перемешайте их со сливочным маслом, чтобы оно растаяло и обволокло. Раскрошите большую часть брынзы на макароны и перемешайте, чтобы она размягчилась от тепла. Подавайте в мисках, посыпав оставшейся брынзой и добавив щедрую ложку сметаны. Ешьте сразу, пока горячо.',
      ar:'اسلق المعكرونة في ماء مملّح حتى تلين ثم صفّها. وهي ساخنة، اخلطها بالزبدة حتى تذوب وتغلّفها. فتّت معظم الجبن فوق المعكرونة وقلّبه ليلين بالحرارة. قدّمها في أوعية، وانثر فوقها باقي الجبن المفتّت وملعقة سخية من القشدة الحامضة. كُلها فوراً وهي ساخنة.',
      zh:'把通心粉在盐水中煮软，沥干。趁热与黄油拌匀，让黄油融化裹住面。把大部分奶酪掰碎撒在面上，拌匀让它借热变软。盛入碗中，撒上剩下的碎奶酪和一大勺酸奶油。趁热立即食用。',
      ja:'マカロニを塩湯で柔らかくなるまで茹で、湯を切る。熱いうちにバターと和え、溶けて全体に絡める。チーズの大部分を崩してのせ、熱で柔らかくなるように混ぜる。器に盛り、残りの崩したチーズとサワークリームをたっぷりのせる。熱いうちにすぐ食べる。',
      hi:'मैकरोनी को नमकीन पानी में नरम होने तक उबालें, फिर छान लें। गरम रहते ही मक्खन के साथ मिलाएँ ताकि पिघलकर लिपट जाए। अधिकांश चीज़ को पास्ता पर चूरा करें और मिलाएँ ताकि गरमी से नरम हो जाए। कटोरों में परोसें, ऊपर बची चूरा चीज़ और एक भरपूर चम्मच खट्टी क्रीम डालें। गरमागरम तुरंत खाएँ।',
      tr:'Makarnayı tuzlu suda yumuşayana dek haşlayıp süzün. Sıcakken tereyağıyla karıştırın, erisin ve her yanı kaplasın. Peynirin çoğunu makarnanın üzerine ufalayın ve sıcakla yumuşaması için karıştırın. Kâselere alın, üzerine kalan ufalanmış peyniri ve bol bir kaşık ekşi kremayı serpin. Sıcakken hemen yiyin.',
      it:'Lessa i maccheroni in acqua salata finché sono teneri, poi scola. Ancora caldi, mescolali con il burro finché si scioglie e li avvolge. Sbriciola gran parte del formaggio sulla pasta e mescola perché si ammorbidisca col calore. Servi nelle ciotole, con il resto del formaggio sbriciolato sopra e una generosa cucchiaiata di panna acida. Mangia subito, ben caldo.',
      ko:'마카로니를 소금물에 부드러워질 때까지 삶아 물기를 뺀다. 뜨거울 때 버터와 버무려 녹아 고루 입혀지게 한다. 치즈 대부분을 파스타 위에 부숴 넣고 열로 부드러워지게 섞는다. 그릇에 담고 남은 부순 치즈와 사워크림 넉넉히 한 숟갈을 올린다. 뜨거울 때 바로 먹는다.' } },
  { id:'budget_016', name:NAMES.supaCrema, servings:2, prep:10, cook:30, costRon:3, nut:{cal:180,prot:4,carb:28,fat:6,fib:5}, tags:['budget','vegan','healthy'],
    ing:[ {q:300,u:'g',n:I.potatoes}, {q:2,n:I.carrot}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.oil}, {q:700,u:'ml',n:I.water}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Curăță și taie cuburi cartofii, morcovii și ceapa. Călește ceapa în ulei 5 minute, apoi adaugă cartofii și morcovii și toarnă apa. Potrivește de sare și fierbe acoperit circa 25 de minute, până totul e foarte moale. Pasează cu blenderul până devine o cremă fină și catifelată, subțiind cu puțină apă fierbinte dacă e prea groasă, apoi mai potrivește de sare. Servește fierbinte, cu pătrunjel tocat deasupra și, dacă vrei, un fir de ulei.',
      en:'Peel and dice the potatoes, carrots and onion. Soften the onion in the oil for 5 minutes, then add the potatoes and carrots and pour in the water. Season with salt and simmer, covered, for about 25 minutes until everything is very soft. Blend until smooth and silky, loosening with a little hot water if too thick, then check the salt. Serve hot, scattered with chopped parsley and, if you like, a drizzle of oil.',
      es:'Pela y corta en dados las patatas, las zanahorias y la cebolla. Sofríe la cebolla en el aceite 5 minutos, añade las patatas y las zanahorias y vierte el agua. Sazona con sal y cuece tapado unos 25 minutos hasta que todo esté muy blando. Tritura hasta obtener una crema fina y sedosa, aflojando con un poco de agua caliente si está muy espesa, y rectifica de sal. Sirve caliente, con perejil picado por encima y, si quieres, un hilo de aceite.',
      fr:'Épluchez et coupez en dés les pommes de terre, les carottes et l’oignon. Faites revenir l’oignon dans l’huile 5 minutes, ajoutez les pommes de terre et les carottes et versez l’eau. Salez et laissez cuire à couvert environ 25 minutes jusqu’à ce que tout soit très tendre. Mixez jusqu’à obtenir un velouté fin et soyeux, en détendant avec un peu d’eau chaude si c’est trop épais, puis rectifiez le sel. Servez chaud, parsemé de persil haché et, si vous voulez, d’un filet d’huile.',
      de:'Kartoffeln, Karotten und Zwiebel schälen und würfeln. Die Zwiebel im Öl 5 Minuten anschwitzen, Kartoffeln und Karotten zugeben und das Wasser angießen. Salzen und zugedeckt etwa 25 Minuten köcheln, bis alles sehr weich ist. Fein und samtig pürieren, bei Bedarf mit etwas heißem Wasser verdünnen, dann mit Salz abschmecken. Heiß servieren, mit gehackter Petersilie bestreut und nach Belieben einem Spritzer Öl.',
      pt:'Descasque e corte em cubos as batatas, as cenouras e a cebola. Refogue a cebola no óleo 5 minutos, junte as batatas e as cenouras e deite a água. Tempere com sal e cozinhe tapado cerca de 25 minutos até tudo ficar muito macio. Triture até obter um creme fino e sedoso, soltando com um pouco de água quente se estiver muito espesso, e acerte o sal. Sirva quente, com salsa picada por cima e, se quiser, um fio de azeite.',
      ru:'Очистите и нарежьте кубиками картофель, морковь и лук. Обжарьте лук в масле 5 минут, добавьте картофель и морковь и влейте воду. Посолите и варите под крышкой около 25 минут, пока всё не станет очень мягким. Пробейте блендером до гладкого шелковистого крема, разбавляя горячей водой, если слишком густо, и досолите по вкусу. Подавайте горячим, посыпав рубленой петрушкой и, по желанию, сбрызнув маслом.',
      ar:'قشّر وقطّع البطاطا والجزر والبصل مكعّبات. شوّح البصل في الزيت 5 دقائق، أضف البطاطا والجزر واسكب الماء. ملّح واطهه مغطى نحو 25 دقيقة حتى يلين كل شيء تماماً. اخلطه بالخلاط حتى يصبح كريمة ناعمة حريرية، وخفّفه بقليل من الماء الساخن إن كان ثخيناً، ثم عدّل الملح. قدّمه ساخناً مع البقدونس المفروم فوقه ورشة زيت إن رغبت.',
      zh:'把土豆、胡萝卜和洋葱去皮切丁。用油炒洋葱5分钟，加入土豆和胡萝卜，倒入水。加盐，加盖煮约25分钟至全部非常软烂。用搅拌机打成细滑的浓汤，太稠就加点热水调稀，再调盐。趁热食用，撒上切碎的欧芹，喜欢的话淋一点油。',
      ja:'じゃがいも、にんじん、玉ねぎを皮をむいて角切りにする。玉ねぎを油で5分炒め、じゃがいもとにんじんを加えて水を注ぐ。塩をして、ふたをして約25分、すべてがとても柔らかくなるまで煮る。ブレンダーでなめらかなクリーム状にし、濃すぎれば熱湯で少しのばして塩で味を調える。熱々で、刻んだパセリを散らし、好みで油をひとたらしして供する。',
      hi:'आलू, गाजर और प्याज़ को छीलकर क्यूब में काटें। प्याज़ को तेल में 5 मिनट भूनें, आलू और गाजर डालें और पानी डालें। नमक डालकर ढककर लगभग 25 मिनट पकाएँ जब तक सब कुछ बहुत नरम हो जाए। ब्लेंडर से महीन और रेशमी क्रीम बना लें, ज़्यादा गाढ़ा हो तो थोड़ा गरम पानी डालें, फिर नमक ठीक करें। गरमागरम परोसें, ऊपर कटा पार्सले डालकर और चाहें तो थोड़ा तेल।',
      tr:'Patates, havuç ve soğanı soyup küp doğrayın. Soğanı yağda 5 dakika kavurun, patates ve havucu ekleyip suyu dökün. Tuzlayıp kapağı kapalı yaklaşık 25 dakika, her şey iyice yumuşayana dek pişirin. Blenderdan geçirip pürüzsüz, kadifemsi bir krema yapın, çok koyuysa biraz sıcak suyla açın ve tuzu ayarlayın. Sıcak servis edin, üzerine kıyılmış maydanoz serpip isterseniz bir çizgi yağ gezdirin.',
      it:'Sbuccia e taglia a dadini patate, carote e cipolla. Fai appassire la cipolla nell’olio 5 minuti, unisci patate e carote e versa l’acqua. Sala e cuoci coperto circa 25 minuti finché tutto è molto morbido. Frulla fino a ottenere una vellutata fine e setosa, allungando con un po’ d’acqua calda se troppo densa, poi aggiusta di sale. Servi calda, con prezzemolo tritato sopra e, se vuoi, un filo d’olio.',
      ko:'감자, 당근, 양파를 껍질 벗겨 깍둑 썬다. 양파를 기름에 5분 볶고 감자와 당근을 넣은 뒤 물을 붓는다. 소금 간을 하고 뚜껑을 덮어 약 25분, 모두 아주 부드러워질 때까지 끓인다. 블렌더로 곱고 매끈한 크림 상태로 갈고, 너무 되직하면 뜨거운 물을 조금 넣어 농도를 맞춘 뒤 소금으로 간한다. 뜨겁게, 다진 파슬리를 뿌리고 원하면 기름을 살짝 둘러 낸다.' } },

  { id:'budget_017', name:NAMES.pastai, servings:2, prep:10, cook:15, costRon:4, nut:{cal:150,prot:4,carb:12,fat:10,fib:5}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.greenBeans}, {q:3,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,n:I.lemon}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Curăță capetele păstăilor și fierbe-le în apă cu sare circa 10 minute, până sunt fragede, apoi scurge-le. Zdrobește usturoiul cu un praf de sare până devine pastă și amestecă-l cu uleiul, ca un fel de mujdei. Amestecă păstăile calde cu mujdeiul, ca să-l absoarbă, apoi stoarce lămâia deasupra și presară pătrunjel. Servește-le calde sau la temperatura camerei, ca masă ușoară cu pâine sau alături de orice.',
      en:'Top and tail the green beans and boil them in salted water for about 10 minutes until tender, then drain. Crush the garlic to a paste with a pinch of salt and stir in the oil to make a rough garlic dressing. Toss the warm beans with the garlic dressing so they soak it up, then squeeze over the lemon and scatter with parsley. Serve warm or at room temperature, as a light meal with bread or alongside anything.',
      es:'Limpia los extremos de las judías verdes y cuécelas en agua con sal unos 10 minutos, hasta que estén tiernas, luego escúrrelas. Machaca el ajo con una pizca de sal hasta hacer una pasta y mézclalo con el aceite, como un alioli rústico. Mezcla las judías calientes con el ajo para que lo absorban, exprime el limón por encima y espolvorea perejil. Sírvelas calientes o a temperatura ambiente, como comida ligera con pan o como acompañamiento.',
      fr:'Équeutez les haricots verts et faites-les cuire à l’eau salée environ 10 minutes, jusqu’à ce qu’ils soient tendres, puis égouttez. Écrasez l’ail avec une pincée de sel en pâte et mélangez-le à l’huile, comme une sauce à l’ail rustique. Mélangez les haricots chauds avec l’ail pour qu’ils l’absorbent, pressez le citron dessus et parsemez de persil. Servez-les chauds ou à température ambiante, en repas léger avec du pain ou en accompagnement.',
      de:'Die grünen Bohnen putzen und in Salzwasser etwa 10 Minuten weich kochen, dann abgießen. Den Knoblauch mit einer Prise Salz zu einer Paste zerdrücken und mit dem Öl verrühren, wie eine rustikale Knoblauchsoße. Die warmen Bohnen mit der Knoblauchsoße mischen, damit sie sie aufnehmen, dann die Zitrone darüber ausdrücken und mit Petersilie bestreuen. Warm oder bei Zimmertemperatur servieren, als leichtes Essen mit Brot oder als Beilage.',
      pt:'Limpe as pontas do feijão-verde e coza-o em água com sal cerca de 10 minutos, até ficar tenro, depois escorra. Esmague o alho com uma pitada de sal até formar pasta e misture-o com o azeite, como um alho rústico. Envolva o feijão quente no alho para o absorver, esprema o limão por cima e polvilhe com salsa. Sirva quente ou à temperatura ambiente, como refeição leve com pão ou como acompanhamento.',
      ru:'Обрежьте кончики стручковой фасоли и отварите её в подсолённой воде около 10 минут до мягкости, затем откиньте. Разотрите чеснок со щепоткой соли в пасту и смешайте с маслом — получится грубый чесночный соус. Перемешайте тёплую фасоль с чесночным соусом, чтобы она его впитала, выдавите сверху лимон и посыпьте петрушкой. Подавайте тёплой или комнатной температуры, как лёгкое блюдо с хлебом или на гарнир.',
      ar:'نظّف أطراف الفاصوليا الخضراء واسلقها في ماء مملّح نحو 10 دقائق حتى تلين ثم صفّها. اهرس الثوم مع رشة ملح حتى يصير معجوناً واخلطه بالزيت كصلصة ثوم ريفية. قلّب الفاصوليا الدافئة بصلصة الثوم لتتشرّبها، ثم اعصر الليمون فوقها وانثر البقدونس. قدّمها دافئة أو بحرارة الغرفة، كوجبة خفيفة مع الخبز أو كطبق جانبي.',
      zh:'把四季豆掐去两头，放盐水中煮约10分钟至变软，沥干。把蒜和一撮盐捣成蒜泥，拌入油，做成粗蒜酱。趁热把四季豆与蒜酱拌匀，让它吸收，再挤上柠檬汁、撒上欧芹。趁热或常温食用，配面包做清淡一餐，或作为配菜。',
      ja:'さやいんげんの筋を取り、塩湯で約10分、柔らかくなるまで茹でて水を切る。にんにくを塩ひとつまみとともにすりつぶしてペーストにし、油と混ぜて素朴なガーリックソースにする。温かいいんげんをガーリックソースと和えて吸わせ、レモンを搾りかけ、パセリを散らす。温かいうちか常温で、パンを添えた軽い一品として、または付け合わせとして供する。',
      hi:'हरी बीन्स के सिरे काटकर नमकीन पानी में लगभग 10 मिनट नरम होने तक उबालें, फिर छान लें। लहसुन को एक चुटकी नमक के साथ पीसकर पेस्ट बनाएँ और तेल में मिलाएँ, एक देहाती लहसुन सॉस की तरह। गरम बीन्स को लहसुन सॉस के साथ मिलाएँ ताकि सोख लें, ऊपर नींबू निचोड़ें और पार्सले छिड़कें। गरम या कमरे के तापमान पर परोसें, ब्रेड के साथ हल्के भोजन के रूप में या साइड डिश के रूप में।',
      tr:'Taze fasulyelerin uçlarını temizleyip tuzlu suda yaklaşık 10 dakika, yumuşayana dek haşlayın, sonra süzün. Sarımsağı bir tutam tuzla ezip macun yapın ve yağla karıştırarak köy usulü sarımsak sosu hazırlayın. Sıcak fasulyeleri sarımsak sosuyla karıştırıp emmesini sağlayın, üzerine limon sıkın ve maydanoz serpin. Sıcak ya da oda sıcaklığında, ekmekle hafif bir öğün olarak veya garnitür olarak servis edin.',
      it:'Spunta i fagiolini e lessali in acqua salata circa 10 minuti, finché sono teneri, poi scola. Schiaccia l’aglio con un pizzico di sale fino a una pasta e mescolalo con l’olio, come una salsa all’aglio rustica. Condisci i fagiolini caldi con la salsa all’aglio perché la assorbano, poi spremi sopra il limone e cospargi di prezzemolo. Servili caldi o a temperatura ambiente, come pasto leggero con il pane o come contorno.',
      ko:'그린빈의 양끝을 다듬어 소금물에 약 10분, 부드러워질 때까지 삶아 물기를 뺀다. 마늘을 소금 한 꼬집과 함께 으깨 페이스트로 만들고 기름과 섞어 투박한 마늘 소스를 만든다. 따뜻한 그린빈을 마늘 소스와 버무려 배어들게 한 뒤 레몬을 짜 뿌리고 파슬리를 뿌린다. 따뜻하게 또는 실온으로, 빵을 곁들인 가벼운 한 끼로 또는 곁들임으로 낸다.' } },

  { id:'budget_018', name:NAMES.cartofiCuptor, servings:2, prep:10, cook:40, costRon:3, nut:{cal:320,prot:6,carb:52,fat:11,fib:5}, tags:['budget','vegan','family'],
    ing:[ {q:700,u:'g',n:I.potatoes}, {q:3,u:'clove',n:I.garlic}, {q:4,u:'tbsp',n:I.oil}, {q:1,u:'tbsp',n:I.rosemary}, {q:1,u:'tsp',n:I.paprika}, {n:I.salt} ],
    steps:{
      ro:'Spală bine cartofii și taie-i sferturi (nu trebuie curățați). Amestecă-i într-o tavă cu uleiul, usturoiul zdrobit, rozmarinul, boiaua și sare din belșug, până sunt bine unși. Întinde-i într-un singur strat și coace-i la 200°C circa 40 de minute, întorcându-i o dată, până sunt bine rumeniți și crocanți la exterior, pufoși în interior. Servește-i fierbinți — sunt buni și simpli, cu o salată verde sau murături.',
      en:'Scrub the potatoes and cut them into wedges (no need to peel). Toss them in a roasting tin with the oil, the crushed garlic, the rosemary, the paprika and plenty of salt until well coated. Spread them out in a single layer and roast at 200°C for about 40 minutes, turning once, until deep golden and crisp outside, fluffy inside. Serve hot — great on their own with a green salad or pickles.',
      es:'Lava bien las patatas y córtalas en cuartos (no hace falta pelarlas). Mézclalas en una bandeja con el aceite, el ajo machacado, el romero, el pimentón y sal abundante, hasta que queden bien cubiertas. Extiéndelas en una sola capa y ásalas a 200°C unos 40 minutos, dándoles la vuelta una vez, hasta que estén bien doradas y crujientes por fuera y tiernas por dentro. Sírvelas calientes — están buenas solas, con una ensalada verde o encurtidos.',
      fr:'Lavez bien les pommes de terre et coupez-les en quartiers (inutile de les éplucher). Mélangez-les dans un plat avec l’huile, l’ail écrasé, le romarin, le paprika et beaucoup de sel, jusqu’à ce qu’elles soient bien enrobées. Étalez-les en une seule couche et faites-les rôtir à 200°C environ 40 minutes, en les retournant une fois, jusqu’à ce qu’elles soient bien dorées et croustillantes dehors, moelleuses dedans. Servez-les chaudes — délicieuses seules, avec une salade verte ou des pickles.',
      de:'Die Kartoffeln gut waschen und vierteln (Schälen ist nicht nötig). In einer Form mit dem Öl, dem zerdrückten Knoblauch, dem Rosmarin, dem Paprikapulver und reichlich Salz mischen, bis sie gut überzogen sind. In einer Schicht verteilen und bei 200 °C etwa 40 Minuten rösten, einmal wenden, bis sie außen tief goldbraun und knusprig, innen locker sind. Heiß servieren — auch pur lecker, mit grünem Salat oder Eingelegtem.',
      pt:'Lave bem as batatas e corte-as em quartos (não é preciso descascar). Misture-as num tabuleiro com o azeite, o alho esmagado, o alecrim, o colorau e sal generoso, até ficarem bem envolvidas. Espalhe-as numa só camada e asse a 200°C cerca de 40 minutos, virando uma vez, até ficarem bem douradas e crocantes por fora e fofas por dentro. Sirva quentes — ótimas sozinhas, com uma salada verde ou picles.',
      ru:'Хорошо вымойте картофель и нарежьте дольками (чистить не нужно). Перемешайте его в противне с маслом, раздавленным чесноком, розмарином, паприкой и щедрой солью, чтобы всё хорошо покрылось. Разложите в один слой и запекайте при 200 °C около 40 минут, один раз перевернув, пока картофель не станет золотистым и хрустящим снаружи и рассыпчатым внутри. Подавайте горячим — хорош и сам по себе, с зелёным салатом или соленьями.',
      ar:'اغسل البطاطا جيداً وقطّعها أرباعاً (دون تقشير). قلّبها في صينية مع الزيت والثوم المهروس وإكليل الجبل والبابريكا وملح وفير حتى تُغلَّف جيداً. افردها بطبقة واحدة واشوِها على 200 °م نحو 40 دقيقة، مع تقليبها مرة، حتى تذهبّ وتصبح مقرمشة من الخارج وطرية من الداخل. قدّمها ساخنة — لذيذة وحدها، مع سلطة خضراء أو مخللات.',
      zh:'把土豆洗净切成四块（不用去皮）。在烤盘里与油、拍碎的蒜、迷迭香、红椒粉和足量盐拌匀，让土豆均匀裹上。铺成一层，200°C烤约40分钟，中途翻一次，至外皮金黄酥脆、内里松软。趁热食用——单吃也很好，配绿沙拉或腌菜。',
      ja:'じゃがいもをよく洗い、四つ割りにする（皮はむかなくてよい）。天板で油、つぶしたにんにく、ローズマリー、パプリカ、たっぷりの塩と和え、全体にまとわせる。一層に広げ、200℃で約40分、途中で一度返しながら、外は濃いきつね色でカリッと、中はほくほくになるまで焼く。熱々で——そのままでも、グリーンサラダやピクルスを添えても美味しい。',
      hi:'आलू अच्छे से धोकर चार टुकड़ों में काटें (छीलने की ज़रूरत नहीं)। एक ट्रे में तेल, कुटा लहसुन, रोज़मेरी, पेपरिका और भरपूर नमक के साथ मिलाएँ ताकि अच्छी तरह लिपट जाएँ। एक परत में फैलाएँ और 200°C पर लगभग 40 मिनट भूनें, बीच में एक बार पलटें, जब तक बाहर से गहरे सुनहरे और कुरकुरे तथा अंदर से नरम हो जाएँ। गरम परोसें — अकेले भी बढ़िया, हरे सलाद या अचार के साथ।',
      tr:'Patatesleri iyice yıkayıp dörde bölün (soymaya gerek yok). Bir tepside yağ, ezilmiş sarımsak, biberiye, toz biber ve bolca tuzla, iyice kaplanana dek karıştırın. Tek kat halinde yayıp 200°C’de yaklaşık 40 dakika, bir kez çevirerek, dışı iyice kızarıp çıtırlaşana ve içi yumuşayana dek pişirin. Sıcak servis edin — tek başına da, yeşil salata veya turşuyla da nefis.',
      it:'Lava bene le patate e tagliale a spicchi (non serve pelarle). Condiscile in una teglia con l’olio, l’aglio schiacciato, il rosmarino, la paprica e sale abbondante, finché sono ben ricoperte. Distendile in un solo strato e arrostiscile a 200°C per circa 40 minuti, girandole una volta, finché sono ben dorate e croccanti fuori e morbide dentro. Servile calde — ottime da sole, con un’insalata verde o sottaceti.',
      ko:'감자를 잘 씻어 4등분한다(껍질은 벗기지 않아도 된다). 로스팅 팬에서 기름, 으깬 마늘, 로즈마리, 파프리카 가루, 넉넉한 소금과 버무려 고루 입힌다. 한 겹으로 펴고 200°C에서 약 40분, 한 번 뒤집으며 겉은 진한 갈색으로 바삭하고 속은 포슬포슬해질 때까지 굽는다. 뜨겁게 낸다 — 그대로도, 그린 샐러드나 피클과도 잘 어울린다.' } },

  { id:'budget_019', name:NAMES.chiftele, servings:2, prep:15, cook:20, costRon:4, nut:{cal:300,prot:8,carb:42,fat:12,fib:4}, tags:['budget','vegetarian','family'],
    ing:[ {q:500,u:'g',n:I.potatoes}, {q:1,n:I.eggs}, {q:3,u:'tbsp',n:I.flour}, {q:1,n:I.onion}, {q:2,u:'tbsp',n:I.parsley}, {q:4,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Fierbe cartofii întregi până sunt moi, apoi curăță-i, pasează-i și lasă-i să se răcorească puțin. Amestecă ceapa tocată mărunt, oul, făina și pătrunjelul și potrivește de sare, până obții o compoziție care se modelează. Cu mâinile ude, formează chiftele mici, apoi prăjește-le în ulei la foc mediu până sunt bine rumenite și crocante pe ambele părți, circa 3 minute pe parte. Scurge-le pe hârtie și servește-le calde.',
      en:'Boil the potatoes whole until tender, then peel and mash them and let them cool a little. Mix in the finely chopped onion, the egg, the flour and the parsley, and season with salt to a mixture you can shape. With wet hands, form small patties, then fry them in the oil over medium heat until deep golden and crisp on both sides, about 3 minutes a side. Drain on paper and serve warm.',
      es:'Cuece las patatas enteras hasta que estén tiernas, luego pélalas, aplástalas y déjalas enfriar un poco. Mezcla la cebolla muy picada, el huevo, la harina y el perejil, y sazona con sal hasta lograr una masa moldeable. Con las manos húmedas, forma tortitas pequeñas y fríelas en el aceite a fuego medio hasta que estén bien doradas y crujientes por ambos lados, unos 3 minutos por lado. Escúrrelas sobre papel y sírvelas calientes.',
      fr:'Faites cuire les pommes de terre entières jusqu’à ce qu’elles soient tendres, puis épluchez-les, écrasez-les et laissez-les tiédir un peu. Mélangez l’oignon finement haché, l’œuf, la farine et le persil, et salez jusqu’à obtenir une préparation façonnable. Les mains humides, formez de petites galettes, puis faites-les frire dans l’huile à feu moyen jusqu’à ce qu’elles soient bien dorées et croustillantes des deux côtés, environ 3 minutes par face. Égouttez-les sur du papier et servez chaud.',
      de:'Die Kartoffeln im Ganzen weich kochen, dann schälen, zerdrücken und etwas abkühlen lassen. Die fein gehackte Zwiebel, das Ei, das Mehl und die Petersilie untermischen und mit Salz zu einer formbaren Masse würzen. Mit feuchten Händen kleine Puffer formen, dann im Öl bei mittlerer Hitze auf beiden Seiten goldbraun und knusprig braten, etwa 3 Minuten pro Seite. Auf Papier abtropfen lassen und warm servieren.',
      pt:'Coza as batatas inteiras até ficarem macias, depois descasque, esmague e deixe arrefecer um pouco. Junte a cebola bem picada, o ovo, a farinha e a salsa, e tempere com sal até obter uma massa moldável. Com as mãos húmidas, forme bolinhos pequenos e frite-os no óleo em lume médio até ficarem bem dourados e crocantes dos dois lados, cerca de 3 minutos por lado. Escorra em papel e sirva quente.',
      ru:'Отварите картофель целиком до мягкости, затем очистите, разомните и дайте немного остыть. Вмешайте мелко нарезанный лук, яйцо, муку и петрушку и посолите до массы, которую можно лепить. Влажными руками сформуйте небольшие котлеты и обжарьте в масле на среднем огне до золотистой корочки с обеих сторон, около 3 минут на сторону. Обсушите на бумаге и подавайте тёплыми.',
      ar:'اسلق البطاطا كاملة حتى تلين، ثم قشّرها واهرسها واتركها تبرد قليلاً. أضف البصل المفروم ناعماً والبيضة والدقيق والبقدونس، وملّح حتى تحصل على عجينة قابلة للتشكيل. بأيدٍ مبلّلة، شكّل أقراصاً صغيرة، ثم اقليها في الزيت على نار متوسطة حتى تذهبّ وتقرمش على الوجهين، نحو 3 دقائق لكل وجه. صفّها على ورق وقدّمها دافئة.',
      zh:'把土豆整只煮软，去皮压成泥，稍微放凉。拌入切碎的洋葱、鸡蛋、面粉和欧芹，加盐调至可成形的面糊。手蘸水，捏成小饼，中火下油煎至两面金黄酥脆，每面约3分钟。用纸吸油，趁热食用。',
      ja:'じゃがいもを丸ごと柔らかく茹で、皮をむいてつぶし、少し冷ます。みじん切りの玉ねぎ、卵、小麦粉、パセリを混ぜ、塩で味を調えて形が作れる生地にする。濡らした手で小さなパティを作り、油で中火で両面がしっかり色づきカリッとするまで、片面約3分ずつ揚げ焼きにする。紙で油を切り、温かいうちに供する。',
      hi:'आलू को साबुत नरम होने तक उबालें, फिर छीलकर मैश करें और थोड़ा ठंडा होने दें। बारीक कटा प्याज़, अंडा, आटा और पार्सले मिलाएँ और नमक डालकर ऐसा मिश्रण बनाएँ जो आकार ले सके। गीले हाथों से छोटी टिक्की बनाएँ, फिर तेल में मध्यम आँच पर दोनों तरफ सुनहरा और कुरकुरा होने तक, हर तरफ लगभग 3 मिनट तलें। कागज़ पर निकालें और गरम परोसें।',
      tr:'Patatesleri bütün halde yumuşayana dek haşlayın, sonra soyup ezin ve biraz soğumaya bırakın. İnce doğranmış soğan, yumurta, un ve maydanozu karıştırın ve şekil alacak bir karışım olana dek tuzlayın. Islak elle küçük köfteler yapın, sonra yağda orta ateşte iki tarafı iyice kızarıp çıtırlaşana dek, her yüz için yaklaşık 3 dakika kızartın. Kâğıt üzerine alıp sıcak servis edin.',
      it:'Lessa le patate intere finché sono morbide, poi sbucciale, schiacciale e falle intiepidire un po’. Unisci la cipolla tritata fine, l’uovo, la farina e il prezzemolo, e sala fino a un composto modellabile. Con le mani umide forma piccole polpette, poi friggile nell’olio a fuoco medio finché sono ben dorate e croccanti su entrambi i lati, circa 3 minuti per lato. Scolale su carta e servile calde.',
      ko:'감자를 통째로 부드러워질 때까지 삶은 뒤 껍질을 벗겨 으깨고 살짝 식힌다. 곱게 다진 양파, 달걀, 밀가루, 파슬리를 섞고 소금으로 간해 모양을 낼 수 있는 반죽을 만든다. 젖은 손으로 작은 전을 빚어 기름에 중불로 양면이 진한 갈색으로 바삭해질 때까지 한 면당 약 3분씩 지진다. 종이에 기름을 빼고 따뜻하게 낸다.' } },

  { id:'budget_020', name:NAMES.orezLapte, servings:2, prep:5, cook:30, costRon:4, nut:{cal:320,prot:9,carb:58,fat:6,fib:1}, tags:['budget','vegetarian','family'],
    ing:[ {q:150,u:'g',n:I.rice}, {q:700,u:'ml',n:I.milk}, {q:3,u:'tbsp',n:I.sugar}, {q:1,u:'tsp',n:I.cinnamon}, {n:I.salt} ],
    steps:{
      ro:'Clătește orezul și pune-l într-o oală cu laptele, zahărul și un praf de sare. Adu încet la fiert, apoi fierbe la foc mic, amestecând des ca să nu se prindă, circa 25 de minute, până orezul e moale și laptele s-a îngroșat într-un desert cremos. Se întărește pe măsură ce se răcește, așa că ia-l de pe foc cât e încă moale. Servește-l cald sau rece, presărat cu scorțișoară.',
      en:'Rinse the rice and put it in a pot with the milk, the sugar and a pinch of salt. Bring gently to a simmer, then cook on low, stirring often so it doesn’t catch, for about 25 minutes until the rice is soft and the milk has thickened to a creamy pudding. It firms up as it cools, so take it off while still loose. Serve warm or cold, dusted with the cinnamon.',
      es:'Enjuaga el arroz y ponlo en una olla con la leche, el azúcar y una pizca de sal. Lleva despacio a ebullición y luego cuece a fuego bajo, removiendo a menudo para que no se pegue, unos 25 minutos, hasta que el arroz esté blando y la leche se haya espesado en un postre cremoso. Cuaja al enfriar, así que retíralo cuando aún esté suelto. Sírvelo caliente o frío, espolvoreado con canela.',
      fr:'Rincez le riz et mettez-le dans une casserole avec le lait, le sucre et une pincée de sel. Portez doucement à frémissement, puis laissez cuire à feu doux, en remuant souvent pour que ça n’attache pas, environ 25 minutes, jusqu’à ce que le riz soit tendre et le lait épaissi en un dessert crémeux. Il se raffermit en refroidissant, retirez-le donc encore souple. Servez chaud ou froid, saupoudré de cannelle.',
      de:'Den Reis abspülen und mit der Milch, dem Zucker und einer Prise Salz in einen Topf geben. Langsam zum Sieden bringen, dann bei schwacher Hitze etwa 25 Minuten kochen, oft umrühren, damit nichts ansetzt, bis der Reis weich und die Milch zu einem cremigen Dessert eingedickt ist. Es wird beim Abkühlen fester, daher noch cremig vom Herd nehmen. Warm oder kalt servieren, mit Zimt bestreut.',
      pt:'Enxágue o arroz e coloque-o num tacho com o leite, o açúcar e uma pitada de sal. Leve devagar a levantar fervura e depois cozinhe em lume brando, mexendo com frequência para não pegar, cerca de 25 minutos, até o arroz ficar macio e o leite engrossar num doce cremoso. Ganha consistência ao arrefecer, por isso retire ainda mole. Sirva quente ou frio, polvilhado com canela.',
      ru:'Промойте рис и положите в кастрюлю с молоком, сахаром и щепоткой соли. Доведите до слабого кипения, затем варите на слабом огне, часто помешивая, чтобы не пригорело, около 25 минут, пока рис не станет мягким, а молоко не загустеет в кремовый десерт. При остывании он густеет, поэтому снимайте с огня, пока он ещё жидковат. Подавайте тёплым или холодным, посыпав корицей.',
      ar:'اغسل الأرز وضعه في قدر مع الحليب والسكر ورشة ملح. ارفعه للغليان ببطء ثم اطهه على نار هادئة مع التحريك المتكرر كي لا يلتصق، نحو 25 دقيقة، حتى يلين الأرز ويثخن الحليب إلى حلوى كريمية. يتماسك عند التبريد، لذا ارفعه وهو ما زال سائلاً بعض الشيء. قدّمه ساخناً أو بارداً، منثوراً بالقرفة.',
      zh:'把米淘净，放入锅中加牛奶、糖和一撮盐。慢慢煮开，转小火，常搅动以免粘底，约25分钟，至米软、牛奶浓稠成奶油般的甜点。放凉会变稠，所以趁还稀软时离火。趁热或冷食，撒上肉桂粉。',
      ja:'米を洗い、鍋に牛乳、砂糖、塩ひとつまみとともに入れる。ゆっくり煮立て、弱火にして焦げ付かないようによく混ぜながら約25分、米が柔らかく牛乳がとろりとクリーミーなデザート状になるまで煮る。冷めると固くなるので、まだゆるいうちに火から下ろす。温かくても冷やしても、シナモンを振って供する。',
      hi:'चावल धोकर एक पतीले में दूध, चीनी और एक चुटकी नमक के साथ डालें। धीरे-धीरे उबाल पर लाएँ, फिर धीमी आँच पर बार-बार चलाते हुए ताकि चिपके नहीं, लगभग 25 मिनट पकाएँ जब तक चावल नरम और दूध गाढ़ा होकर मलाईदार मिठाई बन जाए। ठंडा होने पर गाढ़ा होता है, इसलिए थोड़ा पतला रहते ही आँच से उतारें। गरम या ठंडा, दालचीनी छिड़ककर परोसें।',
      tr:'Pirinci yıkayıp süt, şeker ve bir tutam tuzla bir tencereye alın. Yavaşça kaynama noktasına getirin, sonra kısık ateşte dibe tutmasın diye sık karıştırarak yaklaşık 25 dakika, pirinç yumuşayıp süt kremamsı bir tatlıya koyulaşana dek pişirin. Soğuyunca koyulaşır, bu yüzden hâlâ akışkanken ateşten alın. Sıcak ya da soğuk, üzerine tarçın serperek servis edin.',
      it:'Sciacqua il riso e mettilo in una pentola con il latte, lo zucchero e un pizzico di sale. Porta piano al sobbollore, poi cuoci a fuoco basso, mescolando spesso perché non attacchi, circa 25 minuti, finché il riso è morbido e il latte si è addensato in un dolce cremoso. Rassoda raffreddandosi, quindi togli dal fuoco quando è ancora morbido. Servi caldo o freddo, spolverato di cannella.',
      ko:'쌀을 헹궈 냄비에 우유, 설탕, 소금 한 꼬집과 함께 넣는다. 천천히 끓기 시작하면 약불로 줄여 눌어붙지 않게 자주 저으며 약 25분, 쌀이 부드러워지고 우유가 크리미한 디저트로 걸쭉해질 때까지 끓인다. 식으면 되직해지므로 아직 묽을 때 불에서 내린다. 따뜻하게 또는 차갑게, 계피를 뿌려 낸다.' } },

  { id:'budget_021', name:NAMES.mazare, servings:2, prep:15, cook:30, costRon:4, nut:{cal:360,prot:14,carb:44,fat:15,fib:12}, tags:['budget','vegan','one-pot'],
    ing:[ {q:500,u:'g',n:I.peas}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:2,u:'tbsp',n:I.dill}, {q:200,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Încălzește uleiul într-o oală și călește ceapa tocată și morcovul dat pe răzătoare la foc mediu circa 6 minute, până se înmoaie și se rumenesc. Adaugă roșiile pasate și lasă-le să scadă 2 minute, apoi pune mazărea, apa și un praf bun de sare. Fierbe blând, neacoperit, circa 20 de minute, până mazărea e fragedă și sosul s-a legat în jurul ei — merge și proaspătă, și congelată, iar cea congelată nu trebuie dezghețată. Adaugă cea mai mare parte din mărarul tocat spre final, căci el dă mâncării aroma verii și amprenta ei românească. Potrivește de sare și presară restul de mărar deasupra. Servește caldă, ca fel principal cu pâine, sau ca garnitură lângă orice friptură.',
      en:'Warm the oil in a pot and cook the chopped onion and grated carrot over medium heat for about 6 minutes, until soft and golden. Stir in the tomato passata and let it cook down for 2 minutes, then add the green peas, the water and a good pinch of salt. Simmer gently, uncovered, for about 20 minutes, until the peas are tender and the sauce has thickened around them — fresh or frozen peas both work, and frozen ones need no thawing. Stir most of the chopped dill in near the end, which gives the dish its summery, unmistakably Romanian aroma. Taste and adjust the salt, then scatter the rest of the dill on top. Serve warm as a main with bread, or as a side to anything roasted.',
      es:'Calienta el aceite en una olla y sofríe la cebolla picada y la zanahoria rallada a fuego medio unos 6 minutos, hasta que estén blandas y doradas. Añade el tomate triturado y déjalo reducir 2 minutos, luego incorpora los guisantes, el agua y una buena pizca de sal. Cuece a fuego suave, destapado, unos 20 minutos, hasta que los guisantes estén tiernos y la salsa haya espesado a su alrededor —sirven frescos o congelados, y los congelados no hace falta descongelarlos—. Agrega casi todo el eneldo picado hacia el final, que da al plato su aroma veraniego e inconfundiblemente rumano. Prueba y ajusta la sal, luego esparce el resto del eneldo por encima. Sirve caliente como plato principal con pan, o como guarnición de cualquier asado.',
      fr:'Chauffez l’huile dans une casserole et faites revenir l’oignon haché et la carotte râpée à feu moyen environ 6 minutes, jusqu’à ce qu’ils soient tendres et dorés. Ajoutez les tomates passées et laissez réduire 2 minutes, puis mettez les petits pois, l’eau et une bonne pincée de sel. Laissez mijoter à découvert environ 20 minutes, jusqu’à ce que les pois soient tendres et la sauce épaissie autour d’eux — frais ou surgelés conviennent, et les surgelés n’ont pas besoin d’être décongelés. Incorporez la majeure partie de l’aneth haché vers la fin, ce qui donne au plat son parfum d’été et sa signature roumaine. Rectifiez le sel, puis parsemez du reste d’aneth. Servez chaud en plat avec du pain, ou en accompagnement d’une viande rôtie.',
      de:'Das Öl in einem Topf erwärmen und die gehackte Zwiebel und die geriebene Karotte bei mittlerer Hitze etwa 6 Minuten anschwitzen, bis sie weich und goldgelb sind. Die passierten Tomaten einrühren und 2 Minuten einkochen lassen, dann die Erbsen, das Wasser und eine gute Prise Salz zugeben. Offen etwa 20 Minuten sanft köcheln, bis die Erbsen weich sind und die Sauce sie umhüllt — frische wie tiefgekühlte Erbsen eignen sich, tiefgekühlte müssen nicht aufgetaut werden. Den größten Teil des gehackten Dills gegen Ende einrühren, der dem Gericht sein sommerliches, unverkennbar rumänisches Aroma gibt. Mit Salz abschmecken und den restlichen Dill darüberstreuen. Warm als Hauptgericht mit Brot servieren oder als Beilage zu Gebratenem.',
      pt:'Aqueça o óleo numa panela e refogue a cebola picada e a cenoura ralada em lume médio cerca de 6 minutos, até ficarem macias e douradas. Junte o tomate passata e deixe reduzir 2 minutos, depois adicione as ervilhas, a água e uma boa pitada de sal. Cozinhe em lume brando, destapado, cerca de 20 minutos, até as ervilhas ficarem macias e o molho engrossar à volta delas — servem frescas ou congeladas, e as congeladas não precisam de descongelar. Junte quase todo o endro picado perto do fim, que dá ao prato o seu aroma de verão e a sua marca romena. Prove e acerte o sal, depois espalhe o resto do endro por cima. Sirva quente como prato principal com pão, ou como acompanhamento de qualquer assado.',
      ru:'Разогрейте масло в кастрюле и обжарьте нарезанный лук и натёртую морковь на среднем огне около 6 минут, до мягкости и золотистости. Вмешайте протёртые томаты и дайте им увариться 2 минуты, затем добавьте зелёный горошек, воду и хорошую щепотку соли. Тушите без крышки на слабом огне около 20 минут, пока горошек не станет мягким, а соус не загустеет вокруг него — подойдёт и свежий, и замороженный, размораживать замороженный не нужно. Большую часть рубленого укропа вмешайте ближе к концу — он придаёт блюду летний, безошибочно румынский аромат. Посолите по вкусу и посыпьте оставшимся укропом. Подавайте тёплым как основное блюдо с хлебом или как гарнир к любому жаркому.',
      ar:'سخّن الزيت في قدر وشوّح البصل المفروم والجزر المبشور على نار متوسطة نحو 6 دقائق حتى يلين ويكتسب لوناً ذهبياً. أضف الطماطم المهروسة واتركها تتكاثف دقيقتين، ثم أضف البازلاء والماء ورشة ملح جيدة. اطهها على نار هادئة دون تغطية نحو 20 دقيقة حتى تلين البازلاء ويتماسك حولها الصلصة — تصلح الطازجة والمجمّدة، والمجمّدة لا تحتاج إلى إذابة. أضف معظم الشبت المفروم قرب النهاية، فهو يمنح الطبق عبقه الصيفي وبصمته الرومانية. اضبط الملح ثم انثر بقية الشبت فوقه. قدّمه دافئاً كطبق رئيسي مع الخبز، أو كطبق جانبي بجانب أي مشوي.',
      zh:'锅中热油，中火炒切碎的洋葱和擦丝的胡萝卜约6分钟，至变软金黄。加入番茄泥收2分钟，再放入豌豆、水和一大撮盐。不加盖小火煮约20分钟，至豌豆软嫩、酱汁裹在其上——鲜豌豆或冷冻豌豆皆可，冷冻的无需解冻。临出锅前拌入大部分切碎的莳萝，它赋予这道菜夏日气息和地道的罗马尼亚风味。尝味调盐，再把剩下的莳萝撒在上面。趁热作为主菜配面包食用，或作为任何烤肉的配菜。',
      ja:'鍋に油を温め、みじん切りの玉ねぎとすりおろしたにんじんを中火で約6分、柔らかく色づくまで炒める。トマトピューレを加えて2分煮詰め、グリーンピース、水、塩ひとつまみを加える。ふたをせず弱火で約20分、豆が柔らかくソースが豆にからむまで煮る——生でも冷凍でもよく、冷凍は解凍不要。刻んだディルの大半を仕上げ間際に加えると、夏らしくまぎれもなくルーマニア的な香りが立つ。塩で味を調え、残りのディルを散らす。パンを添えて主菜として、または焼き物の付け合わせとして温かいうちに供する。',
      hi:'बर्तन में तेल गरम करें और कटा प्याज़ व कद्दूकस की गाजर मध्यम आँच पर लगभग 6 मिनट नरम-सुनहरा होने तक भूनें। टमाटर प्यूरी डालकर 2 मिनट गाढ़ा करें, फिर हरी मटर, पानी और अच्छी चुटकी नमक डालें। बिना ढके धीमी आँच पर लगभग 20 मिनट पकाएँ जब तक मटर नरम और ग्रेवी उसके चारों ओर गाढ़ी हो जाए — ताज़ी या जमी हुई दोनों चलेंगी, और जमी हुई को पिघलाने की ज़रूरत नहीं। अधिकांश कटा डिल अंत के पास मिलाएँ, जो पकवान को गर्मियों की और स्पष्ट रूप से रोमानियाई महक देता है। स्वादानुसार नमक ठीक करें, फिर बचा डिल ऊपर छिड़कें। गरम, ब्रेड के साथ मुख्य व्यंजन के रूप में या किसी भुने पकवान के साथ परोसें।',
      tr:'Tencerede yağı ısıtın ve doğranmış soğan ile rendelenmiş havucu orta ateşte yaklaşık 6 dakika, yumuşayıp kızarana dek kavurun. Domates püresini ekleyip 2 dakika suyunu çektirin, sonra bezelye, su ve iyi bir tutam tuz ekleyin. Kapaksız, kısık ateşte yaklaşık 20 dakika, bezelye yumuşayıp sos etrafını sarana dek pişirin — taze de donmuş da olur, donmuşun çözülmesine gerek yok. Kıyılmış dereotunun çoğunu sona doğru ekleyin; yemeğe yazdan gelen ve şaşmaz biçimde Rumen olan kokusunu o verir. Tuzu ayarlayıp kalan dereotunu üzerine serpin. Ekmekle ana yemek olarak ya da her türlü kızartmanın yanında sıcak servis edin.',
      it:'Scalda l’olio in una pentola e fai rosolare la cipolla tritata e la carota grattugiata a fuoco medio per circa 6 minuti, finché sono morbide e dorate. Unisci la passata e falla ridurre 2 minuti, poi aggiungi i piselli, l’acqua e una buona presa di sale. Fai sobbollire scoperto a fuoco basso per circa 20 minuti, finché i piselli sono teneri e il sugo si è addensato attorno a loro — vanno bene freschi o surgelati, e i surgelati non vanno scongelati. Unisci gran parte dell’aneto tritato verso la fine, che dà al piatto il suo profumo estivo e la sua inconfondibile impronta romena. Regola il sale, poi cospargi con l’aneto rimasto. Servi caldo come piatto con pane, o come contorno a qualsiasi arrosto.',
      ko:'냄비에 기름을 데우고 다진 양파와 채 썬 당근을 중불에서 약 6분간 부드럽고 노릇해질 때까지 볶는다. 토마토 퓌레를 넣어 2분간 졸인 뒤 완두콩, 물, 소금 넉넉히 한 꼬집을 넣는다. 뚜껑을 열고 약불에서 약 20분간 완두콩이 부드러워지고 소스가 콩을 감쌀 때까지 끓인다 — 생완두콩과 냉동 완두콩 모두 괜찮고, 냉동은 해동할 필요가 없다. 다진 딜의 대부분을 마무리 즈음에 넣으면 여름 같고 틀림없이 루마니아다운 향이 난다. 간을 맞추고 남은 딜을 위에 뿌린다. 빵을 곁들여 주요리로, 또는 구이 요리의 곁들이로 따뜻하게 낸다.' } },

  { id:'budget_022', name:NAMES.spanac, servings:2, prep:10, cook:15, costRon:3, nut:{cal:180,prot:7,carb:16,fat:11,fib:5}, tags:['budget','vegan','healthy'],
    ing:[ {q:500,u:'g',n:I.spinach}, {q:4,u:'clove',n:I.garlic}, {q:2,u:'tbsp',n:I.oil}, {q:1,u:'tbsp',n:I.flour}, {q:200,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Spală bine spanacul și, dacă frunzele sunt mari, taie-le grosier; merge și spanac congelat, care nu trebuie dezghețat. Încălzește uleiul într-o tigaie largă și călește usturoiul feliat subțire la foc mic un minut, doar cât să înmiresmeze — nu-l lăsa să se rumenească, fiindcă amărăște. Adaugă spanacul și un praf de sare și lasă-l să se înmoaie, amestecând, circa 5 minute. Presară făina și amestec-o, apoi toarnă apa treptat, mereu amestecând, ca să se lege un sos ușor și lucios care îmbracă frunzele. Mai fierbe 3 minute, potrivește de sare și servește cald — tradițional, cu un ou ochi sau mămăligă alături.',
      en:'Rinse the spinach well and, if the leaves are large, chop them roughly; frozen spinach works too and needs no thawing. Warm the oil in a wide pan and cook the thinly sliced garlic over low heat for about a minute, just until fragrant — don’t let it brown or it turns bitter. Add the spinach with a pinch of salt and let it wilt down, stirring, for about 5 minutes. Sprinkle over the flour and stir it in, then pour in the water a little at a time, stirring, so it thickens into a light, glossy sauce that coats the leaves. Simmer for 3 more minutes, adjust the salt, and serve warm — traditionally with a fried egg or polenta alongside.',
      es:'Lava bien las espinacas y, si las hojas son grandes, pícalas groseramente; también sirven congeladas y no hace falta descongelarlas. Calienta el aceite en una sartén amplia y cocina el ajo en láminas finas a fuego bajo un minuto, solo hasta que perfume —no dejes que se dore o amarga—. Añade las espinacas con una pizca de sal y deja que se rehoguen, removiendo, unos 5 minutos. Espolvorea la harina e intégrala, luego vierte el agua poco a poco, sin dejar de remover, para que ligue una salsa ligera y brillante que envuelva las hojas. Cuece 3 minutos más, ajusta la sal y sirve caliente —tradicionalmente con un huevo frito o polenta al lado—.',
      fr:'Rincez bien les épinards et, si les feuilles sont grandes, hachez-les grossièrement ; surgelés, ils conviennent aussi et n’ont pas besoin d’être décongelés. Chauffez l’huile dans une grande poêle et faites cuire l’ail émincé à feu doux une minute, juste jusqu’à ce qu’il embaume — sans le laisser dorer, sinon il devient amer. Ajoutez les épinards avec une pincée de sel et laissez-les tomber, en remuant, environ 5 minutes. Saupoudrez de farine et mélangez, puis versez l’eau peu à peu, sans cesser de remuer, pour lier une sauce légère et brillante qui nappe les feuilles. Laissez mijoter 3 minutes de plus, rectifiez le sel et servez chaud — traditionnellement avec un œuf au plat ou de la polenta.',
      de:'Den Spinat gut waschen und, falls die Blätter groß sind, grob hacken; auch tiefgekühlter Spinat eignet sich und muss nicht aufgetaut werden. Das Öl in einer weiten Pfanne erwärmen und den dünn geschnittenen Knoblauch bei schwacher Hitze etwa eine Minute anschwitzen, nur bis er duftet — nicht bräunen lassen, sonst wird er bitter. Den Spinat mit einer Prise Salz zugeben und unter Rühren etwa 5 Minuten zusammenfallen lassen. Das Mehl darüberstäuben und einrühren, dann nach und nach das Wasser angießen, dabei rühren, bis eine leichte, glänzende Sauce entsteht, die die Blätter umhüllt. Weitere 3 Minuten köcheln, mit Salz abschmecken und warm servieren — traditionell mit einem Spiegelei oder Polenta dazu.',
      pt:'Lave bem os espinafres e, se as folhas forem grandes, pique-as grosseiramente; congelados também servem e não precisam de descongelar. Aqueça o óleo numa frigideira larga e cozinhe o alho em lâminas finas em lume brando cerca de um minuto, só até perfumar — não deixe alourar, senão amarga. Junte os espinafres com uma pitada de sal e deixe murchar, mexendo, cerca de 5 minutos. Polvilhe a farinha e envolva, depois deite a água aos poucos, sempre a mexer, para ligar um molho leve e brilhante que envolva as folhas. Cozinhe mais 3 minutos, acerte o sal e sirva quente — tradicionalmente com um ovo estrelado ou polenta ao lado.',
      ru:'Хорошо промойте шпинат и, если листья крупные, порубите их; замороженный шпинат тоже подойдёт и размораживать его не нужно. Разогрейте масло в широкой сковороде и обжарьте тонко нарезанный чеснок на слабом огне около минуты, только до аромата — не давайте ему подрумяниться, иначе он станет горьким. Добавьте шпинат со щепоткой соли и дайте ему осесть, помешивая, около 5 минут. Присыпьте мукой и вмешайте её, затем вливайте воду понемногу, помешивая, чтобы получился лёгкий блестящий соус, обволакивающий листья. Потушите ещё 3 минуты, посолите по вкусу и подавайте тёплым — традиционно с яичницей-глазуньей или полентой.',
      ar:'اغسل السبانخ جيداً، وإن كانت الأوراق كبيرة فقطّعها تقطيعاً خشناً؛ والسبانخ المجمّدة تصلح أيضاً ولا تحتاج إلى إذابة. سخّن الزيت في مقلاة واسعة واطهُ الثوم المقطّع رفيعاً على نار هادئة نحو دقيقة، فقط حتى يفوح — دون أن يحمرّ وإلا صار مرّاً. أضف السبانخ مع رشة ملح واتركها تذبل مع التقليب نحو 5 دقائق. انثر الدقيق وقلّبه، ثم أضف الماء تدريجياً مع التحريك حتى تتماسك صلصة خفيفة لامعة تغلّف الأوراق. اطهها 3 دقائق أخرى، اضبط الملح وقدّمها دافئة — تقليدياً مع بيضة مقلية أو عصيدة الذرة إلى جانبها.',
      zh:'把菠菜洗净，若叶片较大就粗略切碎；冷冻菠菜也可以，无需解冻。宽口锅中热油，小火将切薄的蒜片炒约1分钟，只需出香——别炒到发褐，否则会苦。放入菠菜和一撮盐，边翻边让它塌软，约5分钟。撒入面粉拌匀，再分次倒入水、不停搅拌，收成一层裹住菜叶的轻盈亮泽酱汁。再煮3分钟，调盐，趁热食用——传统上配一个煎蛋或玉米糊。',
      ja:'ほうれん草をよく洗い、葉が大きければざく切りにする。冷凍ほうれん草でもよく、解凍は不要。広めのフライパンに油を温め、薄切りのにんにくを弱火で約1分、香りが立つまで炒める——焦がすと苦くなるので色づけない。ほうれん草と塩ひとつまみを加え、混ぜながら約5分しんなりさせる。小麦粉を振り入れて混ぜ、水を少しずつ加えながら混ぜ、葉にからむ軽くつやのあるソースにとろみをつける。さらに3分煮て塩を調え、温かいうちに供する——伝統的には目玉焼きやポレンタを添えて。',
      hi:'पालक को अच्छी तरह धोएँ और यदि पत्ते बड़े हों तो मोटा-मोटा काट लें; जमा हुआ पालक भी चलेगा और उसे पिघलाने की ज़रूरत नहीं। चौड़े पैन में तेल गरम करें और पतले कटे लहसुन को धीमी आँच पर लगभग एक मिनट, बस खुशबू आने तक भूनें — भूरा न होने दें वरना कड़वा हो जाता है। पालक और एक चुटकी नमक डालें और चलाते हुए लगभग 5 मिनट मुरझाने दें। ऊपर से आटा छिड़ककर मिलाएँ, फिर थोड़ा-थोड़ा पानी डालते और चलाते हुए एक हल्की, चमकदार ग्रेवी बनाएँ जो पत्तों पर लिपट जाए। 3 मिनट और पकाएँ, नमक ठीक करें और गरम परोसें — पारंपरिक रूप से एक तले अंडे या पोलेंटा के साथ।',
      tr:'Ispanağı iyice yıkayın, yapraklar iriyse kabaca doğrayın; donmuş ıspanak da olur ve çözülmesine gerek yoktur. Geniş bir tavada yağı ısıtın ve ince dilimlenmiş sarımsağı kısık ateşte yaklaşık bir dakika, sadece kokusu çıkana dek soteleyin — kızarmasına izin vermeyin, yoksa acılaşır. Ispanağı bir tutam tuzla ekleyin ve karıştırarak yaklaşık 5 dakika suyunu salıp çökmesini sağlayın. Üzerine unu serpip karıştırın, sonra suyu azar azar, karıştırarak ekleyin ki yaprakları saran hafif, parlak bir sos bağlasın. 3 dakika daha pişirin, tuzu ayarlayın ve sıcak servis edin — geleneksel olarak yanında sahanda yumurta ya da mısır lapası ile.',
      it:'Lava bene gli spinaci e, se le foglie sono grandi, tritale grossolanamente; vanno bene anche surgelati e non serve scongelarli. Scalda l’olio in una padella ampia e cuoci l’aglio a fettine sottili a fuoco basso per circa un minuto, solo finché profuma — non farlo dorare, o diventa amaro. Aggiungi gli spinaci con un pizzico di sale e falli appassire, mescolando, per circa 5 minuti. Spolvera la farina e mescolala, poi versa l’acqua poco per volta, mescolando, così da legare una salsa leggera e lucida che avvolge le foglie. Fai sobbollire altri 3 minuti, regola il sale e servi caldo — tradizionalmente con un uovo all’occhio di bue o polenta.',
      ko:'시금치를 잘 씻고 잎이 크면 큼직하게 썬다. 냉동 시금치도 좋고 해동할 필요가 없다. 넓은 팬에 기름을 데우고 얇게 썬 마늘을 약불에서 약 1분, 향이 날 때까지만 볶는다 — 갈색이 되면 쓴맛이 나니 태우지 않는다. 시금치와 소금 한 꼬집을 넣고 저으며 약 5분간 숨을 죽인다. 밀가루를 뿌려 섞은 뒤 물을 조금씩 부으며 저어 잎을 감싸는 가볍고 윤기 있는 소스로 걸쭉하게 만든다. 3분 더 끓이고 간을 맞춰 따뜻하게 낸다 — 전통적으로 달걀프라이나 폴렌타를 곁들인다.' } },

  { id:'budget_023', name:NAMES.dovlecei, servings:2, prep:10, cook:20, costRon:3, nut:{cal:210,prot:4,carb:15,fat:16,fib:5}, tags:['budget','vegan','healthy'],
    ing:[ {q:600,u:'g',n:I.zucchini}, {q:1,n:I.onion}, {q:3,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:2,u:'tbsp',n:I.dill}, {n:I.salt} ],
    steps:{
      ro:'Taie dovleceii în felii semilună de circa un centimetru — cei tineri nu trebuie curățați de coajă. Încălzește uleiul într-o tigaie largă și înmoaie ceapa tocată la foc mediu 4 minute, apoi adaugă usturoiul feliat și lasă-l 30 de secunde, cât să înmiresmeze. Pune dovleceii și un praf de sare și gătește, amestecând din când în când, circa 8 minute, până prind culoare pe margini. Toarnă roșiile pasate, dă focul mai mic și fierbe 8–10 minute, până dovleceii sunt fragezi, dar încă își țin forma. Adaugă cea mai mare parte din mărarul tocat luat de pe foc, ca să rămână proaspăt și verde, și potrivește de sare. Servește cald sau la temperatura camerei, presărat cu restul de mărar.',
      en:'Cut the zucchini into half-moons about a centimetre thick — young ones need no peeling. Warm the oil in a wide pan and soften the chopped onion over medium heat for 4 minutes, then add the sliced garlic and cook for 30 seconds until fragrant. Add the zucchini with a pinch of salt and cook, stirring now and then, for about 8 minutes, until they start to colour at the edges. Pour in the tomato passata, lower the heat and simmer for 8 to 10 minutes, until the zucchini is tender but still holds its shape. Stir most of the chopped dill in off the heat, so it stays fresh and green, and adjust the salt. Serve warm or at room temperature, scattered with the rest of the dill.',
      es:'Corta los calabacines en medias lunas de aproximadamente un centímetro —los tiernos no necesitan pelarse—. Calienta el aceite en una sartén amplia y ablanda la cebolla picada a fuego medio 4 minutos, luego añade el ajo en láminas y cocina 30 segundos hasta que perfume. Añade el calabacín con una pizca de sal y cocina, removiendo de vez en cuando, unos 8 minutos, hasta que empiece a dorarse por los bordes. Vierte el tomate triturado, baja el fuego y cuece 8 a 10 minutos, hasta que el calabacín esté tierno pero aún mantenga la forma. Agrega casi todo el eneldo picado fuera del fuego, para que quede fresco y verde, y ajusta la sal. Sirve caliente o a temperatura ambiente, espolvoreado con el resto del eneldo.',
      fr:'Coupez les courgettes en demi-lunes d’environ un centimètre — les jeunes n’ont pas besoin d’être pelées. Chauffez l’huile dans une grande poêle et faites fondre l’oignon haché à feu moyen 4 minutes, puis ajoutez l’ail émincé et faites-le revenir 30 secondes jusqu’à ce qu’il embaume. Ajoutez les courgettes avec une pincée de sel et faites cuire, en remuant de temps en temps, environ 8 minutes, jusqu’à ce qu’elles colorent sur les bords. Versez les tomates passées, baissez le feu et laissez mijoter 8 à 10 minutes, jusqu’à ce que les courgettes soient tendres mais gardent leur forme. Incorporez la majeure partie de l’aneth haché hors du feu, pour qu’il reste frais et vert, et rectifiez le sel. Servez chaud ou à température ambiante, parsemé du reste d’aneth.',
      de:'Die Zucchini in etwa ein Zentimeter dicke Halbmonde schneiden — junge müssen nicht geschält werden. Das Öl in einer weiten Pfanne erwärmen und die gehackte Zwiebel bei mittlerer Hitze 4 Minuten weich dünsten, dann den geschnittenen Knoblauch zugeben und 30 Sekunden anbraten, bis er duftet. Die Zucchini mit einer Prise Salz zugeben und unter gelegentlichem Rühren etwa 8 Minuten braten, bis sie an den Rändern Farbe nehmen. Die passierten Tomaten angießen, die Hitze reduzieren und 8 bis 10 Minuten köcheln, bis die Zucchini weich sind, aber noch Form haben. Den größten Teil des gehackten Dills vom Herd genommen einrühren, damit er frisch und grün bleibt, und mit Salz abschmecken. Warm oder bei Zimmertemperatur servieren, mit dem restlichen Dill bestreut.',
      pt:'Corte as courgettes em meias-luas de cerca de um centímetro — as tenras não precisam de ser descascadas. Aqueça o óleo numa frigideira larga e amoleça a cebola picada em lume médio 4 minutos, depois junte o alho laminado e cozinhe 30 segundos até perfumar. Junte as courgettes com uma pitada de sal e cozinhe, mexendo de vez em quando, cerca de 8 minutos, até começarem a alourar nas pontas. Deite o tomate passata, baixe o lume e cozinhe 8 a 10 minutos, até as courgettes ficarem macias mas ainda com forma. Junte quase todo o endro picado fora do lume, para ficar fresco e verde, e acerte o sal. Sirva quente ou à temperatura ambiente, polvilhado com o resto do endro.',
      ru:'Нарежьте кабачки полукружьями толщиной около сантиметра — молодые чистить не нужно. Разогрейте масло в широкой сковороде и потушите нарезанный лук на среднем огне 4 минуты, затем добавьте нарезанный чеснок и готовьте 30 секунд до аромата. Добавьте кабачки со щепоткой соли и жарьте, изредка помешивая, около 8 минут, пока они не начнут румяниться по краям. Влейте протёртые томаты, убавьте огонь и тушите 8–10 минут, пока кабачки не станут мягкими, но сохранят форму. Большую часть рубленого укропа вмешайте, сняв с огня, чтобы он остался свежим и зелёным, и посолите по вкусу. Подавайте тёплым или комнатной температуры, посыпав оставшимся укропом.',
      ar:'قطّع الكوسة أنصاف دوائر بسمك سنتيمتر تقريباً — الصغيرة منها لا تحتاج إلى تقشير. سخّن الزيت في مقلاة واسعة وليّن البصل المفروم على نار متوسطة 4 دقائق، ثم أضف الثوم المقطّع واطهه 30 ثانية حتى يفوح. أضف الكوسة مع رشة ملح واطهها مع التقليب بين الحين والآخر نحو 8 دقائق حتى تبدأ حوافها بالاحمرار. أضف الطماطم المهروسة، اخفض النار واطهها 8–10 دقائق حتى تلين الكوسة مع بقائها متماسكة الشكل. أضف معظم الشبت المفروم بعد رفع القدر عن النار كي يبقى طازجاً أخضر، واضبط الملح. قدّمها دافئة أو بحرارة الغرفة، منثوراً عليها بقية الشبت.',
      zh:'把西葫芦切成约一厘米厚的半月片——嫩的无需削皮。宽口锅中热油，中火将切碎的洋葱煸软4分钟，再加蒜片炒30秒出香。放入西葫芦和一撮盐，不时翻动煎约8分钟，至边缘上色。倒入番茄泥，转小火煮8至10分钟，至西葫芦软嫩但仍保持形状。离火后拌入大部分切碎的莳萝，使其保持鲜绿，再调盐。趁热或常温食用，撒上剩下的莳萝。',
      ja:'ズッキーニを厚さ約1センチの半月切りにする——若いものは皮をむかなくてよい。広めのフライパンに油を温め、みじん切りの玉ねぎを中火で4分やわらかくし、薄切りのにんにくを加えて30秒、香りが立つまで炒める。ズッキーニと塩ひとつまみを加え、時々混ぜながら約8分、縁が色づき始めるまで炒める。トマトピューレを注ぎ、火を弱めて8〜10分、ズッキーニが柔らかくなりつつ形を保つまで煮る。刻んだディルの大半は火を止めてから加え、フレッシュな緑を保ち、塩で調える。温かくても常温でも、残りのディルを散らして供する。',
      hi:'तोरी को लगभग एक सेंटीमीटर मोटे अर्धचंद्राकार टुकड़ों में काटें — कोमल तोरी छीलने की ज़रूरत नहीं। चौड़े पैन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 4 मिनट नरम करें, फिर कटा लहसुन डालकर 30 सेकंड खुशबू आने तक भूनें। तोरी और एक चुटकी नमक डालें और बीच-बीच में चलाते हुए लगभग 8 मिनट पकाएँ जब तक किनारों पर रंग आने लगे। टमाटर प्यूरी डालें, आँच कम करें और 8–10 मिनट पकाएँ जब तक तोरी नरम हो पर आकार बनाए रखे। अधिकांश कटा डिल आँच से उतारकर मिलाएँ ताकि वह ताज़ा-हरा रहे, और नमक ठीक करें। गरम या कमरे के तापमान पर, बचे डिल छिड़ककर परोसें।',
      tr:'Kabakları yaklaşık bir santim kalınlığında yarım ay dilimleyin — taze olanların soyulmasına gerek yok. Geniş bir tavada yağı ısıtın ve doğranmış soğanı orta ateşte 4 dakika yumuşatın, sonra dilimlenmiş sarımsağı ekleyip 30 saniye kokusu çıkana dek soteleyin. Kabakları bir tutam tuzla ekleyin ve ara sıra karıştırarak yaklaşık 8 dakika, kenarları renk almaya başlayana dek pişirin. Domates püresini dökün, ateşi kısın ve 8–10 dakika, kabaklar yumuşayıp şeklini korur hâlde kalana dek pişirin. Kıyılmış dereotunun çoğunu ocaktan aldıktan sonra ekleyin ki taze ve yeşil kalsın, tuzu ayarlayın. Sıcak ya da oda sıcaklığında, kalan dereotunu serperek servis edin.',
      it:'Taglia le zucchine a mezzelune spesse circa un centimetro — quelle giovani non vanno sbucciate. Scalda l’olio in una padella ampia e fai ammorbidire la cipolla tritata a fuoco medio per 4 minuti, poi aggiungi l’aglio a fette e cuoci 30 secondi finché profuma. Aggiungi le zucchine con un pizzico di sale e cuoci, mescolando ogni tanto, per circa 8 minuti, finché iniziano a colorirsi ai bordi. Versa la passata, abbassa la fiamma e fai sobbollire 8-10 minuti, finché le zucchine sono tenere ma mantengono la forma. Unisci gran parte dell’aneto tritato fuori dal fuoco, così resta fresco e verde, e regola il sale. Servi caldo o a temperatura ambiente, cosparso con l’aneto rimasto.',
      ko:'애호박을 약 1센티미터 두께의 반달 모양으로 썬다 — 어린 것은 껍질을 벗기지 않아도 된다. 넓은 팬에 기름을 데우고 다진 양파를 중불에서 4분간 부드럽게 한 뒤 저민 마늘을 넣어 30초간 향이 날 때까지 볶는다. 애호박과 소금 한 꼬집을 넣고 이따금 저으며 약 8분, 가장자리가 색이 나기 시작할 때까지 볶는다. 토마토 퓌레를 붓고 불을 줄여 8~10분, 애호박이 부드러워지되 모양은 유지될 때까지 끓인다. 다진 딜의 대부분은 불을 끄고 넣어 신선한 초록빛을 살리고 간을 맞춘다. 따뜻하게 또는 실온으로, 남은 딜을 뿌려 낸다.' } },

  { id:'budget_024', name:NAMES.ciuperci, servings:2, prep:20, cook:15, costRon:5, nut:{cal:330,prot:12,carb:28,fat:19,fib:4}, tags:['budget','vegetarian','family'],
    ing:[ {q:400,u:'g',n:I.mushrooms}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {q:1,n:I.eggs}, {q:60,u:'g',n:I.breadcrumbs}, {q:2,u:'tbsp',n:I.parsley}, {q:4,u:'tbsp',n:I.oil}, {n:I.salt} ],
    steps:{
      ro:'Toacă mărunt ciupercile și ceapa, apoi gătește-le cu usturoiul pisat într-o tigaie uscată sau abia unsă cu ulei, la foc mediu-mare, circa 8 minute, până se evaporă complet apa lăsată de ciuperci — pasul acesta ține chiftelele legate. Lasă compoziția să se răcorească puțin, apoi amestecă oul, pesmetul, pătrunjelul tocat și un praf bun de sare într-o pastă moale, ușor de modelat; dacă e prea umedă, mai pune o lingură de pesmet. Formează chiftele mici cu mâinile ude. Încălzește uleiul într-o tigaie și prăjește-le la foc mediu circa 3 minute pe fiecare parte, până sunt aurii și bine legate. Scurge-le pe hârtie de bucătărie și presară puțină sare. Servește-le calde sau reci, cu mujdei, iaurt sau o salată verde.',
      en:'Chop the mushrooms and onion finely, then cook them with the minced garlic in a dry or lightly oiled pan over medium-high heat for about 8 minutes, until the water the mushrooms release has fully evaporated — this step is what keeps the patties from falling apart. Let the mixture cool a little, then mix in the egg, the breadcrumbs, the chopped parsley and a good pinch of salt to a soft, shapeable paste; if it feels wet, add another spoon of breadcrumbs. Shape into small patties with wet hands. Warm the oil in a pan and fry them over medium heat for about 3 minutes per side, until deep golden and set. Drain on paper towel and season with a little more salt. Serve hot or cold, with garlic sauce, yogurt or a green salad.',
      es:'Pica finos los champiñones y la cebolla, luego cocínalos con el ajo picado en una sartén seca o apenas engrasada a fuego medio-alto unos 8 minutos, hasta que el agua que sueltan los champiñones se evapore por completo — este paso es lo que evita que las tortitas se deshagan. Deja enfriar un poco la mezcla, luego incorpora el huevo, el pan rallado, el perejil picado y una buena pizca de sal hasta una pasta blanda y moldeable; si queda húmeda, añade otra cucharada de pan rallado. Forma tortitas pequeñas con las manos húmedas. Calienta el aceite en una sartén y fríelas a fuego medio unos 3 minutos por lado, hasta que estén doradas y firmes. Escúrrelas sobre papel de cocina y sazona con un poco más de sal. Sírvelas calientes o frías, con salsa de ajo, yogur o una ensalada verde.',
      fr:'Hachez finement les champignons et l’oignon, puis faites-les cuire avec l’ail haché dans une poêle sèche ou à peine huilée à feu moyen-vif environ 8 minutes, jusqu’à ce que l’eau rendue par les champignons soit entièrement évaporée — c’est cette étape qui empêche les galettes de se défaire. Laissez tiédir le mélange, puis incorporez l’œuf, la chapelure, le persil haché et une bonne pincée de sel pour obtenir une pâte souple et façonnable ; si elle est humide, ajoutez une cuillerée de chapelure. Façonnez de petites galettes avec les mains mouillées. Chauffez l’huile dans une poêle et faites-les frire à feu moyen environ 3 minutes par face, jusqu’à ce qu’elles soient bien dorées et fermes. Égouttez-les sur du papier absorbant et salez un peu. Servez chaud ou froid, avec une sauce à l’ail, du yaourt ou une salade verte.',
      de:'Champignons und Zwiebel fein hacken, dann mit dem gehackten Knoblauch in einer trockenen oder leicht geölten Pfanne bei mittelhoher Hitze etwa 8 Minuten braten, bis das von den Pilzen abgegebene Wasser vollständig verdampft ist — dieser Schritt hält die Bratlinge zusammen. Die Masse etwas abkühlen lassen, dann Ei, Semmelbrösel, gehackte Petersilie und eine gute Prise Salz zu einer weichen, formbaren Masse verkneten; ist sie zu feucht, einen weiteren Löffel Semmelbrösel zugeben. Mit nassen Händen kleine Bratlinge formen. Das Öl in einer Pfanne erhitzen und sie bei mittlerer Hitze etwa 3 Minuten pro Seite braten, bis sie tiefgolden und fest sind. Auf Küchenpapier abtropfen lassen und mit etwas Salz würzen. Warm oder kalt servieren, mit Knoblauchsauce, Joghurt oder einem grünen Salat.',
      pt:'Pique finamente os cogumelos e a cebola, depois cozinhe-os com o alho picado numa frigideira seca ou levemente untada em lume médio-alto cerca de 8 minutos, até a água que os cogumelos libertam evaporar por completo — é este passo que impede os bolinhos de se desfazerem. Deixe a mistura arrefecer um pouco, depois envolva o ovo, o pão ralado, a salsa picada e uma boa pitada de sal até obter uma pasta macia e moldável; se ficar húmida, junte mais uma colher de pão ralado. Molde bolinhos pequenos com as mãos húmidas. Aqueça o óleo numa frigideira e frite-os em lume médio cerca de 3 minutos de cada lado, até ficarem bem dourados e firmes. Escorra em papel de cozinha e tempere com um pouco mais de sal. Sirva quentes ou frios, com molho de alho, iogurte ou uma salada verde.',
      ru:'Мелко нарежьте грибы и лук, затем обжарьте их с измельчённым чесноком на сухой или слегка смазанной маслом сковороде на среднесильном огне около 8 минут, пока вся выделившаяся из грибов влага полностью не испарится — именно этот шаг не даёт котлетам разваливаться. Дайте массе немного остыть, затем вмешайте яйцо, панировочные сухари, рубленую петрушку и хорошую щепотку соли до мягкой, пластичной массы; если она влажная, добавьте ещё ложку сухарей. Влажными руками сформуйте небольшие котлеты. Разогрейте масло в сковороде и обжарьте их на среднем огне примерно по 3 минуты с каждой стороны, до насыщенного золотистого цвета и плотности. Обсушите на бумажном полотенце и присолите. Подавайте горячими или холодными, с чесночным соусом, йогуртом или зелёным салатом.',
      ar:'افرم الفطر والبصل ناعماً، ثم اطهها مع الثوم المهروس في مقلاة جافة أو مدهونة قليلاً بالزيت على نار متوسطة-عالية نحو 8 دقائق حتى يتبخّر الماء الذي يطلقه الفطر تماماً — هذه الخطوة هي ما يمنع الأقراص من التفكّك. اترك الخليط ليبرد قليلاً، ثم اخلط البيضة والبقسماط والبقدونس المفروم ورشة ملح جيدة حتى تحصل على عجينة طرية قابلة للتشكيل؛ إن كانت رطبة أضف ملعقة بقسماط أخرى. شكّل أقراصاً صغيرة بيدين مبلّلتين. سخّن الزيت في مقلاة واقلها على نار متوسطة نحو 3 دقائق لكل وجه حتى تصير ذهبية غامقة ومتماسكة. صفّها على ورق مطبخ ورشّها بقليل من الملح. قدّمها ساخنة أو باردة، مع صلصة الثوم أو اللبن أو سلطة خضراء.',
      zh:'把蘑菇和洋葱切碎，与蒜末一起放入干锅或抹薄油的锅中，中大火炒约8分钟，直到蘑菇渗出的水分完全蒸发——这一步能让肉饼不散。让混合物稍微放凉，再拌入鸡蛋、面包糠、切碎的欧芹和一大撮盐，揉成柔软、可塑形的糊；若偏湿，再加一勺面包糠。用湿手团成小饼。锅中热油，中火每面煎约3分钟，至深金黄且定形。用厨房纸吸油，再撒少许盐。趁热或放凉食用，配蒜酱、酸奶或一份绿沙拉。',
      ja:'マッシュルームと玉ねぎをみじん切りにし、刻んだにんにくとともに油をひかないか薄くひいたフライパンで中火よりやや強めに約8分、きのこから出た水分が完全に飛ぶまで炒める——この工程がおやきを崩れにくくする。粗熱を取ってから卵、パン粉、刻んだパセリ、塩ひとつまみを混ぜ、やわらかく成形できる生地にする。水っぽければパン粉をもう一さじ足す。濡れた手で小さく成形する。フライパンに油を温め、中火で片面約3分ずつ、濃いきつね色で固まるまで焼く。ペーパーで油を切り、塩を少し振る。温かくても冷たくても、ガーリックソースやヨーグルト、グリーンサラダを添えて供する。',
      hi:'मशरूम और प्याज़ को बारीक काटें, फिर उन्हें पिसे लहसुन के साथ सूखे या हल्के तेल लगे पैन में मध्यम-तेज़ आँच पर लगभग 8 मिनट पकाएँ, जब तक मशरूम से निकला पानी पूरी तरह सूख न जाए — यही चरण टिक्कियों को बिखरने से रोकता है। मिश्रण को थोड़ा ठंडा होने दें, फिर अंडा, ब्रेडक्रम्ब्स, कटा हरा धनिया और अच्छी चुटकी नमक मिलाकर एक नरम, आकार देने योग्य लोई बनाएँ; गीली लगे तो एक चम्मच और ब्रेडक्रम्ब्स डालें। गीले हाथों से छोटी टिक्कियाँ बनाएँ। पैन में तेल गरम करें और मध्यम आँच पर हर तरफ लगभग 3 मिनट, गहरे सुनहरे और जमे होने तक तलें। किचन पेपर पर निकालें और थोड़ा नमक छिड़कें। गरम या ठंडा, लहसुन की चटनी, दही या हरे सलाद के साथ परोसें।',
      tr:'Mantar ve soğanı ince doğrayın, sonra dövülmüş sarımsakla birlikte kuru ya da hafif yağlı bir tavada orta-yüksek ateşte yaklaşık 8 dakika, mantarların bıraktığı su tamamen çekilene dek pişirin — köftelerin dağılmasını önleyen adım budur. Karışımı biraz soğutun, sonra yumurta, galeta unu, kıyılmış maydanoz ve iyi bir tutam tuzu yoğurup yumuşak, şekil verilebilir bir hamur elde edin; ıslak gelirse bir kaşık daha galeta unu ekleyin. Islak ellerle küçük köfteler şekillendirin. Tavada yağı ısıtın ve orta ateşte her yüzü yaklaşık 3 dakika, koyu altın rengi alıp sıkılaşana dek kızartın. Kâğıt havluda süzüp biraz tuz serpin. Sıcak ya da soğuk, sarımsaklı sos, yoğurt veya yeşil salatayla servis edin.',
      it:'Trita finemente i funghi e la cipolla, poi cuocili con l’aglio tritato in una padella asciutta o appena unta a fuoco medio-alto per circa 8 minuti, finché l’acqua che i funghi rilasciano è del tutto evaporata — è questo passaggio a tenere insieme le polpette. Fai intiepidire il composto, poi incorpora l’uovo, il pangrattato, il prezzemolo tritato e una buona presa di sale fino a una pasta morbida e modellabile; se risulta umida, aggiungi un altro cucchiaio di pangrattato. Forma piccole polpette con le mani bagnate. Scalda l’olio in padella e friggile a fuoco medio circa 3 minuti per lato, finché sono ben dorate e sode. Scolale su carta da cucina e sala leggermente. Servile calde o fredde, con salsa all’aglio, yogurt o un’insalata verde.',
      ko:'버섯과 양파를 곱게 다진 뒤 다진 마늘과 함께 기름 없이 또는 살짝 두른 팬에서 중강불로 약 8분, 버섯에서 나온 물기가 완전히 날아갈 때까지 볶는다 — 이 과정이 전이 부서지지 않게 한다. 반죽을 조금 식힌 뒤 달걀, 빵가루, 다진 파슬리, 소금 넉넉히 한 꼬집을 넣어 부드럽고 빚기 좋은 반죽을 만든다. 질면 빵가루를 한 술 더 넣는다. 젖은 손으로 작은 전을 빚는다. 팬에 기름을 데우고 중불에서 한 면당 약 3분씩, 진한 황금색으로 단단해질 때까지 부친다. 키친타월에 기름을 빼고 소금을 조금 뿌린다. 뜨겁게 또는 차갑게, 마늘 소스나 요구르트, 그린 샐러드와 함께 낸다.' } },

  { id:'budget_025', name:NAMES.ovaz, servings:2, prep:2, cook:10, costRon:2, nut:{cal:260,prot:9,carb:41,fat:7,fib:5}, tags:['budget','vegetarian','quick'],
    ing:[ {q:80,u:'g',n:I.oats}, {q:400,u:'ml',n:I.milk}, {q:100,u:'ml',n:I.water}, {q:2,u:'tbsp',n:I.sugar}, {q:1,u:'tsp',n:I.cinnamon}, {n:I.salt} ],
    steps:{
      ro:'Pune fulgii de ovăz într-o crăticioară cu laptele, apa și un vârf de sare — apa împiedică lipirea și subțiază puțin laptele. Adu la un clocot blând la foc mediu, amestecând, apoi dă focul mic și fierbe circa 6 minute, amestecând des, până ovăzul e moale și cremos. Adaugă zahărul și scorțișoara în ultimul minut. Se îngroașă pe măsură ce stă, așa că mai slăbește-l cu un strop de lapte dacă e nevoie. Servește cald, ornat cu fructe, nuci sau o lingură de gem, după gust.',
      en:'Put the rolled oats in a small pot with the milk, the water and a tiny pinch of salt — the water keeps it from catching and lightens the milk. Bring to a gentle simmer over medium heat, stirring, then lower the heat and cook for about 6 minutes, stirring often, until the oats are soft and creamy. Stir in the sugar and the cinnamon in the last minute. It thickens as it stands, so loosen it with a splash more milk if needed. Serve hot, topped with fruit, nuts or a spoon of jam, to taste.',
      es:'Pon los copos de avena en un cazo con la leche, el agua y una pizca mínima de sal — el agua evita que se pegue y aligera la leche. Lleva a un hervor suave a fuego medio, removiendo, luego baja el fuego y cocina unos 6 minutos, removiendo a menudo, hasta que la avena esté blanda y cremosa. Añade el azúcar y la canela en el último minuto. Espesa al reposar, así que aflójala con un chorrito más de leche si hace falta. Sirve caliente, con fruta, frutos secos o una cucharada de mermelada por encima, al gusto.',
      fr:'Mettez les flocons d’avoine dans une petite casserole avec le lait, l’eau et une toute petite pincée de sel — l’eau empêche que ça attache et allège le lait. Portez à léger frémissement à feu moyen, en remuant, puis baissez le feu et laissez cuire environ 6 minutes, en remuant souvent, jusqu’à ce que l’avoine soit tendre et crémeuse. Incorporez le sucre et la cannelle dans la dernière minute. Cela épaissit en reposant, détendez-le donc avec un peu de lait si besoin. Servez chaud, garni de fruits, de noix ou d’une cuillerée de confiture, selon le goût.',
      de:'Die Haferflocken mit der Milch, dem Wasser und einer winzigen Prise Salz in einen kleinen Topf geben — das Wasser verhindert Ansetzen und macht die Milch leichter. Bei mittlerer Hitze unter Rühren sanft zum Köcheln bringen, dann die Hitze reduzieren und etwa 6 Minuten kochen, oft rühren, bis der Hafer weich und cremig ist. Zucker und Zimt in der letzten Minute einrühren. Er wird beim Stehen fester, daher bei Bedarf mit einem Schuss Milch lockern. Heiß servieren, nach Geschmack mit Obst, Nüssen oder einem Löffel Marmelade garniert.',
      pt:'Coloque os flocos de aveia num tacho pequeno com o leite, a água e uma pitada mínima de sal — a água impede que pegue e torna o leite mais leve. Leve a fervura branda em lume médio, mexendo, depois baixe o lume e cozinhe cerca de 6 minutos, mexendo com frequência, até a aveia ficar macia e cremosa. Junte o açúcar e a canela no último minuto. Engrossa ao repousar, por isso desfaça com um pouco mais de leite se precisar. Sirva quente, coberto com fruta, frutos secos ou uma colher de compota, a gosto.',
      ru:'Всыпьте овсяные хлопья в небольшую кастрюлю с молоком, водой и крошечной щепоткой соли — вода не даёт пригореть и делает молоко легче. Доведите до слабого кипения на среднем огне, помешивая, затем убавьте огонь и варите около 6 минут, часто помешивая, пока овсянка не станет мягкой и кремовой. Вмешайте сахар и корицу в последнюю минуту. При стоянии она густеет, поэтому при необходимости разведите ложкой молока. Подавайте горячей, украсив фруктами, орехами или ложкой варенья, по вкусу.',
      ar:'ضع رقائق الشوفان في قدر صغير مع الحليب والماء ورشة ملح صغيرة جداً — الماء يمنع الالتصاق ويخفّف الحليب. ارفعه لغليان هادئ على نار متوسطة مع التقليب، ثم اخفض النار واطهه نحو 6 دقائق مع التحريك المتكرر حتى يصير الشوفان طرياً كريمياً. أضف السكر والقرفة في الدقيقة الأخيرة. يتماسك عند الوقوف، لذا خفّفه برشة حليب إضافية عند اللزوم. قدّمه ساخناً، مزيّناً بالفاكهة أو المكسرات أو ملعقة مربّى، حسب الرغبة.',
      zh:'把燕麦片放入小锅，加牛奶、水和极少的一撮盐——水能防粘并让牛奶更清爽。中火搅拌着煮至微沸，转小火煮约6分钟，常搅动，至燕麦软糯绵密。最后一分钟拌入糖和肉桂粉。静置会变稠，需要时加少许牛奶稀释。趁热食用，随喜好用水果、坚果或一勺果酱点缀。',
      ja:'オートミールを小鍋に入れ、牛乳、水、ごく少量の塩を加える——水が焦げ付きを防ぎ、牛乳を軽くする。中火で混ぜながら静かに煮立て、火を弱めて約6分、よく混ぜながらオートミールが柔らかくクリーミーになるまで煮る。仕上げの1分で砂糖とシナモンを混ぜる。置くと固くなるので、必要なら牛乳を少し足してゆるめる。温かいうちに、好みで果物やナッツ、ジャムひとさじをのせて供する。',
      hi:'ओट्स को एक छोटे बर्तन में दूध, पानी और बहुत थोड़ी चुटकी नमक के साथ डालें — पानी चिपकने से रोकता है और दूध को हल्का करता है। मध्यम आँच पर चलाते हुए हल्के उबाल पर लाएँ, फिर आँच कम करके लगभग 6 मिनट, बार-बार चलाते हुए पकाएँ जब तक ओट्स नरम और मलाईदार हो जाएँ। आखिरी मिनट में चीनी और दालचीनी मिलाएँ। रखने पर गाढ़ा होता है, इसलिए ज़रूरत हो तो थोड़ा दूध डालकर पतला करें। गरम परोसें, स्वादानुसार फल, मेवे या एक चम्मच जैम से सजाकर।',
      tr:'Yulaf ezmesini küçük bir tencereye süt, su ve çok küçük bir tutam tuzla koyun — su, dibe tutmayı önler ve sütü hafifletir. Orta ateşte karıştırarak hafif kaynamaya getirin, sonra ateşi kısıp yaklaşık 6 dakika, sık karıştırarak yulaf yumuşayıp kremamsı olana dek pişirin. Şeker ve tarçını son dakikada karıştırın. Bekledikçe koyulaşır, gerekirse biraz sütle açın. Sıcak servis edin, arzuya göre meyve, kuruyemiş ya da bir kaşık reçelle süsleyin.',
      it:'Metti i fiocchi d’avena in un pentolino con il latte, l’acqua e un pizzico minimo di sale — l’acqua evita che attacchi e alleggerisce il latte. Porta a leggero sobbollore a fuoco medio, mescolando, poi abbassa la fiamma e cuoci per circa 6 minuti, mescolando spesso, finché l’avena è morbida e cremosa. Unisci lo zucchero e la cannella nell’ultimo minuto. Si addensa riposando, quindi allungalo con un goccio di latte se serve. Servi caldo, guarnito con frutta, noci o un cucchiaio di marmellata, a piacere.',
      ko:'작은 냄비에 귀리, 우유, 물, 아주 약간의 소금을 넣는다 — 물이 눌어붙음을 막고 우유를 가볍게 한다. 중불에서 저으며 잔잔하게 끓기 시작하면 불을 줄여 약 6분간 자주 저으며 귀리가 부드럽고 크리미해질 때까지 끓인다. 마지막 1분에 설탕과 계피를 넣어 섞는다. 두면 되직해지므로 필요하면 우유를 조금 더 넣어 풀어준다. 뜨겁게, 기호에 따라 과일, 견과, 잼 한 술을 올려 낸다.' } },

  { id:'budget_026', name:NAMES.praz, servings:2, prep:15, cook:30, costRon:4, nut:{cal:260,prot:5,carb:24,fat:16,fib:7}, tags:['budget','vegan','one-pot'],
    ing:[ {q:500,u:'g',n:I.leek}, {q:1,n:I.carrot}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:100,u:'g',n:I.olives}, {q:1,n:I.bayLeaf}, {q:100,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Curăță prazul, crestează-l pe lungime și spală-l bine între foi, unde se ascunde nisipul, apoi taie-l semi-rondele groase. Încălzește uleiul într-o oală și înmoaie prazul și morcovul dat pe răzătoare la foc mediu circa 8 minute, amestecând, până se lasă și se îndulcesc — prazul nu trebuie să se rumenească, doar să se topească. Adaugă roșiile pasate, foaia de dafin, apa și un praf mic de sare, căci măslinele sunt deja sărate, apoi fierbe blând, acoperit, circa 15 minute, până prazul e mătăsos. Pune măslinele în ultimele 5 minute, cât să se încălzească fără să amărască. Potrivește de sare. Servește cald cu pâine — un fel de post clasic românesc, și mai bun a doua zi.',
      en:'Trim the leeks, slit them lengthwise and rinse well between the layers where grit hides, then cut into thick half-rings. Warm the oil in a pot and soften the leeks and grated carrot over medium heat for about 8 minutes, stirring, until they collapse and sweeten — leeks must not brown, only melt. Add the tomato passata, bay leaf, water and a small pinch of salt, since the olives are already salty, then simmer gently, covered, for about 15 minutes, until the leeks are silky. Stir in the olives in the last 5 minutes so they warm through without turning bitter. Taste and adjust the salt. Serve warm with bread, a classic Romanian Lenten dish that is even better the next day.',
      es:'Limpia los puerros, córtalos a lo largo y enjuágalos bien entre las capas, donde se esconde la tierra, luego trocéalos en medias rodajas gruesas. Calienta el aceite en una olla y ablanda los puerros y la zanahoria rallada a fuego medio unos 8 minutos, removiendo, hasta que se deshagan y endulcen —el puerro no debe dorarse, solo fundirse—. Añade el tomate triturado, la hoja de laurel, el agua y una pizca pequeña de sal, pues las aceitunas ya son saladas, y cuece suave, tapado, unos 15 minutos, hasta que el puerro esté sedoso. Incorpora las aceitunas en los últimos 5 minutos, para que se calienten sin amargar. Ajusta la sal. Sirve caliente con pan, un plato de vigilia rumano clásico, aún mejor al día siguiente.',
      fr:'Parez les poireaux, fendez-les dans la longueur et rincez-les bien entre les couches, où se cache le sable, puis coupez-les en demi-rondelles épaisses. Chauffez l’huile dans une casserole et faites fondre les poireaux et la carotte râpée à feu moyen environ 8 minutes, en remuant, jusqu’à ce qu’ils s’affaissent et sucrent — les poireaux ne doivent pas dorer, seulement fondre. Ajoutez les tomates passées, la feuille de laurier, l’eau et une petite pincée de sel, car les olives sont déjà salées, puis laissez mijoter à couvert environ 15 minutes, jusqu’à ce que les poireaux soient soyeux. Ajoutez les olives dans les 5 dernières minutes pour qu’elles chauffent sans devenir amères. Rectifiez le sel. Servez chaud avec du pain, un plat de carême roumain classique, meilleur encore le lendemain.',
      de:'Den Lauch putzen, längs einschneiden und gut zwischen den Schichten waschen, wo sich Sand versteckt, dann in dicke Halbringe schneiden. Das Öl in einem Topf erwärmen und Lauch und geriebene Karotte bei mittlerer Hitze etwa 8 Minuten unter Rühren weich dünsten, bis sie zusammenfallen und süßlich werden — der Lauch darf nicht bräunen, nur zerfallen. Passierte Tomaten, Lorbeerblatt, Wasser und eine kleine Prise Salz zugeben, da die Oliven schon salzig sind, dann zugedeckt etwa 15 Minuten sanft köcheln, bis der Lauch seidig ist. Die Oliven in den letzten 5 Minuten einrühren, damit sie durchwärmen, ohne bitter zu werden. Mit Salz abschmecken. Warm mit Brot servieren — ein klassisches rumänisches Fastengericht, am nächsten Tag noch besser.',
      pt:'Limpe os alhos-franceses, corte-os ao comprido e lave bem entre as camadas, onde se esconde a terra, depois corte em meias-rodelas grossas. Aqueça o óleo numa panela e amoleça o alho-francês e a cenoura ralada em lume médio cerca de 8 minutos, mexendo, até desfazerem e adoçarem — o alho-francês não deve alourar, só derreter. Junte o tomate passata, a folha de louro, a água e uma pitada pequena de sal, pois as azeitonas já são salgadas, e cozinhe em lume brando, tapado, cerca de 15 minutos, até o alho-francês ficar sedoso. Junte as azeitonas nos últimos 5 minutos, para aquecerem sem amargar. Acerte o sal. Sirva quente com pão, um prato de jejum romeno clássico, ainda melhor no dia seguinte.',
      ru:'Очистите лук-порей, надрежьте вдоль и хорошо промойте между слоями, где прячется песок, затем нарежьте толстыми полукольцами. Разогрейте масло в кастрюле и потушите порей с натёртой морковью на среднем огне около 8 минут, помешивая, пока они не осядут и не станут сладковатыми — порей не должен подрумяниться, только размягчиться. Добавьте протёртые томаты, лавровый лист, воду и маленькую щепотку соли, ведь оливки уже солёные, затем тушите под крышкой около 15 минут, пока порей не станет шелковистым. Вмешайте оливки за последние 5 минут, чтобы они прогрелись, не горча. Посолите по вкусу. Подавайте тёплым с хлебом — классическое румынское постное блюдо, которое на следующий день ещё вкуснее.',
      ar:'نظّف الكرّاث، شقّه طولياً واغسله جيداً بين طبقاته حيث يختبئ الرمل، ثم قطّعه أنصاف حلقات سميكة. سخّن الزيت في قدر وليّن الكرّاث والجزر المبشور على نار متوسطة نحو 8 دقائق مع التقليب حتى يذبل ويحلو — يجب ألا يحمرّ الكرّاث بل يذوب فقط. أضف الطماطم المهروسة وورقة الغار والماء ورشة ملح صغيرة، فالزيتون مالح أصلاً، ثم اطهه مغطى على نار هادئة نحو 15 دقيقة حتى يصبح الكرّاث حريرياً. أضف الزيتون في آخر 5 دقائق كي يسخن دون أن يصير مرّاً. اضبط الملح. قدّمه دافئاً مع الخبز — طبق صيامي روماني كلاسيكي، وألذّ في اليوم التالي.',
      zh:'把韭葱去根，纵向剖开，在层与层之间仔细冲洗掉藏着的泥沙，再切成厚半圈。锅中热油，中火将韭葱和擦丝的胡萝卜煸软约8分钟，边煸边让它塌软回甜——韭葱不要煎褐，只需软烂。加入番茄泥、香叶、水和一小撮盐（橄榄本身已咸），加盖小火煮约15分钟，至韭葱柔滑。最后5分钟放入橄榄，让它热透而不发苦。调盐。趁热配面包食用——一道经典的罗马尼亚素斋菜，隔天更好吃。',
      ja:'リーキは根を落として縦に切り込みを入れ、砂が隠れる層の間までよく洗い、厚めの半月切りにする。鍋に油を温め、リーキとすりおろしたにんじんを中火で約8分、混ぜながらくたっと甘くなるまで炒める——リーキは色づけず、とろけさせるだけ。トマトピューレ、ローリエ、水、そして塩ひとつまみ（オリーブが塩気を持つので控えめに）を加え、ふたをして弱火で約15分、リーキがなめらかになるまで煮る。オリーブは最後の5分で加え、苦くならないよう温める。塩で味を調える。パンを添えて温かいうちに——ルーマニアの精進料理の定番で、翌日はさらに美味しい。',
      hi:'लीक को साफ करें, लंबाई में चीरा लगाकर परतों के बीच अच्छी तरह धोएँ जहाँ रेत छिपती है, फिर मोटे अर्ध-गोल टुकड़ों में काटें। बर्तन में तेल गरम करें और लीक व कद्दूकस गाजर को मध्यम आँच पर लगभग 8 मिनट चलाते हुए भूनें जब तक वे नरम और मीठे हो जाएँ — लीक को भूरा न होने दें, बस पिघलने दें। टमाटर प्यूरी, तेज पत्ता, पानी और एक छोटी चुटकी नमक डालें, क्योंकि जैतून पहले से नमकीन हैं, फिर ढककर धीमी आँच पर लगभग 15 मिनट पकाएँ जब तक लीक रेशमी हो जाए। जैतून आखिरी 5 मिनट में डालें ताकि वे गरम हों पर कड़वे न हों। नमक ठीक करें। गरम, ब्रेड के साथ परोसें — एक क्लासिक रोमानियाई व्रत व्यंजन, अगले दिन और भी बेहतर।',
      tr:'Pırasaları ayıklayın, boylamasına yarıp kum saklanan katmanların arasını iyice yıkayın, sonra kalın yarım halkalar hâlinde doğrayın. Tencerede yağı ısıtın ve pırasa ile rendelenmiş havucu orta ateşte, karıştırarak yaklaşık 8 dakika, dağılıp tatlanana dek yumuşatın — pırasa kızarmamalı, yalnızca erimeli. Domates püresi, defne yaprağı, su ve küçük bir tutam tuz ekleyin, çünkü zeytinler zaten tuzlu, sonra kapağını kapatıp kısık ateşte yaklaşık 15 dakika, pırasa ipeksi olana dek pişirin. Zeytinleri son 5 dakikada ekleyin ki acılaşmadan ısınsın. Tuzu ayarlayın. Ekmekle sıcak servis edin — klasik bir Rumen perhiz yemeği, ertesi gün daha da lezzetli.',
      it:'Pulisci i porri, incidili per il lungo e sciacquali bene tra gli strati, dove si nasconde la terra, poi tagliali a mezze rondelle spesse. Scalda l’olio in una pentola e fai ammorbidire i porri e la carota grattugiata a fuoco medio per circa 8 minuti, mescolando, finché cedono e diventano dolci — i porri non devono dorare, solo sciogliersi. Aggiungi la passata, l’alloro, l’acqua e un piccolo pizzico di sale, poiché le olive sono già salate, poi fai sobbollire coperto per circa 15 minuti, finché i porri sono setosi. Unisci le olive negli ultimi 5 minuti, così si scaldano senza diventare amare. Regola il sale. Servi caldo con pane — un classico piatto di magro romeno, ancora migliore il giorno dopo.',
      ko:'리크는 다듬어 길게 칼집을 내고 흙이 숨는 겹 사이까지 잘 씻은 뒤 두툼한 반달 모양으로 썬다. 냄비에 기름을 데우고 리크와 채 썬 당근을 중불에서 약 8분간 저으며 무르고 단맛이 날 때까지 볶는다 — 리크는 색을 내지 말고 녹이듯 익힌다. 토마토 퓌레, 월계수 잎, 물, 그리고 소금 한 꼬집만(올리브가 이미 짜다) 넣고 뚜껑을 덮어 약불에서 약 15분간 리크가 비단결처럼 부드러워질 때까지 끓인다. 올리브는 마지막 5분에 넣어 쓴맛이 나지 않게 데운다. 간을 맞춘다. 빵을 곁들여 따뜻하게 낸다 — 루마니아의 대표적인 금육식 요리로, 다음 날 더 맛있다.' } },

  { id:'budget_027', name:NAMES.bulgur, servings:2, prep:10, cook:20, costRon:3, nut:{cal:400,prot:10,carb:66,fat:12,fib:12}, tags:['budget','vegan','family'],
    ing:[ {q:200,u:'g',n:I.bulgur}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:1,n:I.bellPepper}, {q:3,u:'tbsp',n:I.oil}, {q:100,u:'g',n:I.passata}, {q:400,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Clătește bulgurul într-o sită și lasă-l să se scurgă. Încălzește uleiul într-o oală și călește ceapa tocată, morcovul ras și ardeiul tăiat cubulețe la foc mediu circa 6 minute, până se înmoaie. Adaugă roșiile pasate și gătește 2 minute, apoi pune bulgurul și amestecă-l în ulei un minut, ca fiecare bob să se îmbrace — așa iese pilaful pufos, nu lipicios. Toarnă apa fierbinte cu un praf bun de sare, dă în clocot, apoi acoperă și fierbe la foc mic circa 12 minute, până se absoarbe apa. Ia de pe foc și lasă acoperit 5 minute, apoi afânează cu furculița. Servește cald simplu sau ca garnitură.',
      en:'Rinse the bulgur in a sieve and leave it to drain. Warm the oil in a pot and cook the chopped onion, grated carrot and diced pepper over medium heat for about 6 minutes, until soft. Stir in the tomato passata and cook for 2 minutes, then add the bulgur and toss it in the oil for a minute so every grain is coated — this keeps the pilaf fluffy rather than sticky. Pour in the hot water with a good pinch of salt, bring to a simmer, then cover and cook on the lowest heat for about 12 minutes, until the water is absorbed. Take it off the heat and let it stand, covered, for 5 minutes, then fluff with a fork. Serve warm on its own or as a side.',
      es:'Enjuaga el bulgur en un colador y déjalo escurrir. Calienta el aceite en una olla y sofríe la cebolla picada, la zanahoria rallada y el pimiento en dados a fuego medio unos 6 minutos, hasta que ablanden. Añade el tomate triturado y cocina 2 minutos, luego incorpora el bulgur y remuévelo en el aceite un minuto para que cada grano se impregne —así el pilaf queda suelto y no pegajoso—. Vierte el agua caliente con una buena pizca de sal, lleva a hervor, tapa y cuece a fuego mínimo unos 12 minutos, hasta que se absorba el agua. Retira del fuego y deja reposar tapado 5 minutos, luego separa con un tenedor. Sirve caliente solo o como guarnición.',
      fr:'Rincez le boulgour dans une passoire et laissez-le égoutter. Chauffez l’huile dans une casserole et faites revenir l’oignon haché, la carotte râpée et le poivron en dés à feu moyen environ 6 minutes, jusqu’à ce qu’ils soient tendres. Ajoutez les tomates passées et poursuivez 2 minutes, puis ajoutez le boulgour et remuez-le dans l’huile une minute pour enrober chaque grain — c’est ce qui rend le pilaf léger plutôt que collant. Versez l’eau chaude avec une bonne pincée de sel, portez à frémissement, couvrez et laissez cuire à feu très doux environ 12 minutes, jusqu’à absorption de l’eau. Retirez du feu et laissez reposer à couvert 5 minutes, puis égrenez à la fourchette. Servez chaud, seul ou en accompagnement.',
      de:'Den Bulgur in einem Sieb abspülen und abtropfen lassen. Das Öl in einem Topf erwärmen und die gehackte Zwiebel, die geriebene Karotte und die gewürfelte Paprika bei mittlerer Hitze etwa 6 Minuten weich dünsten. Passierte Tomaten einrühren und 2 Minuten kochen, dann den Bulgur zugeben und eine Minute im Öl schwenken, damit jedes Korn überzogen ist — so wird das Pilaw locker statt klebrig. Das heiße Wasser mit einer guten Prise Salz angießen, aufkochen, dann zugedeckt bei niedrigster Hitze etwa 12 Minuten garen, bis das Wasser aufgesogen ist. Vom Herd nehmen, zugedeckt 5 Minuten ruhen lassen, dann mit der Gabel auflockern. Warm servieren, pur oder als Beilage.',
      pt:'Enxágue o bulgur num coador e deixe escorrer. Aqueça o óleo numa panela e refogue a cebola picada, a cenoura ralada e o pimento aos cubos em lume médio cerca de 6 minutos, até amolecerem. Junte o tomate passata e cozinhe 2 minutos, depois adicione o bulgur e envolva-o no óleo um minuto para que cada grão fique revestido — é isto que deixa o pilaf solto em vez de pegajoso. Deite a água quente com uma boa pitada de sal, leve a fervura, tape e cozinhe em lume brando cerca de 12 minutos, até a água ser absorvida. Retire do lume e deixe repousar tapado 5 minutos, depois solte com um garfo. Sirva quente, simples ou como acompanhamento.',
      ru:'Промойте булгур в сите и дайте стечь. Разогрейте масло в кастрюле и обжарьте нарезанный лук, натёртую морковь и нарезанный кубиками перец на среднем огне около 6 минут, до мягкости. Вмешайте протёртые томаты и готовьте 2 минуты, затем добавьте булгур и минуту помешивайте в масле, чтобы каждое зёрнышко покрылось, — так плов получится рассыпчатым, а не липким. Влейте горячую воду с хорошей щепоткой соли, доведите до кипения, накройте и готовьте на самом слабом огне около 12 минут, пока вода не впитается. Снимите с огня, дайте постоять под крышкой 5 минут, затем разрыхлите вилкой. Подавайте тёплым, сам по себе или как гарнир.',
      ar:'اشطف البرغل في مصفاة واتركه ليتصفّى. سخّن الزيت في قدر وشوّح البصل المفروم والجزر المبشور والفلفل المقطّع مكعبات على نار متوسطة نحو 6 دقائق حتى يلين. أضف الطماطم المهروسة واطهها دقيقتين، ثم أضف البرغل وقلّبه في الزيت دقيقة كي تتغلّف كل حبة — هذا ما يجعل البرغل مفكّكاً لا لزجاً. أضف الماء الساخن مع رشة ملح جيدة، ارفعه للغليان، غطّه واطهه على أهدأ نار نحو 12 دقيقة حتى يمتص الماء. ارفعه عن النار واتركه مغطى 5 دقائق، ثم فكّكه بالشوكة. قدّمه دافئاً وحده أو كطبق جانبي.',
      zh:'把布格麦在筛中冲洗后沥干。锅中热油，中火将切碎的洋葱、擦丝的胡萝卜和切丁的甜椒煸软约6分钟。加入番茄泥炒2分钟，再放入布格麦，在油中翻拌1分钟，让每粒都裹上油——这样抓饭才松散不黏。倒入加了一大撮盐的热水，煮开后加盖，用最小火焖约12分钟，至水分收干。离火，加盖焖5分钟，再用叉子拨松。趁热单吃或作配菜。',
      ja:'ブルグルをざるで洗い、水気を切る。鍋に油を温め、みじん切りの玉ねぎ、すりおろしたにんじん、角切りのパプリカを中火で約6分やわらかくなるまで炒める。トマトピューレを加えて2分炒め、ブルグルを入れて1分ほど油をまとわせる——こうすると一粒ずつがコーティングされ、ベタつかずふっくら仕上がる。塩ひとつまみを加えた熱湯を注ぎ、煮立ったらふたをして最弱火で約12分、水分が吸われるまで炊く。火から下ろし、ふたをして5分蒸らし、フォークでほぐす。温かいうちに、そのまま、あるいは付け合わせとして供する。',
      hi:'बुलगुर को छलनी में धोकर छान लें। बर्तन में तेल गरम करें और कटा प्याज़, कद्दूकस गाजर और कटी शिमला मिर्च मध्यम आँच पर लगभग 6 मिनट नरम होने तक भूनें। टमाटर प्यूरी डालकर 2 मिनट पकाएँ, फिर बुलगुर डालकर एक मिनट तेल में मिलाएँ ताकि हर दाना लिपट जाए — इससे पुलाव चिपचिपा नहीं, खिला-खिला बनता है। एक अच्छी चुटकी नमक के साथ गरम पानी डालें, उबाल लाएँ, फिर ढककर सबसे धीमी आँच पर लगभग 12 मिनट पकाएँ जब तक पानी सूख जाए। आँच से उतारकर ढके 5 मिनट रखें, फिर काँटे से खिलाएँ। गरम, अकेले या साथ में परोसें।',
      tr:'Bulguru bir süzgeçte yıkayıp süzülmeye bırakın. Tencerede yağı ısıtın ve doğranmış soğan, rendelenmiş havuç ve küp doğranmış biberi orta ateşte yaklaşık 6 dakika yumuşayana dek kavurun. Domates püresini ekleyip 2 dakika pişirin, sonra bulguru ekleyip bir dakika yağda çevirin ki her tane kaplansın — pilavı yapışkan değil tane tane yapan budur. İyi bir tutam tuzla sıcak suyu ekleyin, kaynamaya getirin, kapağını kapatıp en kısık ateşte yaklaşık 12 dakika, su çekilene dek pişirin. Ocaktan alıp kapağı kapalı 5 dakika dinlendirin, sonra çatalla kabartın. Sıcak, tek başına ya da yanında servis edin.',
      it:'Sciacqua il bulgur in un colino e lascialo scolare. Scalda l’olio in una pentola e fai rosolare la cipolla tritata, la carota grattugiata e il peperone a dadini a fuoco medio per circa 6 minuti, finché sono morbidi. Unisci la passata e cuoci 2 minuti, poi aggiungi il bulgur e giralo nell’olio un minuto così ogni chicco si riveste — è questo a rendere il pilaf sgranato invece che colloso. Versa l’acqua calda con una buona presa di sale, porta a sobbollore, copri e cuoci a fuoco bassissimo per circa 12 minuti, finché l’acqua è assorbita. Togli dal fuoco e lascia riposare coperto 5 minuti, poi sgrana con una forchetta. Servi caldo da solo o come contorno.',
      ko:'불구르를 체에 헹궈 물기를 뺀다. 냄비에 기름을 데우고 다진 양파, 채 썬 당근, 깍둑 썬 파프리카를 중불에서 약 6분간 부드러워질 때까지 볶는다. 토마토 퓌레를 넣어 2분 볶은 뒤 불구르를 넣고 1분간 기름에 버무려 알알이 코팅한다 — 이렇게 하면 필라프가 질척이지 않고 보슬보슬해진다. 소금 넉넉히 한 꼬집을 넣은 뜨거운 물을 붓고 끓어오르면 뚜껑을 덮어 가장 약한 불에서 약 12분, 물이 흡수될 때까지 익힌다. 불에서 내려 뚜껑을 덮은 채 5분 뜸을 들이고 포크로 부슬부슬 푼다. 그대로 또는 곁들이로 따뜻하게 낸다.' } },

  { id:'budget_028', name:NAMES.bame, servings:2, prep:10, cook:25, costRon:4, nut:{cal:200,prot:5,carb:22,fat:12,fib:8}, tags:['budget','vegan','one-pot'],
    ing:[ {q:400,u:'g',n:I.okra}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:200,u:'g',n:I.passata}, {q:1,n:I.lemon}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești bame proaspete, lasă păstăile întregi și taie doar vârful codiței — dacă le crestezi, lasă sucul cleios; cele congelate merg direct din pungă. Încălzește uleiul într-o oală și înmoaie ceapa tocată la foc mediu 5 minute, apoi adaugă usturoiul feliat 30 de secunde. Pune bamele și gătește blând 5 minute, fără să amesteci prea mult, ca păstăile să rămână întregi. Toarnă roșiile pasate și un strop de apă cu un praf de sare, plus zeama de la o jumătate de lămâie — aciditatea e secretul care ține bamele să nu devină cleioase. Fierbe neacoperit circa 15 minute, până bamele sunt fragede și sosul a scăzut. Servește cald cu pâine sau orez, cu restul de lămâie deasupra.',
      en:'If using fresh okra, leave the pods whole and trim only the very tip of the stem — cutting into them releases the sticky sap; frozen okra goes straight from the bag. Warm the oil in a pot and soften the chopped onion over medium heat for 5 minutes, then add the sliced garlic for 30 seconds. Add the okra and cook gently for 5 minutes without stirring too much, so the pods stay intact. Pour in the tomato passata and a splash of water with a pinch of salt, plus the juice of half a lemon — the acid is the trick that keeps okra from going slimy. Simmer, uncovered, for about 15 minutes, until the okra is tender and the sauce has reduced. Serve warm with bread or rice, finished with the remaining lemon.',
      es:'Si usas okra fresca, deja las vainas enteras y corta solo la puntita del tallo —si las cortas, sueltan la baba pegajosa—; la congelada va directa de la bolsa. Calienta el aceite en una olla y ablanda la cebolla picada a fuego medio 5 minutos, luego añade el ajo en láminas 30 segundos. Añade la okra y cocina suave 5 minutos sin remover mucho, para que las vainas queden enteras. Vierte el tomate triturado y un chorrito de agua con una pizca de sal, más el zumo de media limón —el ácido es el truco que evita que la okra se vuelva viscosa—. Cuece destapado unos 15 minutos, hasta que la okra esté tierna y la salsa haya reducido. Sirve caliente con pan o arroz, rematado con el resto del limón.',
      fr:'Si vous utilisez des gombos frais, laissez les gousses entières et coupez seulement l’extrémité de la tige — les entailler libère la sève collante ; les surgelés vont directement du sachet. Chauffez l’huile dans une casserole et faites fondre l’oignon haché à feu moyen 5 minutes, puis ajoutez l’ail émincé 30 secondes. Ajoutez les gombos et faites cuire doucement 5 minutes sans trop remuer, pour garder les gousses intactes. Versez les tomates passées et un filet d’eau avec une pincée de sel, plus le jus d’un demi-citron — l’acidité est l’astuce qui empêche les gombos de devenir gluants. Laissez mijoter à découvert environ 15 minutes, jusqu’à ce que les gombos soient tendres et la sauce réduite. Servez chaud avec du pain ou du riz, arrosé du reste de citron.',
      de:'Bei frischer Okra die Schoten ganz lassen und nur die äußerste Stielspitze abschneiden — beim Einschneiden tritt der klebrige Saft aus; tiefgekühlte Okra kommt direkt aus der Tüte. Das Öl in einem Topf erwärmen und die gehackte Zwiebel bei mittlerer Hitze 5 Minuten weich dünsten, dann den geschnittenen Knoblauch 30 Sekunden zugeben. Die Okra zugeben und 5 Minuten sanft garen, ohne viel zu rühren, damit die Schoten ganz bleiben. Passierte Tomaten und einen Schuss Wasser mit einer Prise Salz angießen, dazu den Saft einer halben Zitrone — die Säure ist der Trick, damit Okra nicht schleimig wird. Offen etwa 15 Minuten köcheln, bis die Okra weich und die Sauce eingedickt ist. Warm mit Brot oder Reis servieren, mit dem restlichen Zitronensaft beträufelt.',
      pt:'Se usar quiabo fresco, deixe as vagens inteiras e corte só a pontinha do pé — cortá-las liberta a seiva pegajosa; o congelado vai direto do saco. Aqueça o óleo numa panela e amoleça a cebola picada em lume médio 5 minutos, depois junte o alho laminado 30 segundos. Junte o quiabo e cozinhe suavemente 5 minutos sem mexer muito, para as vagens ficarem inteiras. Deite o tomate passata e um pouco de água com uma pitada de sal, mais o sumo de meio limão — a acidez é o truque que impede o quiabo de ficar viscoso. Cozinhe destapado cerca de 15 minutos, até o quiabo ficar tenro e o molho reduzir. Sirva quente com pão ou arroz, rematado com o resto do limão.',
      ru:'Если используете свежую бамию, оставьте стручки целыми и срежьте лишь самый кончик стебля — надрезы выпускают клейкий сок; замороженная идёт прямо из пакета. Разогрейте масло в кастрюле и потушите нарезанный лук на среднем огне 5 минут, затем добавьте нарезанный чеснок на 30 секунд. Добавьте бамию и готовьте мягко 5 минут, не помешивая слишком, чтобы стручки остались целыми. Влейте протёртые томаты и немного воды со щепоткой соли, а также сок половины лимона — кислота и есть секрет, чтобы бамия не стала слизистой. Тушите без крышки около 15 минут, пока бамия не станет мягкой, а соус не загустеет. Подавайте тёплой с хлебом или рисом, сбрызнув оставшимся лимоном.',
      ar:'إن استخدمت البامية الطازجة، اترك القرون كاملة واقطع طرف العنق فقط — تقطيعها يطلق المادة اللزجة؛ أما المجمّدة فتذهب مباشرة من الكيس. سخّن الزيت في قدر وليّن البصل المفروم على نار متوسطة 5 دقائق، ثم أضف الثوم المقطّع 30 ثانية. أضف البامية واطهها برفق 5 دقائق دون تقليب كثير كي تبقى القرون سليمة. أضف الطماطم المهروسة ورشة ماء مع رشة ملح، وعصير نصف ليمونة — الحموضة هي السرّ الذي يمنع البامية من أن تصبح لزجة. اطهها دون تغطية نحو 15 دقيقة حتى تلين البامية ويثخن الصلصة. قدّمها دافئة مع الخبز أو الأرز، مع بقية الليمون فوقها.',
      zh:'用新鲜秋葵时，整根保留，只切去蒂梗的最尖端——切开会流出黏液；冷冻秋葵可直接下锅。锅中热油，中火将切碎的洋葱煸软5分钟，再加蒜片炒30秒。放入秋葵，轻轻煮5分钟，不要多翻，让荚保持完整。倒入番茄泥和少许水、一撮盐，再挤入半个柠檬汁——酸味正是防止秋葵发黏的窍门。不加盖煮约15分钟，至秋葵软嫩、酱汁收浓。趁热配面包或米饭，挤上剩下的柠檬。',
      ja:'生のオクラを使うなら莢は丸ごとにし、ヘタの先だけを切る——切り込むと粘りが出る。冷凍オクラは袋から直接でよい。鍋に油を温め、みじん切りの玉ねぎを中火で5分やわらかくし、薄切りのにんにくを30秒加える。オクラを入れ、あまり混ぜずに5分やさしく煮て、莢を崩さない。トマトピューレと少量の水、塩ひとつまみ、そしてレモン半個分の果汁を加える——この酸味こそオクラをぬめらせない秘訣。ふたをせず約15分、オクラが柔らかくソースが煮詰まるまで煮る。パンやご飯を添え、残りのレモンをかけて温かいうちに供する。',
      hi:'ताज़ी भिंडी इस्तेमाल करें तो फलियाँ साबुत रखें और सिर्फ डंठल का सिरा काटें — काटने से चिपचिपा रस निकलता है; जमी भिंडी सीधे थैले से डालें। बर्तन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 5 मिनट नरम करें, फिर कटा लहसुन 30 सेकंड डालें। भिंडी डालें और ज़्यादा हिलाए बिना 5 मिनट धीरे पकाएँ ताकि फलियाँ साबुत रहें। टमाटर प्यूरी और थोड़ा पानी एक चुटकी नमक के साथ डालें, साथ में आधे नींबू का रस — यही खटास भिंडी को लसदार होने से बचाती है। बिना ढके लगभग 15 मिनट पकाएँ जब तक भिंडी नरम और सॉस गाढ़ी हो। गरम, ब्रेड या चावल के साथ, ऊपर बचा नींबू निचोड़कर परोसें।',
      tr:'Taze bamya kullanıyorsanız kozaları bütün bırakın ve yalnızca sap ucunu kesin — kesmek yapışkan suyunu salar; donmuş bamya doğrudan poşetten girer. Tencerede yağı ısıtın ve doğranmış soğanı orta ateşte 5 dakika yumuşatın, sonra dilimlenmiş sarımsağı 30 saniye ekleyin. Bamyayı ekleyip fazla karıştırmadan 5 dakika hafifçe pişirin ki kozalar bütün kalsın. Domates püresi ve bir tutam tuzla biraz su, bir de yarım limonun suyunu ekleyin — bamyayı yapışkanlaşmaktan koruyan sır bu asittir. Kapaksız yaklaşık 15 dakika, bamya yumuşayıp sos koyulaşana dek pişirin. Ekmek ya da pilavla, üzerine kalan limonu sıkarak sıcak servis edin.',
      it:'Se usi okra fresca, lascia i baccelli interi e taglia solo la punta del picciolo — inciderli libera la bava collosa; quella surgelata va dritta dal sacchetto. Scalda l’olio in una pentola e fai ammorbidire la cipolla tritata a fuoco medio 5 minuti, poi aggiungi l’aglio a fette per 30 secondi. Unisci l’okra e cuoci dolcemente 5 minuti senza mescolare troppo, così i baccelli restano interi. Versa la passata e un goccio d’acqua con un pizzico di sale, più il succo di mezzo limone — l’acidità è il trucco che evita all’okra di diventare viscida. Fai sobbollire scoperto circa 15 minuti, finché l’okra è tenera e il sugo si è ridotto. Servi caldo con pane o riso, completando con il limone rimasto.',
      ko:'생오크라를 쓰면 꼬투리를 통째로 두고 꼭지 끝만 자른다 — 칼집을 내면 끈적한 진액이 나온다. 냉동 오크라는 봉지째 바로 넣는다. 냄비에 기름을 데우고 다진 양파를 중불에서 5분 부드럽게 한 뒤 저민 마늘을 30초 넣는다. 오크라를 넣고 꼬투리가 부서지지 않게 많이 젓지 말고 5분간 살살 익힌다. 토마토 퓌레와 물 약간, 소금 한 꼬집, 그리고 레몬 반 개 즙을 넣는다 — 이 산미가 오크라를 미끈해지지 않게 하는 비결이다. 뚜껑을 열고 약 15분, 오크라가 부드러워지고 소스가 졸아들 때까지 끓인다. 빵이나 밥을 곁들이고 남은 레몬을 뿌려 따뜻하게 낸다.' } },

  { id:'budget_029', name:NAMES.bob, servings:2, prep:10, cook:25, costRon:4, nut:{cal:300,prot:16,carb:40,fat:9,fib:14}, tags:['budget','vegan','high-protein'],
    ing:[ {q:400,u:'g',n:I.favaBeans}, {q:1,n:I.onion}, {q:2,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:150,u:'g',n:I.passata}, {q:2,u:'tbsp',n:I.dill}, {n:I.salt} ],
    steps:{
      ro:'Dacă folosești bob uscat, lasă-l la înmuiat peste noapte și curăță pielițele tari; boabele proaspete sau congelate, decojite, nu trebuie înmuiate. Încălzește uleiul într-o oală și călește ceapa tocată la foc mediu 6 minute, până se înmoaie, apoi adaugă usturoiul feliat 30 de secunde. Adaugă roșiile pasate și gătește 2 minute, apoi pune bobul cu apă cât să-l acopere și un praf bun de sare. Fierbe blând circa 18 minute, până boabele sunt fragede și cremoase, iar sosul s-a legat — zdrobește câteva de peretele oalei ca să-l îngroși. Adaugă cea mai mare parte din mărarul tocat la final. Servește cald, presărat cu restul de mărar — un fel vechi, țărănesc, care satură cu pâine alături.',
      en:'If using dried fava beans, soak them overnight and peel off the tough skins; fresh or frozen shelled beans need no soaking. Warm the oil in a pot and cook the chopped onion over medium heat for 6 minutes, until soft, then add the sliced garlic for 30 seconds. Stir in the tomato passata and cook for 2 minutes, then add the fava beans with enough water to just cover and a good pinch of salt. Simmer gently for about 18 minutes, until the beans are tender and creamy and the sauce has thickened — mash a few against the pot to bind it. Stir in most of the chopped dill at the end. Serve warm, scattered with the rest of the dill, an old country dish that eats like a meal with bread.',
      es:'Si usas habas secas, remójalas toda la noche y quítales la piel dura; las frescas o congeladas desgranadas no necesitan remojo. Calienta el aceite en una olla y sofríe la cebolla picada a fuego medio 6 minutos, hasta que ablande, luego añade el ajo en láminas 30 segundos. Incorpora el tomate triturado y cocina 2 minutos, luego añade las habas con agua justa para cubrirlas y una buena pizca de sal. Cuece suave unos 18 minutos, hasta que las habas estén tiernas y cremosas y la salsa haya espesado —aplasta unas contra la olla para ligarla—. Agrega casi todo el eneldo picado al final. Sirve caliente, espolvoreado con el resto del eneldo, un plato campesino antiguo que llena con pan al lado.',
      fr:'Si vous utilisez des fèves sèches, faites-les tremper une nuit et retirez les peaux dures ; les fèves fraîches ou surgelées écossées n’ont pas besoin de trempage. Chauffez l’huile dans une casserole et faites revenir l’oignon haché à feu moyen 6 minutes, jusqu’à ce qu’il soit tendre, puis ajoutez l’ail émincé 30 secondes. Ajoutez les tomates passées et poursuivez 2 minutes, puis ajoutez les fèves avec juste assez d’eau pour les couvrir et une bonne pincée de sel. Laissez mijoter doucement environ 18 minutes, jusqu’à ce que les fèves soient tendres et crémeuses et la sauce épaissie — écrasez-en quelques-unes contre la casserole pour lier. Incorporez la majeure partie de l’aneth haché à la fin. Servez chaud, parsemé du reste d’aneth, un vieux plat paysan qui rassasie avec du pain.',
      de:'Bei getrockneten dicken Bohnen diese über Nacht einweichen und die zähen Häute abziehen; frische oder tiefgekühlte, ausgelöste Bohnen müssen nicht eingeweicht werden. Das Öl in einem Topf erwärmen und die gehackte Zwiebel bei mittlerer Hitze 6 Minuten weich dünsten, dann den geschnittenen Knoblauch 30 Sekunden zugeben. Passierte Tomaten einrühren und 2 Minuten kochen, dann die Bohnen mit gerade bedeckendem Wasser und einer guten Prise Salz zugeben. Etwa 18 Minuten sanft köcheln, bis die Bohnen weich und cremig sind und die Sauce gebunden ist — einige an der Topfwand zerdrücken, um sie zu binden. Den größten Teil des gehackten Dills am Ende einrühren. Warm servieren, mit dem restlichen Dill bestreut — ein altes Bauerngericht, das mit Brot sättigt.',
      pt:'Se usar favas secas, demolhe-as de um dia para o outro e retire as peles duras; frescas ou congeladas descascadas não precisam de demolha. Aqueça o óleo numa panela e refogue a cebola picada em lume médio 6 minutos, até amolecer, depois junte o alho laminado 30 segundos. Junte o tomate passata e cozinhe 2 minutos, depois adicione as favas com água apenas a cobrir e uma boa pitada de sal. Cozinhe em lume brando cerca de 18 minutos, até as favas ficarem macias e cremosas e o molho engrossar — esmague algumas contra a panela para ligar. Junte quase todo o endro picado no fim. Sirva quente, polvilhado com o resto do endro, um prato camponês antigo que enche com pão ao lado.',
      ru:'Если используете сушёные бобы, замочите их на ночь и снимите жёсткую кожицу; свежие или замороженные очищенные бобы замачивать не нужно. Разогрейте масло в кастрюле и обжарьте нарезанный лук на среднем огне 6 минут до мягкости, затем добавьте нарезанный чеснок на 30 секунд. Вмешайте протёртые томаты и готовьте 2 минуты, затем добавьте бобы с водой, чтобы едва покрыть, и хорошую щепотку соли. Тушите мягко около 18 минут, пока бобы не станут нежными и кремовыми, а соус не загустеет — несколько раздавите о стенку кастрюли, чтобы связать. Большую часть рубленого укропа вмешайте в конце. Подавайте тёплым, посыпав оставшимся укропом, — старое деревенское блюдо, которое насыщает с хлебом.',
      ar:'إن استخدمت الفول اليابس، انقعه ليلة كاملة وأزل القشور القاسية؛ أما الفول الطازج أو المجمّد المقشور فلا يحتاج نقعاً. سخّن الزيت في قدر وشوّح البصل المفروم على نار متوسطة 6 دقائق حتى يلين، ثم أضف الثوم المقطّع 30 ثانية. أضف الطماطم المهروسة واطهها دقيقتين، ثم أضف الفول مع ماء يكفي لتغطيته ورشة ملح جيدة. اطهه برفق نحو 18 دقيقة حتى يلين الفول ويصير كريمياً ويتماسك الصلصة — اهرس بعضه على جدار القدر ليتماسك. أضف معظم الشبت المفروم في النهاية. قدّمه دافئاً منثوراً ببقية الشبت — طبق ريفي قديم يشبع مع الخبز.',
      zh:'用干蚕豆要先泡一夜并剥去硬皮；新鲜或冷冻的去壳蚕豆无需浸泡。锅中热油，中火将切碎的洋葱煸软6分钟，再加蒜片炒30秒。加入番茄泥炒2分钟，再放入蚕豆，加水刚没过，撒一大撮盐。小火轻煮约18分钟，至豆软糯、酱汁收稠——把几颗压在锅壁上使汤汁更浓。临出锅拌入大部分切碎的莳萝。趁热食用，撒上剩下的莳萝——一道古老的乡间菜，配面包很顶饱。',
      ja:'乾燥そら豆を使う場合は一晩浸して固い皮をむく。生や冷凍のさやから出した豆は浸水不要。鍋に油を温め、みじん切りの玉ねぎを中火で6分やわらかくし、薄切りのにんにくを30秒加える。トマトピューレを加えて2分炒め、そら豆をひたひたの水と塩ひとつまみとともに入れる。約18分やさしく煮て、豆が柔らかくクリーミーになりソースがまとまるまで——数粒を鍋肌でつぶしてとろみをつける。刻んだディルの大半を最後に加える。残りのディルを散らし、温かいうちに供する——パンを添えれば一食になる素朴な田舎料理。',
      hi:'सूखे बाकला इस्तेमाल करें तो रातभर भिगोकर सख्त छिलके उतार दें; ताज़े या जमे छिले बाकला को भिगोने की ज़रूरत नहीं। बर्तन में तेल गरम करें और कटा प्याज़ मध्यम आँच पर 6 मिनट नरम होने तक भूनें, फिर कटा लहसुन 30 सेकंड डालें। टमाटर प्यूरी डालकर 2 मिनट पकाएँ, फिर बाकला डालें, बस डूबने भर पानी और एक अच्छी चुटकी नमक के साथ। धीमी आँच पर लगभग 18 मिनट पकाएँ जब तक बाकला नरम-मलाईदार और सॉस गाढ़ी हो — कुछ दानों को बर्तन की दीवार पर मसलकर गाढ़ा करें। अधिकांश कटा डिल अंत में मिलाएँ। गरम, बचा डिल छिड़ककर परोसें — एक पुराना देहाती व्यंजन जो ब्रेड के साथ पेट भर देता है।',
      tr:'Kuru bakla kullanıyorsanız gece boyu ıslatıp sert kabuklarını soyun; taze ya da donmuş, kabuğu çıkarılmış bakla ıslatma istemez. Tencerede yağı ısıtın ve doğranmış soğanı orta ateşte 6 dakika yumuşayana dek kavurun, sonra dilimlenmiş sarımsağı 30 saniye ekleyin. Domates püresini ekleyip 2 dakika pişirin, sonra baklayı üzerini ancak örtecek suyla ve iyi bir tutam tuzla ekleyin. Kısık ateşte yaklaşık 18 dakika, bakla yumuşayıp kremamsı olana ve sos koyulaşana dek pişirin — birkaçını tencere kenarında ezerek bağlayın. Kıyılmış dereotunun çoğunu sonda ekleyin. Kalan dereotunu serpip sıcak servis edin — ekmekle doyuran eski bir köy yemeği.',
      it:'Se usi fave secche, mettile in ammollo una notte e togli le bucce dure; le fave fresche o surgelate sgusciate non vanno ammollate. Scalda l’olio in una pentola e fai rosolare la cipolla tritata a fuoco medio 6 minuti, finché è morbida, poi aggiungi l’aglio a fette per 30 secondi. Unisci la passata e cuoci 2 minuti, poi aggiungi le fave con acqua giusto a coprire e una buona presa di sale. Fai sobbollire dolcemente circa 18 minuti, finché le fave sono tenere e cremose e il sugo si è addensato — schiacciane qualcuna contro la pentola per legare. Unisci gran parte dell’aneto tritato alla fine. Servi caldo, cosparso con l’aneto rimasto, un vecchio piatto contadino che sazia con il pane.',
      ko:'말린 잠두를 쓰면 하룻밤 불려 질긴 껍질을 벗긴다. 생것이나 냉동 깐 잠두는 불릴 필요가 없다. 냄비에 기름을 데우고 다진 양파를 중불에서 6분 부드럽게 한 뒤 저민 마늘을 30초 넣는다. 토마토 퓌레를 넣어 2분 볶고, 잠두를 겨우 잠길 만큼의 물과 소금 넉넉히 한 꼬집과 함께 넣는다. 약불에서 약 18분, 콩이 부드럽고 크리미해지며 소스가 걸쭉해질 때까지 끓인다 — 몇 알을 냄비 벽에 으깨 농도를 낸다. 다진 딜의 대부분을 마지막에 넣는다. 남은 딜을 뿌려 따뜻하게 낸다 — 빵을 곁들이면 한 끼가 되는 오래된 시골 요리다.' } },

  { id:'budget_030', name:NAMES.omleta, servings:2, prep:10, cook:15, costRon:3, nut:{cal:360,prot:16,carb:26,fat:22,fib:3}, tags:['budget','vegetarian','quick'],
    ing:[ {q:4,n:I.eggs}, {q:300,u:'g',n:I.potatoes}, {q:1,n:I.onion}, {q:3,u:'tbsp',n:I.oil}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Curăță cartofii și taie-i cubulețe mici, ca să se gătească repede. Încălzește uleiul într-o tigaie antiaderentă și prăjește cartofii cu ceapa tocată la foc mediu circa 10 minute, întorcând din când în când, până sunt aurii și fragezi. Bate ouăle cu un praf bun de sare și cu cea mai mare parte din pătrunjelul tocat. Întinde cartofii într-un strat uniform, toarnă ouăle deasupra și dă focul mic, apoi lasă să se lege neatins 3 minute, până baza e aurie. Împăturește-o sau întoarce-o ca să se gătească și deasupra încă 2 minute, până e legată, dar încă moale. Răstoarnă pe o farfurie, presară restul de pătrunjel și servește cald cu pâine sau o salată de roșii.',
      en:'Peel the potatoes and cut them into small cubes so they cook quickly. Warm the oil in a non-stick pan and fry the potatoes with the chopped onion over medium heat for about 10 minutes, turning now and then, until golden and tender. Beat the eggs with a good pinch of salt and most of the chopped parsley. Spread the potatoes into an even layer, pour the eggs over and lower the heat, then let it set undisturbed for 3 minutes, until the base is golden. Fold it over or flip it to cook the top for another 2 minutes, until just set but still moist. Slide onto a plate, scatter with the rest of the parsley, and serve hot with bread or a tomato salad.',
      es:'Pela las patatas y córtalas en cubos pequeños para que se hagan rápido. Calienta el aceite en una sartén antiadherente y fríe las patatas con la cebolla picada a fuego medio unos 10 minutos, dándoles la vuelta de vez en cuando, hasta que estén doradas y tiernas. Bate los huevos con una buena pizca de sal y casi todo el perejil picado. Extiende las patatas en una capa uniforme, vierte los huevos por encima y baja el fuego, luego deja que cuaje sin tocar 3 minutos, hasta que la base esté dorada. Dóblala o dale la vuelta para cocinar la parte de arriba otros 2 minutos, hasta que cuaje pero siga jugosa. Deslízala a un plato, espolvorea el resto del perejil y sirve caliente con pan o una ensalada de tomate.',
      fr:'Épluchez les pommes de terre et coupez-les en petits dés pour qu’elles cuisent vite. Chauffez l’huile dans une poêle antiadhésive et faites revenir les pommes de terre avec l’oignon haché à feu moyen environ 10 minutes, en retournant de temps en temps, jusqu’à ce qu’elles soient dorées et tendres. Battez les œufs avec une bonne pincée de sel et la majeure partie du persil haché. Étalez les pommes de terre en une couche régulière, versez les œufs dessus et baissez le feu, puis laissez prendre sans y toucher 3 minutes, jusqu’à ce que la base soit dorée. Pliez-la ou retournez-la pour cuire le dessus encore 2 minutes, jusqu’à ce qu’elle soit prise mais encore moelleuse. Faites-la glisser sur une assiette, parsemez du reste de persil et servez chaud avec du pain ou une salade de tomates.',
      de:'Die Kartoffeln schälen und in kleine Würfel schneiden, damit sie schnell garen. Das Öl in einer beschichteten Pfanne erwärmen und die Kartoffeln mit der gehackten Zwiebel bei mittlerer Hitze etwa 10 Minuten braten, ab und zu wenden, bis sie goldbraun und weich sind. Die Eier mit einer guten Prise Salz und dem größten Teil der gehackten Petersilie verquirlen. Die Kartoffeln in einer gleichmäßigen Schicht verteilen, die Eier darüber gießen und die Hitze reduzieren, dann 3 Minuten unberührt stocken lassen, bis der Boden goldbraun ist. Zusammenklappen oder wenden, um die Oberseite weitere 2 Minuten zu garen, bis sie gerade gestockt, aber noch saftig ist. Auf einen Teller gleiten lassen, mit der restlichen Petersilie bestreuen und heiß mit Brot oder Tomatensalat servieren.',
      pt:'Descasque as batatas e corte-as em cubos pequenos para cozerem depressa. Aqueça o óleo numa frigideira antiaderente e frite as batatas com a cebola picada em lume médio cerca de 10 minutos, virando de vez em quando, até ficarem douradas e macias. Bata os ovos com uma boa pitada de sal e quase toda a salsa picada. Espalhe as batatas numa camada uniforme, deite os ovos por cima e baixe o lume, depois deixe presar sem mexer 3 minutos, até a base ficar dourada. Dobre-a ou vire-a para cozer o topo mais 2 minutos, até presar mas ainda suculenta. Deslize para um prato, polvilhe com o resto da salsa e sirva quente com pão ou uma salada de tomate.',
      ru:'Очистите картофель и нарежьте мелкими кубиками, чтобы он быстро приготовился. Разогрейте масло в сковороде с антипригарным покрытием и обжарьте картофель с нарезанным луком на среднем огне около 10 минут, время от времени переворачивая, до золотистости и мягкости. Взбейте яйца с хорошей щепоткой соли и большей частью рубленой петрушки. Разровняйте картофель ровным слоем, залейте яйцами и убавьте огонь, затем дайте схватиться, не трогая, 3 минуты, пока низ не станет золотистым. Сложите пополам или переверните, чтобы приготовить верх ещё 2 минуты, до готовности, но с сочностью. Сдвиньте на тарелку, посыпьте оставшейся петрушкой и подавайте горячим с хлебом или салатом из помидоров.',
      ar:'قشّر البطاطس وقطّعها مكعبات صغيرة كي تنضج بسرعة. سخّن الزيت في مقلاة غير لاصقة واقلِ البطاطس مع البصل المفروم على نار متوسطة نحو 10 دقائق مع التقليب بين الحين والآخر حتى تذهب وتلين. اخفق البيض مع رشة ملح جيدة ومعظم البقدونس المفروم. افرد البطاطس بطبقة متساوية، اسكب البيض فوقها واخفض النار، ثم اتركها تتماسك دون تحريك 3 دقائق حتى يذهب القاع. اطوها أو اقلبها لتنضج من الأعلى دقيقتين إضافيتين حتى تتماسك مع بقائها طرية. أزلقها إلى طبق، انثر بقية البقدونس وقدّمها ساخنة مع الخبز أو سلطة الطماطم.',
      zh:'土豆去皮，切成小丁，好熟得快。不粘锅中热油，中火将土豆和切碎的洋葱煎约10分钟，不时翻动，至金黄软嫩。把鸡蛋打散，加一大撮盐和大部分切碎的欧芹。将土豆铺成均匀一层，倒入蛋液，转小火，静置3分钟不动，至底面金黄。对折或翻面再煎顶面约2分钟，至凝固但仍湿润。滑入盘中，撒上剩下的欧芹，趁热配面包或番茄沙拉。',
      ja:'じゃがいもは皮をむいて小さな角切りにし、火が早く通るようにする。フッ素樹脂加工のフライパンに油を温め、じゃがいもとみじん切りの玉ねぎを中火で約10分、時々返しながら、色づいて柔らかくなるまで焼く。卵を塩ひとつまみと刻んだパセリの大半とともに溶く。じゃがいもを均一に広げ、卵を流し入れて火を弱め、触らずに3分、底が色づくまで固める。半分に折るか裏返して上面をさらに2分、固まりつつしっとりを残して火を通す。皿に滑らせ、残りのパセリを散らし、パンやトマトサラダを添えて熱いうちに供する。',
      hi:'आलू छीलकर छोटे टुकड़ों में काटें ताकि जल्दी पकें। नॉन-स्टिक पैन में तेल गरम करें और आलू को कटे प्याज़ के साथ मध्यम आँच पर लगभग 10 मिनट, बीच-बीच में पलटते हुए, सुनहरा और नरम होने तक तलें। अंडे को अच्छी चुटकी नमक और अधिकांश कटे धनिये के साथ फेंटें। आलू को एक समान परत में फैलाएँ, ऊपर अंडे डालें और आँच कम करें, फिर बिना छेड़े 3 मिनट जमने दें जब तक तली सुनहरी हो। इसे मोड़ें या पलटें ताकि ऊपर की तरफ 2 मिनट और पके, जब तक जम जाए पर नम रहे। प्लेट में सरकाएँ, बचा धनिया छिड़कें और गरम, ब्रेड या टमाटर सलाद के साथ परोसें।',
      tr:'Patatesleri soyup küçük küpler hâlinde doğrayın ki çabuk pişsin. Yapışmaz bir tavada yağı ısıtın ve patatesleri doğranmış soğanla orta ateşte yaklaşık 10 dakika, ara sıra çevirerek, kızarıp yumuşayana dek pişirin. Yumurtaları iyi bir tutam tuz ve kıyılmış maydanozun çoğuyla çırpın. Patatesleri eşit bir tabaka hâlinde yayın, yumurtaları üzerine dökün ve ateşi kısın, sonra dokunmadan 3 dakika, alt yüzü kızarana dek pişirin. Katlayın ya da çevirip üst yüzünü 2 dakika daha, tutana ama nemli kalana dek pişirin. Bir tabağa kaydırın, kalan maydanozu serpin ve ekmek ya da domates salatasıyla sıcak servis edin.',
      it:'Sbuccia le patate e tagliale a cubetti piccoli così cuociono in fretta. Scalda l’olio in una padella antiaderente e rosola le patate con la cipolla tritata a fuoco medio per circa 10 minuti, girando ogni tanto, finché sono dorate e tenere. Sbatti le uova con una buona presa di sale e gran parte del prezzemolo tritato. Distribuisci le patate in uno strato uniforme, versa le uova sopra e abbassa la fiamma, poi lascia rapprendere senza toccare per 3 minuti, finché la base è dorata. Piegala o giravolta per cuocere la superficie altri 2 minuti, finché è appena rappresa ma ancora morbida. Falla scivolare su un piatto, cospargi con il prezzemolo rimasto e servi calda con pane o un’insalata di pomodori.',
      ko:'감자는 껍질을 벗겨 빨리 익도록 작게 깍둑 썬다. 코팅 팬에 기름을 데우고 감자와 다진 양파를 중불에서 약 10분간 이따금 뒤집으며 노릇하고 부드러워질 때까지 볶는다. 달걀을 소금 넉넉히 한 꼬집과 다진 파슬리 대부분과 함께 푼다. 감자를 고르게 편 뒤 달걀을 붓고 불을 줄여, 건드리지 말고 3분간 바닥이 노릇해질 때까지 굳힌다. 반으로 접거나 뒤집어 윗면을 2분 더, 막 굳되 촉촉함이 남을 때까지 익힌다. 접시에 미끄러뜨려 남은 파슬리를 뿌리고, 빵이나 토마토 샐러드를 곁들여 뜨겁게 낸다.' } },

  { id:'budget_031', name:NAMES.paste, servings:2, prep:5, cook:15, costRon:3, nut:{cal:420,prot:12,carb:72,fat:10,fib:6}, tags:['budget','vegan','quick'],
    ing:[ {q:250,u:'g',n:I.spaghetti}, {q:250,u:'g',n:I.passata}, {q:3,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Pune o oală mare cu apă sărată la fiert și fierbe spaghetele până sunt al dente, după timpul de pe pachet. Între timp, încălzește uleiul într-o tigaie largă la foc mic și călește usturoiul feliat subțire circa un minut, doar cât devine aromat și auriu-pal — nu-l lăsa să se rumenească, că amărăște sosul. Toarnă roșiile pasate cu un praf de sare, dă focul mai mare și fierbe 8 minute, până se închide la culoare și se îngroașă puțin. Scurge pastele, păstrând o cană din apa lor cu amidon, apoi răstoarnă-le direct în sos cu un strop din acea apă, ca sosul să îmbrace fiecare fir. Adaugă cea mai mare parte din pătrunjelul tocat, luat de pe foc. Servește imediat, presărat cu restul de pătrunjel.',
      en:'Bring a large pot of salted water to the boil and cook the spaghetti until just al dente, following the packet time. Meanwhile, warm the oil in a wide pan over low heat and cook the thinly sliced garlic for about a minute, just until fragrant and pale gold — don’t let it brown or the sauce turns bitter. Pour in the tomato passata with a pinch of salt, raise the heat and simmer for 8 minutes, until it darkens and thickens slightly. Drain the pasta, saving a cup of the starchy water, then toss the pasta straight into the sauce with a splash of that water so it clings to every strand. Stir in most of the chopped parsley off the heat. Serve at once, scattered with the rest of the parsley.',
      es:'Pon a hervir una olla grande de agua con sal y cuece los espaguetis hasta que estén al dente, según el tiempo del paquete. Mientras, calienta el aceite en una sartén amplia a fuego bajo y cocina el ajo en láminas finas cerca de un minuto, solo hasta que perfume y esté dorado pálido — no dejes que se dore o la salsa amarga. Vierte el tomate triturado con una pizca de sal, sube el fuego y cuece 8 minutos, hasta que oscurezca y espese un poco. Escurre la pasta, reservando una taza de su agua con almidón, y échala directa a la salsa con un chorrito de esa agua para que se adhiera a cada hebra. Agrega casi todo el perejil picado fuera del fuego. Sirve enseguida, espolvoreado con el resto del perejil.',
      fr:'Portez à ébullition une grande casserole d’eau salée et faites cuire les spaghettis al dente, selon le temps indiqué. Pendant ce temps, chauffez l’huile dans une grande poêle à feu doux et faites revenir l’ail émincé une minute environ, juste jusqu’à ce qu’il embaume et blondisse — sans le laisser dorer, sinon la sauce devient amère. Versez les tomates passées avec une pincée de sel, montez le feu et laissez mijoter 8 minutes, jusqu’à ce qu’elles foncent et épaississent un peu. Égouttez les pâtes en réservant une tasse de leur eau amidonnée, puis versez-les directement dans la sauce avec un peu de cette eau pour qu’elle enrobe chaque brin. Incorporez la majeure partie du persil haché hors du feu. Servez aussitôt, parsemé du reste de persil.',
      de:'Einen großen Topf mit Salzwasser zum Kochen bringen und die Spaghetti nach Packungsangabe al dente garen. Währenddessen das Öl in einer weiten Pfanne bei schwacher Hitze erwärmen und den dünn geschnittenen Knoblauch etwa eine Minute anschwitzen, nur bis er duftet und blassgolden ist — nicht bräunen lassen, sonst wird die Sauce bitter. Die passierten Tomaten mit einer Prise Salz angießen, die Hitze erhöhen und 8 Minuten köcheln, bis sie nachdunkeln und leicht eindicken. Die Pasta abgießen, dabei eine Tasse des stärkehaltigen Wassers auffangen, dann direkt in die Sauce geben, mit einem Schuss dieses Wassers, damit sie jeden Strang umhüllt. Den größten Teil der gehackten Petersilie vom Herd genommen unterrühren. Sofort servieren, mit der restlichen Petersilie bestreut.',
      pt:'Leve ao lume uma panela grande com água e sal e cozinhe o esparguete al dente, segundo o tempo do pacote. Entretanto, aqueça o óleo numa frigideira larga em lume brando e refogue o alho em lâminas finas cerca de um minuto, só até perfumar e ficar dourado pálido — não deixe alourar, senão o molho amarga. Deite o tomate passata com uma pitada de sal, aumente o lume e cozinhe 8 minutos, até escurecer e engrossar um pouco. Escorra a massa, guardando uma chávena da água com amido, e junte-a diretamente ao molho com um pouco dessa água para envolver cada fio. Junte quase toda a salsa picada fora do lume. Sirva de imediato, polvilhado com o resto da salsa.',
      ru:'Вскипятите большую кастрюлю подсоленной воды и отварите спагетти до состояния аль денте по времени на упаковке. Тем временем разогрейте масло в широкой сковороде на слабом огне и обжарьте тонко нарезанный чеснок около минуты, только до аромата и бледно-золотистого цвета — не давайте ему подрумяниться, иначе соус станет горьким. Влейте протёртые томаты со щепоткой соли, прибавьте огонь и тушите 8 минут, пока они не потемнеют и слегка не загустеют. Откиньте пасту, сохранив чашку крахмалистой воды, и переложите её прямо в соус с ложкой этой воды, чтобы он обволок каждую нить. Вмешайте большую часть рубленой петрушки, сняв с огня. Подавайте сразу, посыпав оставшейся петрушкой.',
      ar:'ضع قدراً كبيراً من الماء المملّح على النار واسلق السباغيتي حتى تصبح «آل دينتي» حسب زمن العبوة. في هذه الأثناء سخّن الزيت في مقلاة واسعة على نار هادئة وشوّح الثوم المقطّع رفيعاً نحو دقيقة، فقط حتى يفوح ويكتسب لوناً ذهبياً باهتاً — دون أن يحمرّ وإلا صارت الصلصة مرّة. أضف الطماطم المهروسة مع رشة ملح، ارفع النار واطهها 8 دقائق حتى تغمق وتثخن قليلاً. صفِّ المعكرونة محتفظاً بكوب من مائها النشوي، ثم أضفها مباشرة إلى الصلصة مع رشة من ذلك الماء كي تغلّف كل خيط. أضف معظم البقدونس المفروم بعد رفعها عن النار. قدّمها فوراً منثوراً عليها بقية البقدونس.',
      zh:'烧一大锅盐水，按包装时间把意面煮到弹牙（al dente）。同时宽口锅中小火热油，将切薄的蒜片炒约1分钟，只需出香、呈浅金色——别炒褐，否则酱会发苦。倒入番茄泥加一撮盐，转大火煮8分钟，至颜色变深、略稠。面捞出沥干，留一杯煮面的淀粉水，直接倒入酱汁中，加一点面汤让酱裹住每根面。离火拌入大部分切碎的欧芹。立即食用，撒上剩下的欧芹。',
      ja:'大きめの鍋に塩湯を沸かし、袋の表示時間どおりスパゲッティをアルデンテに茹でる。その間に広めのフライパンに弱火で油を温め、薄切りのにんにくを約1分、香りが立って淡い金色になるまで炒める——焦がすとソースが苦くなるので色づけない。トマトピューレと塩ひとつまみを加え、火を強めて8分、色が濃くなり少しとろむまで煮る。パスタの湯を切り、茹で汁を1カップ取っておき、ソースに直接入れてその湯を少し加え、麺一本一本にからめる。火を止めて刻んだパセリの大半を混ぜる。すぐに、残りのパセリを散らして供する。',
      hi:'एक बड़े बर्तन में नमकीन पानी उबालें और पैकेट के समय के अनुसार स्पगेटी को अल-डेंटे तक पकाएँ। इस बीच चौड़े पैन में धीमी आँच पर तेल गरम करें और पतले कटे लहसुन को लगभग एक मिनट, बस खुशबू और हल्के सुनहरे रंग तक भूनें — भूरा न होने दें वरना सॉस कड़वी हो जाती है। टमाटर प्यूरी और एक चुटकी नमक डालें, आँच तेज़ करें और 8 मिनट पकाएँ जब तक रंग गहरा और थोड़ा गाढ़ा हो। पास्ता छानें, एक कप स्टार्च वाला पानी बचाकर, फिर सीधे सॉस में डालें और उस पानी का थोड़ा छींटा दें ताकि हर लच्छे पर लिपट जाए। आँच से उतारकर अधिकांश कटा धनिया मिलाएँ। तुरंत, बचा धनिया छिड़ककर परोसें।',
      tr:'Büyük bir tencerede tuzlu suyu kaynatın ve spagettiyi paket süresine göre diri (al dente) haşlayın. Bu sırada geniş bir tavada kısık ateşte yağı ısıtın ve ince dilimlenmiş sarımsağı yaklaşık bir dakika, sadece kokusu çıkıp açık altın rengi alana dek soteleyin — kızarmasına izin vermeyin, yoksa sos acılaşır. Domates püresini bir tutam tuzla ekleyin, ateşi yükseltip 8 dakika, koyulaşıp biraz kıvam alana dek pişirin. Makarnayı süzün, bir fincan nişastalı suyunu ayırın, sonra doğrudan sosa alıp o sudan biraz ekleyin ki her teli sarsın. Ocaktan alıp kıyılmış maydanozun çoğunu karıştırın. Hemen, kalan maydanozu serperek servis edin.',
      it:'Porta a bollore una pentola capiente di acqua salata e cuoci gli spaghetti al dente, seguendo il tempo della confezione. Intanto scalda l’olio in una padella ampia a fuoco basso e rosola l’aglio a fettine sottili per circa un minuto, solo finché profuma ed è dorato pallido — non farlo scurire, o il sugo diventa amaro. Versa la passata con un pizzico di sale, alza la fiamma e cuoci 8 minuti, finché scurisce e si addensa un po’. Scola la pasta tenendo da parte una tazza della sua acqua amidacea, poi versala direttamente nel sugo con un goccio di quell’acqua così avvolge ogni filo. Fuori dal fuoco unisci gran parte del prezzemolo tritato. Servi subito, cosparso con il prezzemolo rimasto.',
      ko:'큰 냄비에 소금물을 끓이고 봉지 표시 시간에 맞춰 스파게티를 알덴테로 삶는다. 그동안 넓은 팬에 약불로 기름을 데우고 얇게 썬 마늘을 약 1분, 향이 나고 옅은 황금색이 될 때까지만 볶는다 — 갈색이 되면 소스가 써지니 태우지 않는다. 토마토 퓌레와 소금 한 꼬집을 넣고 불을 올려 8분, 색이 진해지고 약간 걸쭉해질 때까지 끓인다. 파스타를 건지되 전분물 한 컵을 남기고, 소스에 바로 넣어 그 물을 조금 더해 면 한 가닥마다 감싸이게 버무린다. 불을 끄고 다진 파슬리의 대부분을 섞는다. 남은 파슬리를 뿌려 곧바로 낸다.' } },

  { id:'budget_032', name:NAMES.aripioare, servings:2, prep:10, cook:20, costRon:6, nut:{cal:420,prot:34,carb:4,fat:30,fib:1}, tags:['budget','quick','high-protein'],
    ing:[ {q:600,u:'g',n:I.chickenWings}, {q:4,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,u:'tsp',n:I.paprika}, {q:2,u:'tbsp',n:I.parsley}, {n:I.salt} ],
    steps:{
      ro:'Usucă aripioarele cu un prosop de hârtie și condimentează-le peste tot cu sare și boia — pielea uscată e cea care se face crocantă. Încălzește uleiul într-o tigaie mare la foc mediu-mare și așază aripioarele într-un singur strat, cu pielea în jos. Prăjește-le circa 8 minute fără să le miști, până sunt bine rumenite, apoi întoarce-le și mai gătește cealaltă parte 6 minute. Dă focul mic, adaugă usturoiul zdrobit și amestecă 2 minute, până e aromat și auriu, dar nu ars. Taie într-o aripioară mai groasă ca să vezi dacă zeama iese limpede și mai lasă-le câteva minute dacă e nevoie. Presară pătrunjel tocat și servește fierbinte, cu pâine și murături sau o salată simplă.',
      en:'Pat the chicken wings dry and season them all over with salt and the paprika — dry skin is what turns crisp. Warm the oil in a large pan over medium-high heat and lay the wings in a single layer, skin-side down. Fry them for about 8 minutes without moving them, until deep golden, then turn and cook the other side for 6 minutes more. Lower the heat, add the crushed garlic and toss for 2 minutes, until fragrant and golden but not burnt. Cut into a thick wing to check the juices run clear, and give them a few more minutes if needed. Scatter with chopped parsley and serve hot with bread and a pickle or a simple salad.',
      es:'Seca las alitas con papel de cocina y sazónalas por todas partes con sal y el pimentón — la piel seca es la que se vuelve crujiente. Calienta el aceite en una sartén grande a fuego medio-alto y coloca las alitas en una sola capa, con la piel hacia abajo. Fríelas unos 8 minutos sin moverlas, hasta que estén bien doradas, luego dales la vuelta y cocina el otro lado 6 minutos. Baja el fuego, añade el ajo machacado y remueve 2 minutos, hasta que perfume y se dore sin quemarse. Corta una alita gruesa para ver si los jugos salen claros, y dales unos minutos más si hace falta. Espolvorea perejil picado y sirve caliente con pan y encurtidos o una ensalada sencilla.',
      fr:'Séchez les ailes de poulet avec du papier absorbant et assaisonnez-les partout de sel et de paprika — c’est la peau sèche qui devient croustillante. Chauffez l’huile dans une grande poêle à feu moyen-vif et disposez les ailes en une seule couche, côté peau vers le bas. Faites-les frire environ 8 minutes sans les bouger, jusqu’à ce qu’elles soient bien dorées, puis retournez-les et cuisez l’autre face 6 minutes. Baissez le feu, ajoutez l’ail écrasé et remuez 2 minutes, jusqu’à ce qu’il embaume et dore sans brûler. Coupez une aile épaisse pour vérifier que le jus est clair, et prolongez de quelques minutes si besoin. Parsemez de persil haché et servez chaud avec du pain et un cornichon ou une salade simple.',
      de:'Die Hähnchenflügel trockentupfen und rundum mit Salz und Paprikapulver würzen — trockene Haut wird knusprig. Das Öl in einer großen Pfanne bei mittelhoher Hitze erwärmen und die Flügel in einer Schicht mit der Hautseite nach unten einlegen. Etwa 8 Minuten unbewegt braten, bis sie tief goldbraun sind, dann wenden und die andere Seite 6 Minuten garen. Die Hitze reduzieren, den zerdrückten Knoblauch zugeben und 2 Minuten schwenken, bis er duftet und goldgelb, aber nicht verbrannt ist. In einen dicken Flügel schneiden, um zu prüfen, ob der Saft klar austritt, und bei Bedarf ein paar Minuten länger garen. Mit gehackter Petersilie bestreuen und heiß mit Brot und einer sauren Gurke oder einem einfachen Salat servieren.',
      pt:'Seque as asas de frango com papel de cozinha e tempere-as por todos os lados com sal e o colorau — a pele seca é a que fica crocante. Aqueça o óleo numa frigideira grande em lume médio-alto e disponha as asas numa só camada, com a pele para baixo. Frite-as cerca de 8 minutos sem mexer, até ficarem bem douradas, depois vire e cozinhe o outro lado 6 minutos. Baixe o lume, junte o alho esmagado e mexa 2 minutos, até perfumar e alourar sem queimar. Corte uma asa mais grossa para ver se os sucos saem claros, e dê mais uns minutos se precisar. Polvilhe com salsa picada e sirva quente com pão e um picle ou uma salada simples.',
      ru:'Обсушите куриные крылышки бумажным полотенцем и приправьте со всех сторон солью и паприкой — именно сухая кожа становится хрустящей. Разогрейте масло в большой сковороде на среднесильном огне и выложите крылышки в один слой кожей вниз. Жарьте около 8 минут, не двигая, до насыщенного золотистого цвета, затем переверните и готовьте другую сторону ещё 6 минут. Убавьте огонь, добавьте раздавленный чеснок и помешивайте 2 минуты, до аромата и золотистости, но не до пригорания. Надрежьте крылышко потолще, чтобы проверить, что сок прозрачный, и при необходимости подержите ещё пару минут. Посыпьте рубленой петрушкой и подавайте горячими с хлебом и соленьями или простым салатом.',
      ar:'جفّف أجنحة الدجاج بمنشفة ورقية وتبّلها من كل الجهات بالملح والبابريكا — فالجلد الجاف هو ما يصير مقرمشاً. سخّن الزيت في مقلاة كبيرة على نار متوسطة-عالية ورتّب الأجنحة في طبقة واحدة، الجلد للأسفل. اقلها نحو 8 دقائق دون تحريك حتى تذهب جيداً، ثم اقلبها واطهُ الوجه الآخر 6 دقائق. اخفض النار، أضف الثوم المهروس وقلّب دقيقتين حتى يفوح ويذهب دون أن يحترق. اقطع جناحاً سميكاً للتأكد أن العصارة صافية، وأعطها دقائق إضافية إن لزم. انثر البقدونس المفروم وقدّمها ساخنة مع الخبز ومخلّل أو سلطة بسيطة.',
      zh:'用厨房纸把鸡翅擦干，两面都用盐和红椒粉腌匀——皮干才会煎脆。大锅中大火热油，把鸡翅皮朝下平铺一层。不翻动煎约8分钟，至深金黄，再翻面煎6分钟。转小火，加入压碎的蒜，翻炒2分钟，至出香金黄但不焦。切开一只较厚的鸡翅，看流出的汁是否清澈，需要的话再煎几分钟。撒上切碎的欧芹，趁热配面包和腌菜或一份简单沙拉。',
      ja:'手羽先をペーパーで水気を拭き、全体に塩とパプリカをふる——皮が乾いているほどパリッとする。大きめのフライパンに中火よりやや強めで油を温め、手羽先を皮目を下にして一段に並べる。動かさずに約8分、濃いきつね色になるまで焼き、返してもう片面を6分焼く。火を弱め、つぶしたにんにくを加えて2分、香りが立って色づくが焦げない程度に炒める。厚い手羽先に切り込みを入れ、透明な肉汁が出るか確かめ、必要ならもう数分焼く。刻んだパセリを散らし、パンとピクルスか簡単なサラダを添えて熱いうちに供する。',
      hi:'चिकन विंग्स को किचन पेपर से सुखाएँ और चारों ओर नमक व पेपरिका लगाएँ — सूखी त्वचा ही कुरकुरी होती है। बड़े पैन में मध्यम-तेज़ आँच पर तेल गरम करें और विंग्स को त्वचा नीचे की ओर एक परत में रखें। बिना हिलाए लगभग 8 मिनट, गहरे सुनहरे होने तक तलें, फिर पलटकर दूसरी तरफ 6 मिनट पकाएँ। आँच कम करें, कुचला लहसुन डालें और 2 मिनट चलाएँ, जब तक खुशबू और सुनहरापन आए पर जले नहीं। एक मोटी विंग काटकर देखें कि रस साफ निकल रहा है, ज़रूरत हो तो कुछ मिनट और पकाएँ। कटा धनिया छिड़कें और गरम, ब्रेड और अचार या एक सादे सलाद के साथ परोसें।',
      tr:'Tavuk kanatlarını kâğıt havluyla kurulayın ve her tarafını tuz ve toz biberle ovun — çıtırlaşan şey kuru deridir. Büyük bir tavada orta-yüksek ateşte yağı ısıtın ve kanatları derisi alta gelecek şekilde tek sıra dizin. Kımıldatmadan yaklaşık 8 dakika, koyu altın rengi alana dek kızartın, sonra çevirip diğer yüzü 6 dakika pişirin. Ateşi kısın, ezilmiş sarımsağı ekleyip 2 dakika, kokusu çıkıp yanmadan kızarana dek çevirin. Kalın bir kanadı kesip suyunun berrak aktığını kontrol edin, gerekirse birkaç dakika daha pişirin. Kıyılmış maydanoz serpip ekmek ve turşu ya da sade bir salatayla sıcak servis edin.',
      it:'Asciuga le ali di pollo con carta da cucina e condiscile ovunque con sale e paprica — è la pelle asciutta a diventare croccante. Scalda l’olio in una padella grande a fuoco medio-alto e disponi le ali in un solo strato, con la pelle in giù. Friggile per circa 8 minuti senza muoverle, finché sono ben dorate, poi girale e cuoci l’altro lato per 6 minuti. Abbassa la fiamma, aggiungi l’aglio schiacciato e salta per 2 minuti, finché profuma e dora senza bruciare. Taglia un’ala spessa per controllare che il succo esca chiaro, e dai qualche minuto in più se serve. Cospargi di prezzemolo tritato e servi caldo con pane e un sottaceto o un’insalata semplice.',
      ko:'닭 날개를 키친타월로 물기를 닦고 소금과 파프리카로 골고루 밑간한다 — 껍질이 마를수록 바삭해진다. 큰 팬에 중강불로 기름을 데우고 날개를 껍질이 아래로 오도록 한 겹으로 놓는다. 건드리지 말고 약 8분, 진한 황금색이 될 때까지 굽고 뒤집어 반대쪽을 6분 더 익힌다. 불을 줄이고 으깬 마늘을 넣어 2분, 향이 나고 노릇하되 타지 않게 볶는다. 두꺼운 날개를 잘라 육즙이 맑게 나오는지 확인하고 필요하면 몇 분 더 익힌다. 다진 파슬리를 뿌리고 빵과 피클, 또는 간단한 샐러드를 곁들여 뜨겁게 낸다.' } },

  { id:'budget_033', name:NAMES.dovleacCopt, servings:2, prep:10, cook:35, costRon:2, nut:{cal:200,prot:3,carb:44,fat:1,fib:5}, tags:['budget','vegan','family'],
    ing:[ {q:800,u:'g',n:I.pumpkin}, {q:3,u:'tbsp',n:I.sugar}, {q:1,u:'tsp',n:I.cinnamon}, {n:I.salt} ],
    steps:{
      ro:'Încinge cuptorul la 200°C. Taie dovleacul felii groase de vreo doi centimetri, scoate semințele și miezul ațos, dar lasă coaja — se înmoaie și ține feliile ușor de mânuit. Așază feliile pe o tavă cu hârtie de copt, presară zahărul, scorțișoara și un vârf mic de sare, care întărește dulceața. Coace circa 35 de minute, întorcând o dată, până miezul e complet moale, iar marginile s-au caramelizat. Dovleacul se aburește în propria umezeală, așa că nu e nevoie de ulei. Servește cald, ca desert sau gustare, simplu sau cu o lingură de iaurt, scoțând miezul dulce din coajă cu lingurița.',
      en:'Heat the oven to 200°C. Cut the pumpkin into thick slices about two centimetres wide, scoop out the seeds and stringy centre, but leave the skin on — it softens and makes the slices easy to handle. Lay the slices on a lined tray, sprinkle with the sugar, the cinnamon and a tiny pinch of salt to sharpen the sweetness. Bake for about 35 minutes, turning once, until the flesh is completely soft and the edges have caramelised. The pumpkin steams in its own moisture, so no oil is needed. Serve warm as a dessert or snack, on its own or with a spoon of yogurt, scooping the sweet flesh from the skin.',
      es:'Calienta el horno a 200°C. Corta la calabaza en rodajas gruesas de unos dos centímetros, retira las semillas y el centro fibroso, pero deja la piel — se ablanda y hace las rodajas fáciles de manejar. Coloca las rodajas en una bandeja con papel, espolvorea el azúcar, la canela y una pizca mínima de sal para realzar el dulzor. Hornea unos 35 minutos, dándoles la vuelta una vez, hasta que la pulpa esté completamente blanda y los bordes caramelizados. La calabaza se cuece al vapor con su propia humedad, así que no hace falta aceite. Sirve caliente como postre o tentempié, sola o con una cucharada de yogur, sacando la pulpa dulce de la piel con la cuchara.',
      fr:'Préchauffez le four à 200°C. Coupez le potiron en tranches épaisses d’environ deux centimètres, retirez les graines et le centre filandreux, mais gardez la peau — elle s’attendrit et rend les tranches faciles à manier. Disposez les tranches sur une plaque chemisée, saupoudrez du sucre, de la cannelle et d’une toute petite pincée de sel pour aviver le sucré. Enfournez environ 35 minutes, en retournant une fois, jusqu’à ce que la chair soit tout à fait tendre et les bords caramélisés. Le potiron cuit à la vapeur de sa propre humidité, donc pas besoin d’huile. Servez chaud en dessert ou en en-cas, tel quel ou avec une cuillerée de yaourt, en prélevant la chair sucrée de la peau à la cuillère.',
      de:'Den Backofen auf 200°C vorheizen. Den Kürbis in etwa zwei Zentimeter dicke Scheiben schneiden, Kerne und faseriges Inneres entfernen, die Schale aber dranlassen — sie wird weich und macht die Scheiben leicht handhabbar. Die Scheiben auf ein ausgelegtes Blech legen, mit dem Zucker, dem Zimt und einer winzigen Prise Salz bestreuen, das die Süße hervorhebt. Etwa 35 Minuten backen, einmal wenden, bis das Fruchtfleisch ganz weich und die Ränder karamellisiert sind. Der Kürbis dämpft in der eigenen Feuchtigkeit, daher braucht es kein Öl. Warm als Dessert oder Snack servieren, pur oder mit einem Löffel Joghurt, das süße Fleisch mit dem Löffel aus der Schale holen.',
      pt:'Aqueça o forno a 200°C. Corte a abóbora em fatias grossas de cerca de dois centímetros, retire as sementes e o centro fibroso, mas deixe a casca — amolece e facilita manusear as fatias. Disponha as fatias num tabuleiro forrado, polvilhe com o açúcar, a canela e uma pitada mínima de sal para realçar a doçura. Leve ao forno cerca de 35 minutos, virando uma vez, até a polpa ficar totalmente macia e as pontas caramelizadas. A abóbora coze no seu próprio vapor, por isso não precisa de óleo. Sirva quente como sobremesa ou lanche, simples ou com uma colher de iogurte, retirando a polpa doce da casca com a colher.',
      ru:'Разогрейте духовку до 200°C. Нарежьте тыкву толстыми ломтями около двух сантиметров, удалите семена и волокнистую сердцевину, но оставьте кожуру — она размягчается и делает ломти удобными. Выложите ломти на застеленный противень, посыпьте сахаром, корицей и крошечной щепоткой соли, которая подчеркнёт сладость. Запекайте около 35 минут, перевернув один раз, пока мякоть не станет совсем мягкой, а края не карамелизуются. Тыква готовится на собственном пару, так что масло не нужно. Подавайте тёплой как десерт или закуску, саму по себе или с ложкой йогурта, выбирая сладкую мякоть из кожуры ложкой.',
      ar:'سخّن الفرن إلى 200 درجة مئوية. قطّع اليقطين شرائح سميكة نحو سنتيمترين، أزل البذور واللبّ الليفي، لكن اترك القشرة — فهي تلين وتجعل الشرائح سهلة التناول. رتّب الشرائح في صينية مبطّنة، انثر السكر والقرفة ورشة ملح صغيرة جداً تُبرز الحلاوة. اخبزها نحو 35 دقيقة مع قلبها مرة، حتى يلين اللبّ تماماً وتتكرمل الحواف. يطهو اليقطين ببخار رطوبته الذاتية، فلا حاجة للزيت. قدّمه دافئاً كحلوى أو وجبة خفيفة، وحده أو مع ملعقة لبن، تُخرج اللبّ الحلو من القشرة بالملعقة.',
      zh:'烤箱预热到200°C。把南瓜切成约两厘米厚的片，去籽去掉纤维状的瓤，但保留外皮——皮会变软，也便于拿取。将南瓜片铺在垫纸的烤盘上，撒上糖、肉桂和极少的一撮盐来提升甜味。烤约35分钟，中途翻一次，至果肉完全软糯、边缘焦糖化。南瓜靠自身水分蒸熟，无需用油。趁热作甜点或零食食用，可单吃或配一勺酸奶，用勺从皮上舀出香甜的果肉。',
      ja:'オーブンを200°Cに予熱する。かぼちゃを約2センチ厚に切り、種とわたを取り除くが皮は残す——皮は柔らかくなり、扱いやすくしてくれる。天板に紙を敷いて並べ、砂糖、シナモン、そして甘さを引き立てるごく少量の塩をふる。約35分、一度返しながら、果肉が完全に柔らかく縁がカラメル化するまで焼く。かぼちゃは自身の水分で蒸されるので油は不要。温かいうちにデザートやおやつとしてそのまま、あるいはヨーグルトを添え、甘い果肉を皮からスプーンですくって供する。',
      hi:'ओवन को 200°C पर गरम करें। कद्दू को लगभग दो सेंटीमीटर मोटी फाँकों में काटें, बीज और रेशेदार गूदा निकालें, पर छिलका रहने दें — यह नरम होकर फाँकों को संभालना आसान बनाता है। फाँकों को कागज़ बिछी ट्रे पर रखें, चीनी, दालचीनी और मिठास उभारने के लिए एक बहुत छोटी चुटकी नमक छिड़कें। लगभग 35 मिनट, एक बार पलटते हुए, बेक करें जब तक गूदा पूरी तरह नरम और किनारे कैरेमलाइज़ हो जाएँ। कद्दू अपनी ही नमी की भाप में पकता है, इसलिए तेल की ज़रूरत नहीं। गरम, मिठाई या नाश्ते के रूप में, अकेले या एक चम्मच दही के साथ परोसें, मीठे गूदे को चम्मच से छिलके से निकालते हुए।',
      tr:'Fırını 200°C’ye ısıtın. Balkabağını yaklaşık iki santim kalınlığında dilimleyin, çekirdek ve lifli iç kısmı çıkarın ama kabuğunu bırakın — yumuşar ve dilimleri tutması kolaylaşır. Dilimleri yağlı kâğıt serili tepsiye dizin, şeker, tarçın ve tatlılığı belirginleştiren çok küçük bir tutam tuz serpin. Bir kez çevirerek yaklaşık 35 dakika, iç kısmı tamamen yumuşayıp kenarları karamelize olana dek pişirin. Balkabağı kendi neminin buharıyla piştiği için yağa gerek yoktur. Sıcak, tatlı ya da atıştırmalık olarak, sade veya bir kaşık yoğurtla, tatlı içini kabuğundan kaşıkla alarak servis edin.',
      it:'Scalda il forno a 200°C. Taglia la zucca a fette spesse circa due centimetri, togli i semi e la parte filamentosa centrale, ma lascia la buccia — si ammorbidisce e rende le fette facili da maneggiare. Disponi le fette su una teglia foderata, cospargi con lo zucchero, la cannella e un pizzico minimo di sale per esaltare la dolcezza. Inforna per circa 35 minuti, girando una volta, finché la polpa è del tutto morbida e i bordi si sono caramellati. La zucca cuoce al vapore della propria umidità, quindi non serve olio. Servi calda come dessert o spuntino, da sola o con un cucchiaio di yogurt, prelevando la polpa dolce dalla buccia con il cucchiaio.',
      ko:'오븐을 200°C로 예열한다. 단호박을 약 2센티미터 두께로 두툼하게 썰어 씨와 섬유질 속을 파내되 껍질은 남긴다 — 껍질은 부드러워지고 조각을 다루기 쉽게 해준다. 유산지를 깐 팬에 조각을 올리고 설탕, 계피, 그리고 단맛을 살릴 아주 약간의 소금을 뿌린다. 한 번 뒤집으며 약 35분, 속이 완전히 부드러워지고 가장자리가 캐러멜화될 때까지 굽는다. 단호박은 자체 수분의 김으로 익으므로 기름이 필요 없다. 따뜻하게 디저트나 간식으로, 그대로 또는 요구르트 한 술을 곁들여, 달콤한 속살을 숟가락으로 껍질에서 떠서 낸다.' } },

  { id:'budget_034', name:NAMES.arpacas, servings:2, prep:10, cook:40, costRon:3, nut:{cal:380,prot:10,carb:70,fat:9,fib:14}, tags:['budget','vegan','family'],
    ing:[ {q:200,u:'g',n:I.barley}, {q:1,n:I.onion}, {q:1,n:I.carrot}, {q:3,u:'tbsp',n:I.oil}, {q:100,u:'g',n:I.passata}, {q:500,u:'ml',n:I.water}, {n:I.salt} ],
    steps:{
      ro:'Clătește arpacașul sub apă rece până curge limpede. Încălzește uleiul într-o oală și călește ceapa tocată și morcovul ras la foc mediu circa 6 minute, până se înmoaie. Adaugă roșiile pasate și gătește 2 minute, apoi pune arpacașul și amestecă-l în ulei un minut. Toarnă apa fierbinte cu un praf bun de sare, dă în clocot, apoi acoperă și fierbe la foc mic circa 40 de minute, amestecând din când în când și mai adăugând puțină apă dacă o bea pe toată — arpacașul e mai însetat și mai lent decât orezul. E gata când boabele sunt umflate și fragede, cu o mușcătură plăcută. Lasă-l 5 minute luat de pe foc, potrivește de sare și servește cald, ca fel consistent sau ca garnitură.',
      en:'Rinse the pearl barley under cold water until it runs clear. Warm the oil in a pot and cook the chopped onion and grated carrot over medium heat for about 6 minutes, until soft. Stir in the tomato passata and cook for 2 minutes, then add the barley and turn it in the oil for a minute. Pour in the hot water with a good pinch of salt, bring to a simmer, then cover and cook on low heat for about 40 minutes, stirring now and then and adding a little more water if it drinks it all — barley is thirstier and slower than rice. It is ready when the grains are plump and tender with a pleasant chew. Rest it off the heat for 5 minutes, adjust the salt, and serve warm as a hearty main or a side.',
      es:'Enjuaga la cebada perlada bajo agua fría hasta que salga clara. Calienta el aceite en una olla y sofríe la cebolla picada y la zanahoria rallada a fuego medio unos 6 minutos, hasta que ablanden. Añade el tomate triturado y cocina 2 minutos, luego incorpora la cebada y remuévela en el aceite un minuto. Vierte el agua caliente con una buena pizca de sal, lleva a hervor, tapa y cuece a fuego bajo unos 40 minutos, removiendo de vez en cuando y añadiendo un poco más de agua si se la bebe toda — la cebada es más sedienta y lenta que el arroz. Está lista cuando los granos están hinchados y tiernos con un mordisco agradable. Déjala reposar 5 minutos fuera del fuego, ajusta la sal y sirve caliente como plato contundente o guarnición.',
      fr:'Rincez l’orge perlé à l’eau froide jusqu’à ce qu’elle soit claire. Chauffez l’huile dans une casserole et faites revenir l’oignon haché et la carotte râpée à feu moyen environ 6 minutes, jusqu’à ce qu’ils soient tendres. Ajoutez les tomates passées et poursuivez 2 minutes, puis ajoutez l’orge et remuez-le dans l’huile une minute. Versez l’eau chaude avec une bonne pincée de sel, portez à frémissement, couvrez et laissez cuire à feu doux environ 40 minutes, en remuant de temps en temps et en ajoutant un peu d’eau s’il l’absorbe entièrement — l’orge est plus gourmand en eau et plus lent que le riz. C’est prêt quand les grains sont gonflés et tendres avec une mâche agréable. Laissez reposer 5 minutes hors du feu, rectifiez le sel et servez chaud en plat consistant ou en accompagnement.',
      de:'Die Graupen unter kaltem Wasser abspülen, bis es klar läuft. Das Öl in einem Topf erwärmen und die gehackte Zwiebel und die geriebene Karotte bei mittlerer Hitze etwa 6 Minuten weich dünsten. Passierte Tomaten einrühren und 2 Minuten kochen, dann die Graupen zugeben und eine Minute im Öl wenden. Das heiße Wasser mit einer guten Prise Salz angießen, aufkochen, dann zugedeckt bei niedriger Hitze etwa 40 Minuten garen, ab und zu umrühren und etwas Wasser nachgießen, falls alles aufgesogen wird — Graupen sind durstiger und langsamer als Reis. Sie sind fertig, wenn die Körner prall und zart mit angenehmem Biss sind. Vom Herd genommen 5 Minuten ruhen lassen, mit Salz abschmecken und warm als kräftiges Hauptgericht oder Beilage servieren.',
      pt:'Enxágue a cevada em água fria até sair limpa. Aqueça o óleo numa panela e refogue a cebola picada e a cenoura ralada em lume médio cerca de 6 minutos, até amolecerem. Junte o tomate passata e cozinhe 2 minutos, depois adicione a cevada e envolva-a no óleo um minuto. Deite a água quente com uma boa pitada de sal, leve a fervura, tape e cozinhe em lume brando cerca de 40 minutos, mexendo de vez em quando e juntando um pouco mais de água se a beber toda — a cevada é mais sedenta e lenta do que o arroz. Está pronta quando os grãos estão inchados e tenros com uma mordida agradável. Deixe repousar 5 minutos fora do lume, acerte o sal e sirva quente como prato substancial ou acompanhamento.',
      ru:'Промойте перловку под холодной водой, пока она не станет прозрачной. Разогрейте масло в кастрюле и обжарьте нарезанный лук и натёртую морковь на среднем огне около 6 минут, до мягкости. Вмешайте протёртые томаты и готовьте 2 минуты, затем добавьте перловку и минуту помешивайте в масле. Влейте горячую воду с хорошей щепоткой соли, доведите до кипения, накройте и готовьте на слабом огне около 40 минут, изредка помешивая и подливая немного воды, если она вся впитается, — перловка «пьёт» больше и готовится дольше риса. Она готова, когда зёрна набухли и стали нежными с приятной упругостью. Дайте постоять 5 минут, снятой с огня, посолите по вкусу и подавайте тёплой как сытное блюдо или гарнир.',
      ar:'اشطف الشعير المقشور تحت الماء البارد حتى يصفو. سخّن الزيت في قدر وشوّح البصل المفروم والجزر المبشور على نار متوسطة نحو 6 دقائق حتى يلين. أضف الطماطم المهروسة واطهها دقيقتين، ثم أضف الشعير وقلّبه في الزيت دقيقة. أضف الماء الساخن مع رشة ملح جيدة، ارفعه للغليان، ثم غطّه واطهه على نار هادئة نحو 40 دقيقة مع التقليب بين الحين والآخر وإضافة قليل من الماء إن شربه كله — فالشعير أكثر تعطّشاً وأبطأ من الأرز. يجهز حين تنتفخ الحبوب وتلين مع قضمة لطيفة. اتركه 5 دقائق بعد رفعه عن النار، اضبط الملح وقدّمه دافئاً كطبق مشبع أو جانبي.',
      zh:'把大麦用冷水冲洗到水清。锅中热油，中火将切碎的洋葱和擦丝的胡萝卜煸软约6分钟。加入番茄泥炒2分钟，再放入大麦，在油中翻拌1分钟。倒入加了一大撮盐的热水，煮开后加盖，用小火煮约40分钟，中途翻动，若水被吸干就再加一点——大麦比米更“喝水”、也更慢熟。煮到麦粒饱满软糯、口感有嚼劲即成。离火焖5分钟，调盐，趁热作为顶饱的主食或配菜食用。',
      ja:'大麦を冷水で澄むまで洗う。鍋に油を温め、みじん切りの玉ねぎとすりおろしたにんじんを中火で約6分やわらかくなるまで炒める。トマトピューレを加えて2分煮て、大麦を入れ1分ほど油をまとわせる。塩ひとつまみを加えた熱湯を注ぎ、煮立ったらふたをして弱火で約40分、時々混ぜ、水を吸い切ったら少し足しながら煮る——大麦は米より水を欲しがり、火の通りも遅い。粒がふっくら柔らかく、心地よい歯ごたえになれば出来上がり。火を止めて5分蒸らし、塩で調え、食べ応えのある主菜または付け合わせとして温かいうちに供する。',
      hi:'जौ को ठंडे पानी में तब तक धोएँ जब तक पानी साफ न निकले। बर्तन में तेल गरम करें और कटा प्याज़ व कद्दूकस गाजर मध्यम आँच पर लगभग 6 मिनट नरम होने तक भूनें। टमाटर प्यूरी डालकर 2 मिनट पकाएँ, फिर जौ डालकर एक मिनट तेल में मिलाएँ। एक अच्छी चुटकी नमक के साथ गरम पानी डालें, उबाल लाएँ, फिर ढककर धीमी आँच पर लगभग 40 मिनट पकाएँ, बीच-बीच में चलाते हुए और सारा पानी सूखने पर थोड़ा और डालते हुए — जौ चावल से ज़्यादा पानी पीता और धीरे पकता है। जब दाने फूले और नरम हों, पर हल्का चबाने वाला हो, तब तैयार है। आँच से उतारकर 5 मिनट रखें, नमक ठीक करें और गरम, एक भरपूर मुख्य व्यंजन या साथ के रूप में परोसें।',
      tr:'Arpayı soğuk suyun altında berraklaşana dek yıkayın. Tencerede yağı ısıtın ve doğranmış soğan ile rendelenmiş havucu orta ateşte yaklaşık 6 dakika yumuşayana dek kavurun. Domates püresini ekleyip 2 dakika pişirin, sonra arpayı ekleyip bir dakika yağda çevirin. İyi bir tutam tuzla sıcak suyu ekleyin, kaynamaya getirin, sonra kapağını kapatıp kısık ateşte yaklaşık 40 dakika, ara sıra karıştırıp suyunu tümüyle çekerse biraz daha ekleyerek pişirin — arpa pirinçten daha çok su ister ve daha yavaş pişer. Taneler şişip yumuşadığında, hoş bir diş dokunuşuyla hazırdır. Ocaktan alıp 5 dakika dinlendirin, tuzu ayarlayın ve doyurucu bir ana yemek ya da garnitür olarak sıcak servis edin.',
      it:'Sciacqua l’orzo perlato sotto acqua fredda finché esce limpida. Scalda l’olio in una pentola e fai rosolare la cipolla tritata e la carota grattugiata a fuoco medio per circa 6 minuti, finché sono morbide. Unisci la passata e cuoci 2 minuti, poi aggiungi l’orzo e giralo nell’olio un minuto. Versa l’acqua calda con una buona presa di sale, porta a sobbollore, copri e cuoci a fuoco basso per circa 40 minuti, mescolando ogni tanto e aggiungendo un po’ d’acqua se la beve tutta — l’orzo è più assetato e lento del riso. È pronto quando i chicchi sono gonfi e teneri con una masticabilità piacevole. Fallo riposare 5 minuti fuori dal fuoco, regola il sale e servi caldo come piatto sostanzioso o contorno.',
      ko:'보리를 찬물에 맑아질 때까지 헹군다. 냄비에 기름을 데우고 다진 양파와 채 썬 당근을 중불에서 약 6분간 부드러워질 때까지 볶는다. 토마토 퓌레를 넣어 2분 볶고 보리를 넣어 1분간 기름에 버무린다. 소금 넉넉히 한 꼬집을 넣은 뜨거운 물을 붓고 끓어오르면 뚜껑을 덮어 약불에서 약 40분, 이따금 저으며 물을 다 먹으면 조금씩 더 부어가며 익힌다 — 보리는 쌀보다 물을 더 먹고 더 천천히 익는다. 알이 통통하고 부드러우면서 기분 좋은 씹힘이 있으면 다 된 것이다. 불에서 내려 5분 뜸을 들이고 간을 맞춰, 든든한 주요리나 곁들이로 따뜻하게 낸다.' } },

  { id:'budget_035', name:NAMES.ardeiCopti, servings:2, prep:10, cook:20, costRon:3, nut:{cal:180,prot:3,carb:14,fat:13,fib:4}, tags:['budget','vegan','healthy'],
    ing:[ {q:600,u:'g',n:I.bellPepper}, {q:3,u:'clove',n:I.garlic}, {q:3,u:'tbsp',n:I.oil}, {q:1,u:'tbsp',n:I.vinegar}, {n:I.salt} ],
    steps:{
      ro:'Coace ardeii întregi pe flacăra aragazului, sub grill sau în cuptor încins, întorcându-i până coaja e înnegrită și băşicată peste tot. Pune-i într-un bol și acoperă-l, sau închide-i într-o pungă, și lasă-i să se aburească 10 minute — asta desprinde coaja. Curăță coaja arsă cu degetele, scoate cotorul și semințele și rupe pulpa în fâșii late, păstrând zeama lăsată. Amestecă usturoiul zdrobit, uleiul, oțetul și un praf bun de sare într-un dressing rapid. Amestecă ardeii ușor în dressing și lasă-i cel puțin 15 minute, ca aromele să pătrundă. Servește la temperatura camerei, ca aperitiv sau garnitură, cu pâine cu care să iei zeama.',
      en:'Roast the whole peppers over a gas flame, under the grill or in a hot oven, turning them until the skins are blackened and blistered all over. Put them in a bowl and cover it, or seal them in a bag, and let them steam for 10 minutes — this loosens the skins. Peel off the charred skins with your fingers, pull out the stalk and seeds, and tear the flesh into wide strips, saving any juices. Mix the crushed garlic, the oil, the vinegar and a good pinch of salt into a quick dressing. Toss the peppers gently in the dressing and let them sit for at least 15 minutes so the flavours soak in. Serve at room temperature as a starter or side, with bread to mop up the juices.',
      es:'Asa los pimientos enteros sobre la llama del gas, bajo el grill o en el horno caliente, girándolos hasta que la piel esté ennegrecida y ampollada por todas partes. Ponlos en un bol y tápalo, o ciérralos en una bolsa, y déjalos sudar 10 minutos — esto afloja la piel. Pela la piel quemada con los dedos, retira el tallo y las semillas y desgarra la pulpa en tiras anchas, guardando los jugos. Mezcla el ajo machacado, el aceite, el vinagre y una buena pizca de sal en un aliño rápido. Mezcla los pimientos con suavidad en el aliño y déjalos al menos 15 minutos para que se impregnen los sabores. Sirve a temperatura ambiente como entrante o guarnición, con pan para rebañar los jugos.',
      fr:'Faites griller les poivrons entiers sur la flamme du gaz, sous le gril ou au four chaud, en les tournant jusqu’à ce que la peau soit noircie et boursouflée partout. Mettez-les dans un bol et couvrez-le, ou fermez-les dans un sac, et laissez-les suer 10 minutes — cela décolle la peau. Pelez la peau brûlée avec les doigts, retirez le pédoncule et les graines, et déchirez la chair en larges lanières, en gardant le jus. Mélangez l’ail écrasé, l’huile, le vinaigre et une bonne pincée de sel en une vinaigrette rapide. Mélangez délicatement les poivrons à la vinaigrette et laissez reposer au moins 15 minutes pour que les saveurs pénètrent. Servez à température ambiante en entrée ou en accompagnement, avec du pain pour saucer.',
      de:'Die ganzen Paprika über der Gasflamme, unter dem Grill oder im heißen Ofen rösten, dabei wenden, bis die Haut rundum geschwärzt und Blasen geworfen hat. In eine Schüssel geben und abdecken oder in einem Beutel verschließen und 10 Minuten dämpfen lassen — das löst die Haut. Die verkohlte Haut mit den Fingern abziehen, Strunk und Kerne entfernen und das Fruchtfleisch in breite Streifen zupfen, den austretenden Saft auffangen. Den zerdrückten Knoblauch, das Öl, den Essig und eine gute Prise Salz zu einem schnellen Dressing verrühren. Die Paprika sanft im Dressing wenden und mindestens 15 Minuten ziehen lassen, damit die Aromen einziehen. Bei Zimmertemperatur als Vorspeise oder Beilage servieren, mit Brot zum Auftunken des Safts.',
      pt:'Asse os pimentos inteiros sobre a chama do gás, no grelhador ou no forno quente, virando-os até a pele ficar enegrecida e empolada por todo o lado. Coloque-os numa tigela e tape, ou feche-os num saco, e deixe suar 10 minutos — isto solta a pele. Descasque a pele queimada com os dedos, retire o pé e as sementes, e rasgue a polpa em tiras largas, guardando os sucos. Misture o alho esmagado, o azeite, o vinagre e uma boa pitada de sal num tempero rápido. Envolva os pimentos com suavidade no tempero e deixe pelo menos 15 minutos para os sabores penetrarem. Sirva à temperatura ambiente como entrada ou acompanhamento, com pão para limpar os sucos.',
      ru:'Запеките целые перцы над газовым пламенем, под грилем или в горячей духовке, поворачивая, пока кожица не почернеет и не покроется пузырями со всех сторон. Положите их в миску и накройте или закройте в пакете и дайте пропариться 10 минут — так кожица легче снимется. Снимите обугленную кожицу пальцами, удалите плодоножку и семена и разорвите мякоть на широкие полоски, сохраняя сок. Смешайте раздавленный чеснок, масло, уксус и хорошую щепотку соли в быструю заправку. Аккуратно перемешайте перцы с заправкой и дайте постоять хотя бы 15 минут, чтобы вкусы впитались. Подавайте комнатной температуры как закуску или гарнир, с хлебом, чтобы собрать сок.',
      ar:'اشوِ الفلفل كاملاً على لهب الغاز أو تحت الشوّاية أو في فرن ساخن، مع تقليبه حتى يسودّ القشر ويتنفّط من كل جانب. ضعه في وعاء وغطّه، أو أغلقه في كيس، واتركه يتبخّر 10 دقائق — هذا يفكّ القشر. قشّر الجلد المتفحّم بأصابعك، أزل العنق والبذور، ومزّق اللبّ إلى شرائح عريضة محتفظاً بالعصارة. اخلط الثوم المهروس والزيت والخل ورشة ملح جيدة في صلصة سريعة. قلّب الفلفل برفق في الصلصة واتركه 15 دقيقة على الأقل كي تتغلغل النكهات. قدّمه بحرارة الغرفة كمقبّل أو طبق جانبي، مع خبز تجمع به العصارة.',
      zh:'把整只甜椒放在燃气火上、烤架下或热烤箱中烤，不断翻动，直到表皮四面焦黑起泡。放入碗中盖好，或装进袋子密封，焖10分钟——这样皮易剥。用手指剥去焦皮，去蒂去籽，把果肉撕成宽条，保留流出的汁。把压碎的蒜、油、醋和一大撮盐调成快手汁。将甜椒轻轻拌入调味汁，静置至少15分钟让味道渗入。常温作为前菜或配菜食用，配面包蘸汁。',
      ja:'パプリカを丸ごとガスの直火、グリル、または高温のオーブンで、皮が全体に黒く焦げて膨れるまで返しながら焼く。ボウルに入れて覆うか袋に入れて密封し、10分蒸らす——こうすると皮がむけやすくなる。焦げた皮を指でむき、ヘタと種を取り、果肉を幅広に裂いて、出た汁は取っておく。つぶしたにんにく、油、酢、塩ひとつまみを混ぜて手早くドレッシングを作る。パプリカをドレッシングでやさしくあえ、味がなじむよう最低15分置く。常温で前菜や付け合わせとして、汁を拭うパンを添えて供する。',
      hi:'शिमला मिर्च को साबुत, गैस की लौ पर, ग्रिल के नीचे या गरम ओवन में भूनें, पलटते हुए जब तक छिलका चारों ओर काला और फफोलेदार हो जाए। इन्हें कटोरे में रखकर ढँक दें, या थैले में बंद कर दें, और 10 मिनट भाप में छोड़ें — इससे छिलका ढीला हो जाता है। जला छिलका उँगलियों से उतारें, डंठल और बीज निकालें, और गूदे को चौड़ी पट्टियों में फाड़ें, रस बचाकर। कुचला लहसुन, तेल, सिरका और एक अच्छी चुटकी नमक मिलाकर एक झटपट ड्रेसिंग बनाएँ। शिमला मिर्च को ड्रेसिंग में हल्के से मिलाएँ और कम से कम 15 मिनट रखें ताकि स्वाद समा जाए। कमरे के तापमान पर, स्टार्टर या साथ के रूप में, रस सोखने के लिए ब्रेड के साथ परोसें।',
      tr:'Biberleri bütün hâlde ocak alevinde, ızgara altında ya da sıcak fırında, kabukları her yanı kararıp kabarana dek çevirerek közleyin. Bir kaseye alıp üzerini örtün ya da bir poşete kapatın ve 10 dakika buğulanmaya bırakın — bu kabuğu gevşetir. Yanmış kabuğu parmaklarınızla soyun, sap ve çekirdekleri çıkarın, eti geniş şeritler hâlinde yırtın, çıkan suyu saklayın. Ezilmiş sarımsak, yağ, sirke ve iyi bir tutam tuzu hızlı bir sosta karıştırın. Biberleri sosun içinde nazikçe harmanlayın ve tatların sinmesi için en az 15 dakika bekletin. Oda sıcaklığında, meze ya da garnitür olarak, suyunu almak için ekmekle servis edin.',
      it:'Arrostisci i peperoni interi sulla fiamma del gas, sotto il grill o in forno caldo, girandoli finché la pelle è annerita e piena di bolle ovunque. Mettili in una ciotola e coprila, o chiudili in un sacchetto, e falli sudare 10 minuti — così la pelle si stacca. Pela la pelle bruciata con le dita, togli il picciolo e i semi e strappa la polpa in larghe strisce, tenendo da parte il succo. Mescola l’aglio schiacciato, l’olio, l’aceto e una buona presa di sale in un condimento veloce. Condisci i peperoni delicatamente e lasciali riposare almeno 15 minuti perché i sapori si assorbano. Servi a temperatura ambiente come antipasto o contorno, con pane per raccogliere il succo.',
      ko:'파프리카를 통째로 가스 불, 그릴 아래, 또는 뜨거운 오븐에서 껍질이 사방으로 새까맣게 그을려 부풀 때까지 돌려가며 굽는다. 그릇에 담아 덮거나 봉지에 밀봉해 10분간 김을 들인다 — 이렇게 하면 껍질이 잘 벗겨진다. 탄 껍질을 손으로 벗기고 꼭지와 씨를 빼낸 뒤 살을 넓게 찢고, 나온 즙은 남겨둔다. 으깬 마늘, 기름, 식초, 소금 넉넉히 한 꼬집을 섞어 간단한 드레싱을 만든다. 파프리카를 드레싱에 살살 버무려 맛이 배도록 최소 15분 둔다. 실온에서 전채나 곁들이로, 즙을 찍어 먹을 빵과 함께 낸다.' } },
];

const recipes = SPECS.map(mk);

export { recipes };
export default recipes;
export const BUDGET_RECIPES = recipes;

if (typeof window !== 'undefined') {
  window.BUDGET_RECIPES = recipes;
}
